-- SOURCE STAGED ONLY. Root must integrate exact cold descriptors, compiler and SDK,
-- and independently verify on a fresh coherent Native202 build before installation.
-- No policy/identity/accounting/expiry guard bypass. Existing 173 writes stay literal.
CREATE FUNCTION ordinary187_private.renewal_context202(root0 text,t uuid,u uuid) RETURNS ordinary187_private.contexts
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,ordinary187_private SET TimeZone='UTC' AS $context202$
DECLARE x ordinary187_private.contexts%ROWTYPE;e ordinary187_private.journal%ROWTYPE;o ordinary187_private.journal%ROWTYPE;m ordinary187_private.journal%ROWTYPE;s timestamptz;keys0 integer[];
BEGIN
 IF session_user<>'postgres' OR current_setting('role',true)<>'dyna_app' OR current_setting('session_replication_role')<>'origin'
 OR current_setting('transaction_isolation')<>'read committed' OR current_setting('transaction_read_only')<>'off'
 OR root0 IS NULL OR root0 !~ '^[a-f0-9]{64}$' OR t IS NULL OR u IS NULL
 OR nullif(current_setting('app.tenant_id',true),'')::uuid IS DISTINCT FROM t
 THEN RAISE EXCEPTION '202 exact current original app worker' USING ERRCODE='42501';END IF;
 PERFORM public.ordinary182_require_generation();
 keys0:=ARRAY[(('x'||substr(root0,1,8))::bit(32))::integer,(('x'||substr(root0,9,8))::bit(32))::integer];
 -- SAME worker owns root exclusion, not a different companion that its entry
 -- would block behind. No attempt to upgrade a conflicting shared root lock.
 IF NOT EXISTS(SELECT FROM pg_locks WHERE locktype='advisory' AND pid=pg_backend_pid()
 AND database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND mode='ExclusiveLock' AND granted
 AND objsubid=2 AND classid::bigint=(keys0[1]::bigint&4294967295) AND objid::bigint=(keys0[2]::bigint&4294967295))
 OR NOT EXISTS(SELECT FROM pg_locks WHERE locktype='advisory' AND pid=pg_backend_pid()
 AND database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND mode IN('ShareLock','ExclusiveLock') AND granted
 AND objsubid=1 AND classid=0 AND objid=982376)
 THEN RAISE EXCEPTION '202 same worker exclusive root and current schema lease' USING ERRCODE='42501';END IF;
 SELECT backend_start INTO STRICT s FROM pg_stat_activity WHERE pid=pg_backend_pid() AND datname=current_database() AND usename='postgres';
 SELECT * INTO STRICT x FROM ordinary187_private.contexts WHERE(backend_pid,backend_start,xid)=(pg_backend_pid(),s,pg_current_xact_id());
 IF(x.root_key,x.tenant_id,x.actor_id,x.api_key_id,x.mode) IS DISTINCT FROM(root0,t,u,NULL::uuid,'growth'::text)
 THEN RAISE EXCEPTION '202 same normal owner growth187 context' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT e FROM ordinary187_private.journal WHERE(root_key,epoch,kind)=(x.root_key,x.epoch,'epoch') FOR SHARE;
 SELECT * INTO STRICT o FROM ordinary187_private.journal WHERE(root_key,epoch,id,kind)=(x.root_key,x.epoch,x.original_id,'original');
 SELECT * INTO STRICT m FROM ordinary187_private.journal WHERE(root_key,epoch,id,kind)=(x.root_key,x.epoch,x.member_id,'member');
 IF e.payload_text::jsonb->>'state' IS DISTINCT FROM 'OPEN' OR e.payload_text::jsonb->'keys' IS DISTINCT FROM to_jsonb(keys0)
 OR o.payload_text::jsonb->>'state' IS DISTINCT FROM 'OPEN'
 OR(o.tenant_id,o.actor_id,o.api_key_id) IS DISTINCT FROM(t,u,NULL::uuid)
 OR(m.tenant_id,m.actor_id,m.api_key_id) IS DISTINCT FROM(t,u,NULL::uuid)
 OR m.payload_text::jsonb->>'state' IS DISTINCT FROM 'ACTIVE' OR m.payload_text::jsonb->>'mode' IS DISTINCT FROM 'growth'
 OR(m.payload_text::jsonb->>'original_id')::uuid IS DISTINCT FROM x.original_id
 OR(m.payload_text::jsonb->>'backend_pid')::integer IS DISTINCT FROM pg_backend_pid()
 OR(m.payload_text::jsonb->>'backend_start')::timestamptz IS DISTINCT FROM s
 OR(m.payload_text::jsonb->>'xid')::xid8 IS DISTINCT FROM x.xid OR pg_xact_status(x.xid) IS DISTINCT FROM 'in progress'
 OR NOT EXISTS(SELECT FROM pg_stat_activity p WHERE p.pid=(o.payload_text::jsonb->>'parent_pid')::integer
 AND p.backend_start=(o.payload_text::jsonb->>'parent_start')::timestamptz AND p.datname=current_database() AND p.usename='postgres')
 THEN RAISE EXCEPTION '202 genuine live original and active exact member' USING ERRCODE='42501';END IF;
 RETURN x;
END $context202$;
REVOKE ALL ON FUNCTION ordinary187_private.renewal_context202(text,uuid,uuid) FROM PUBLIC,dyna_app;

CREATE FUNCTION ordinary187_private.quota_pair_preview202(u uuid,t uuid,k uuid,r text,h text,root0 text,job0 uuid,catalog0 uuid,jq uuid,jrequest uuid,jtoken text,rq uuid,rrequest uuid,rtoken text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,ordinary187_private SET TimeZone='UTC' AS $inspect202$
DECLARE j public.large_import_jobs173%ROWTYPE;b public.large_import_quota_reservations173%ROWTYPE;v public.large_import_quota_reservations173%ROWTYPE;n jsonb;now0 timestamptz;ttl integer;reason0 text:='eligible';q0 uuid;
BEGIN
 IF k IS NOT NULL OR r IS DISTINCT FROM 'admin' OR root0 IS NULL OR root0 !~ '^[a-f0-9]{64}$'
 OR job0 IS NULL OR catalog0 IS NULL OR jq IS NULL OR rq IS NULL OR jq=rq OR jrequest IS NULL OR rrequest IS NULL OR jrequest=rrequest
 OR jtoken IS NULL OR rtoken IS NULL OR jtoken !~ '^[a-f0-9]{64}$' OR rtoken !~ '^[a-f0-9]{64}$' OR jtoken=rtoken
 THEN RAISE EXCEPTION '202 normal admin exact distinct pair shape' USING ERRCODE='42501';END IF;
 PERFORM public.large_import_quota_authorize173(u,t,k,r,h);
 -- Global -> tenant -> rows. Both policy rows stay pinned through Source FS check.
 SELECT lease_seconds INTO STRICT ttl FROM public.large_import_quota_policies173 WHERE scope='tenant:'||t::text;
 IF ttl NOT BETWEEN 30 AND 86400 THEN RAISE EXCEPTION '202 current bounded policy TTL' USING ERRCODE='23514';END IF;
 PERFORM 1 FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id IN(jq,rq) ORDER BY id FOR UPDATE;
 SELECT * INTO STRICT b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=jq;
 SELECT * INTO STRICT v FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=rq;
 IF(b.actor_id,b.api_key_id,b.request_id,b.token_hash,b.kind,b.raw_ceiling) IS DISTINCT FROM(u,NULL::uuid,jrequest,jtoken,'job'::text,0::bigint)
 OR(v.actor_id,v.api_key_id,v.request_id,v.token_hash,v.kind,v.raw_ceiling) IS DISTINCT FROM(u,NULL::uuid,rrequest,rtoken,'review'::text,0::bigint)
 THEN RAISE EXCEPTION '202 exact original pair ownership token request kind' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT j FROM public.large_import_jobs173 WHERE tenant_id=t AND id=job0 AND actor_id=u AND api_key_id IS NULL FOR SHARE;
 n:=j.state_text::jsonb;
 IF n->>'schema' IS DISTINCT FROM 'large-import-job/v1' OR(n->>'id')::uuid IS DISTINCT FROM job0
 OR(n#>>'{principal,tenantId}')::uuid IS DISTINCT FROM t OR(n#>>'{principal,userId}')::uuid IS DISTINCT FROM u OR n#>>'{principal,apiKeyId}' IS NOT NULL
 OR encode(sha256(convert_to(j.state_text,'UTF8')),'hex') IS DISTINCT FROM j.state_sha256
 OR jsonb_typeof(n->'core') IS DISTINCT FROM 'array' OR jsonb_array_length(n->'core') NOT BETWEEN 1 AND 100000
 OR EXISTS(SELECT FROM jsonb_array_elements(n->'core') c WHERE(c#>>'{request,catalog_id}')::uuid IS DISTINCT FROM catalog0)
 THEN RAISE EXCEPTION '202 exact current job and catalog' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id IN(jq,rq) ORDER BY reservation_id,resource_key COLLATE "C" FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=jq AND resource_key='job:'||job0::text||':initial' AND kind='job')
 OR NOT EXISTS(SELECT FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=rq AND resource_key ~ ('^review:'||job0::text||':[0-9]+$') AND kind='review')
 THEN RAISE EXCEPTION '202 exact Native job review pair custody' USING ERRCODE='42501';END IF;
 now0:=clock_timestamp();
 IF b.state<>'open' OR v.state<>'open' OR b.outcome IS NOT NULL OR v.outcome IS NOT NULL THEN reason0:='pair_not_open';
 ELSIF b.expires_at>now0 OR v.expires_at>now0 THEN reason0:='pair_not_expired';
 ELSIF j.lease_token IS NOT NULL OR j.leased_at IS NOT NULL THEN reason0:='job_lease_active';
 ELSIF EXISTS(SELECT FROM jsonb_array_elements(n->'core') c WHERE c->'execution' IS NULL OR c->'execution'='null'::jsonb)
 OR EXISTS(SELECT FROM jsonb_each(n->'pim') z CROSS JOIN LATERAL jsonb_array_elements(z.value) p
 WHERE(p->>'previewAttempted'='true' AND(p->'preview' IS NULL OR p->'preview'='null'::jsonb))
 OR(p->>'applyAttempted'='true' AND(p->'applied' IS NULL OR p->'applied'='null'::jsonb))) THEN reason0:='business_outcome_unknown';
 ELSIF EXISTS(SELECT FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id IN(jq,rq) AND(state NOT IN('settled','released') OR kind='raw')) THEN reason0:='resource_not_drained';
 ELSIF EXISTS(SELECT FROM ordinary187_private.journal x WHERE x.root_key=root0 AND x.kind='io'
 AND(x.payload_text::jsonb->>'reservation_id')::uuid IN(jq,rq)
 AND((x.tenant_id,x.actor_id,x.api_key_id) IS DISTINCT FROM(t,u,NULL::uuid) OR x.payload_text::jsonb->>'state' IS DISTINCT FROM 'DRAINED')) THEN reason0:='io_not_drained';
 END IF;
 RETURN jsonb_build_object('schema','quota-expired-open-pair-preview/v1','eligible',reason0='eligible','reason',reason0,
 'native_time',to_char(now0 AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'policy_lease_seconds',ttl,'current_job_sha256',j.state_sha256,
 'job',(to_jsonb(b)-'token_hash')||jsonb_build_object('expires_at',to_char(b.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
 'review',(to_jsonb(v)-'token_hash')||jsonb_build_object('expires_at',to_char(v.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
END $inspect202$;
REVOKE ALL ON FUNCTION ordinary187_private.quota_pair_preview202(uuid,uuid,uuid,text,text,text,uuid,uuid,uuid,uuid,text,uuid,uuid,text) FROM PUBLIC,dyna_app;

CREATE FUNCTION public.ordinary202_quota_renew_preview(u uuid,t uuid,k uuid,r text,h text,root0 text,job0 uuid,catalog0 uuid,jq uuid,jrequest uuid,jtoken text,rq uuid,rrequest uuid,rtoken text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,ordinary187_private SET TimeZone='UTC' AS $preview202$
BEGIN
 RETURN ordinary187_private.quota_pair_preview202(u,t,k,r,h,root0,job0,catalog0,jq,jrequest,jtoken,rq,rrequest,rtoken);
END $preview202$;
REVOKE ALL ON FUNCTION public.ordinary202_quota_renew_preview(uuid,uuid,uuid,text,text,text,uuid,uuid,uuid,uuid,text,uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ordinary202_quota_renew_preview(uuid,uuid,uuid,text,text,text,uuid,uuid,uuid,uuid,text,uuid,uuid,text) TO dyna_app;

CREATE FUNCTION ordinary187_private.quota_renew_effect202(table0 text,op0 text,old0 jsonb,new0 jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,ordinary187_private SET TimeZone='UTC' AS $effect202$
DECLARE x ordinary187_private.contexts%ROWTYPE;p jsonb;j jsonb;v jsonb;bit0 integer;s0 integer;commit0 text;
BEGIN
 IF pg_trigger_depth()<>1 THEN RAISE EXCEPTION '202 only genuine resource trigger effect' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT x FROM ordinary187_private.contexts WHERE backend_pid=pg_backend_pid() AND xid=pg_current_xact_id();
 x:=ordinary187_private.renewal_context202(x.root_key,x.tenant_id,x.actor_id);p:=x.keeper_call;
 IF p->>'a' IS DISTINCT FROM 'n' OR table0 IS DISTINCT FROM 'large_import_quota_reservations173' OR op0 IS DISTINCT FROM 'UPDATE'
 OR old0-'expires_at' IS DISTINCT FROM new0-'expires_at' OR old0->>'state' IS DISTINCT FROM 'open' OR old0->'outcome' IS DISTINCT FROM 'null'::jsonb
 OR(old0->>'tenant_id')::uuid IS DISTINCT FROM x.tenant_id OR(old0->>'actor_id')::uuid IS DISTINCT FROM x.actor_id OR old0->'api_key_id' IS DISTINCT FROM 'null'::jsonb
 OR(new0->>'expires_at')::timestamptz IS DISTINCT FROM(p->>'t')::timestamptz OR(new0->>'expires_at')::timestamptz<=(old0->>'expires_at')::timestamptz
 OR(old0->>'expires_at')::timestamptz>clock_timestamp()
 THEN RAISE EXCEPTION '202 renewal marker permits expiry alone' USING ERRCODE='42501';END IF;
 bit0:=CASE WHEN old0->>'id'=p->>'q' AND old0->>'kind'='job' THEN 1 WHEN old0->>'id'=p->>'c' AND old0->>'kind'='review' THEN 2 ELSE 0 END;s0:=(p->>'s')::integer;
 IF bit0=0 OR(s0&bit0)<>0 OR s0 NOT BETWEEN 0 AND 3 THEN RAISE EXCEPTION '202 exact pair once only' USING ERRCODE='42501';END IF;
 SELECT to_jsonb(b)-'expires_at' INTO STRICT j FROM public.large_import_quota_reservations173 b WHERE tenant_id=x.tenant_id AND id=(p->>'q')::uuid;
 SELECT to_jsonb(b)-'expires_at' INTO STRICT v FROM public.large_import_quota_reservations173 b WHERE tenant_id=x.tenant_id AND id=(p->>'c')::uuid;
 commit0:=encode(sha256(convert_to(jsonb_build_array(j,v)::text,'UTF8')),'hex');
 IF commit0 IS DISTINCT FROM p->>'w' THEN RAISE EXCEPTION '202 exact original pair non-expiry commitment' USING ERRCODE='42501';END IF;
 UPDATE ordinary187_private.contexts SET keeper_call=jsonb_set(p,'{s}',to_jsonb(s0|bit0)) WHERE(backend_pid,backend_start,xid)=(x.backend_pid,x.backend_start,x.xid);
END $effect202$;
REVOKE ALL ON FUNCTION ordinary187_private.quota_renew_effect202(text,text,jsonb,jsonb) FROM PUBLIC,dyna_app;

CREATE FUNCTION public.ordinary202_quota_renew_pair(u uuid,t uuid,k uuid,r text,h text,root0 text,job0 uuid,catalog0 uuid,jq uuid,jrequest uuid,jtoken text,rq uuid,rrequest uuid,rtoken text,expected_job_expires_at text,expected_review_expires_at text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,ordinary187_private SET TimeZone='UTC' AS $renew202$
DECLARE x ordinary187_private.contexts%ROWTYPE;fact jsonb;j0 jsonb;r0 jsonb;j1 jsonb;r1 jsonb;p jsonb;now0 timestamptz;deadline0 timestamptz;deadline_text text;ttl integer;sha0 text;
BEGIN
 x:=ordinary187_private.renewal_context202(root0,t,u);
 IF x.keeper_call IS NOT NULL THEN RAISE EXCEPTION '202 no nested unfinished renewal marker' USING ERRCODE='42501';END IF;
 IF expected_job_expires_at IS NULL OR expected_review_expires_at IS NULL
 OR expected_job_expires_at !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
 OR expected_review_expires_at !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
 THEN RAISE EXCEPTION '202 microsecond expiry CAS shape' USING ERRCODE='22023';END IF;
 fact:=ordinary187_private.quota_pair_preview202(u,t,k,r,h,root0,job0,catalog0,jq,jrequest,jtoken,rq,rrequest,rtoken);
 IF fact->'eligible' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION '202 current pair refused: %',fact->>'reason' USING ERRCODE='55000';END IF;
 j0:=fact->'job';r0:=fact->'review';
 IF j0->>'expires_at' IS DISTINCT FROM expected_job_expires_at OR r0->>'expires_at' IS DISTINCT FROM expected_review_expires_at
 THEN RAISE EXCEPTION '202 stale exact pair expiry CAS' USING ERRCODE='40001';END IF;
 now0:=clock_timestamp();ttl:=(fact->>'policy_lease_seconds')::integer;deadline0:=now0+ttl*interval '1 second';deadline_text:=to_char(deadline0 AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
 SELECT encode(sha256(convert_to(jsonb_build_array(to_jsonb(j)-'expires_at',to_jsonb(v)-'expires_at')::text,'UTF8')),'hex') INTO STRICT sha0
 FROM public.large_import_quota_reservations173 j CROSS JOIN public.large_import_quota_reservations173 v WHERE j.tenant_id=t AND j.id=jq AND v.tenant_id=t AND v.id=rq;
 p:=jsonb_build_object('a','n','q',jq::text,'c',rq::text,'k',job0::text,'t',deadline_text,'w',sha0,'s',0);
 UPDATE ordinary187_private.contexts SET keeper_call=p WHERE(backend_pid,backend_start,xid)=(x.backend_pid,x.backend_start,x.xid);
 UPDATE public.large_import_quota_reservations173 SET expires_at=deadline0 WHERE tenant_id=t AND id=jq;
 UPDATE public.large_import_quota_reservations173 SET expires_at=deadline0 WHERE tenant_id=t AND id=rq;
 SELECT keeper_call INTO STRICT p FROM ordinary187_private.contexts WHERE(backend_pid,backend_start,xid)=(x.backend_pid,x.backend_start,x.xid);
 IF p->>'a' IS DISTINCT FROM 'n' OR p->>'s' IS DISTINCT FROM '3' THEN RAISE EXCEPTION '202 both exact expiry updates required' USING ERRCODE='42501';END IF;
 UPDATE ordinary187_private.contexts SET keeper_call=NULL WHERE(backend_pid,backend_start,xid)=(x.backend_pid,x.backend_start,x.xid);
 SELECT(to_jsonb(b)-'token_hash')||jsonb_build_object('expires_at',deadline_text) INTO STRICT j1 FROM public.large_import_quota_reservations173 b WHERE tenant_id=t AND id=jq;
 SELECT(to_jsonb(b)-'token_hash')||jsonb_build_object('expires_at',deadline_text) INTO STRICT r1 FROM public.large_import_quota_reservations173 b WHERE tenant_id=t AND id=rq;
 IF j1-'expires_at' IS DISTINCT FROM j0-'expires_at' OR r1-'expires_at' IS DISTINCT FROM r0-'expires_at'
 THEN RAISE EXCEPTION '202 all non-expiry fields unchanged' USING ERRCODE='23514';END IF;
 PERFORM public.large_import173_admit(u,t,k,r,h,true);
 RETURN jsonb_build_object('schema','quota-open-pair-renewal-receipt/v1','renewed',true,'identity_preserved',true,'accounting_preserved',true,
 'native_time',to_char(now0 AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'lease_seconds',ttl,
 'job',jsonb_build_object('before',j0,'after',j1),'review',jsonb_build_object('before',r0,'after',r1));
END $renew202$;
REVOKE ALL ON FUNCTION public.ordinary202_quota_renew_pair(uuid,uuid,uuid,text,text,text,uuid,uuid,uuid,uuid,text,uuid,uuid,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ordinary202_quota_renew_pair(uuid,uuid,uuid,text,text,text,uuid,uuid,uuid,uuid,text,uuid,uuid,text,text,text) TO dyna_app;

CREATE OR REPLACE FUNCTION ordinary187_private.context_bound198() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,ordinary187_private SET TimeZone='UTC' AS $bound198$
BEGIN
 -- Actual whole tuple includes the marker and every inherited column; JSON length alone is insufficient.
 IF pg_column_size(NEW)>1024 THEN RAISE EXCEPTION '198 context exceeds preallocated1024' USING ERRCODE='54000';END IF;
 IF TG_OP='UPDATE' AND to_jsonb(NEW)-'keeper_call' IS DISTINCT FROM to_jsonb(OLD)-'keeper_call' THEN RAISE EXCEPTION '198 marker cannot replace context authority' USING ERRCODE='42501';END IF;
 -- Native202: exact additive marker; legacy198 branch below remains literal.
 IF NEW.keeper_call->>'a'='n' THEN
  IF NEW.mode<>'growth' OR NEW.api_key_id IS NOT NULL
  OR (SELECT array_agg(v ORDER BY v) FROM jsonb_object_keys(NEW.keeper_call) v) IS DISTINCT FROM ARRAY['a','c','k','q','s','t','w']::text[]
  OR EXISTS(SELECT FROM jsonb_each(NEW.keeper_call) e WHERE e.key<>'s' AND jsonb_typeof(e.value) IS DISTINCT FROM 'string')
  OR octet_length(NEW.keeper_call::text)>512
  OR NEW.keeper_call->>'q' IS NULL OR NEW.keeper_call->>'c' IS NULL OR NEW.keeper_call->>'k' IS NULL
  OR NEW.keeper_call->>'q' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
  OR NEW.keeper_call->>'c' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
  OR NEW.keeper_call->>'k' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
  OR NEW.keeper_call->>'q'=NEW.keeper_call->>'c'
  OR NEW.keeper_call->>'w' IS NULL OR NEW.keeper_call->>'w' !~ '^[a-f0-9]{64}$'
  OR NEW.keeper_call->>'t' IS NULL OR NEW.keeper_call->>'t' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
  OR jsonb_typeof(NEW.keeper_call->'s') IS DISTINCT FROM 'number'
  OR (NEW.keeper_call->>'s')::integer NOT BETWEEN 0 AND 3
  THEN RAISE EXCEPTION '202 exact bounded normal-owner renewal marker' USING ERRCODE='23514';END IF;
  RETURN NEW;
 END IF;
 IF NEW.keeper_call IS NOT NULL AND (jsonb_typeof(NEW.keeper_call) IS DISTINCT FROM 'object' OR octet_length(NEW.keeper_call::text)>512
 OR (SELECT array_agg(k198.value ORDER BY k198.value) FROM jsonb_object_keys(NEW.keeper_call) AS k198(value)) IS DISTINCT FROM ARRAY['a','c','k','q','s','t','w']::text[]
 OR EXISTS(SELECT FROM jsonb_each(NEW.keeper_call) e198 WHERE e198.key<>'s' AND jsonb_typeof(e198.value) IS DISTINCT FROM 'string')
 OR NEW.keeper_call->>'a' IS NULL OR NEW.keeper_call->>'a' NOT IN('u','b','c','d','z') OR NEW.keeper_call->>'t' IS NULL OR NEW.keeper_call->>'t' NOT IN('unused-quarantine','released-lock','known-close','absent-prefix')
 OR NEW.keeper_call->>'w' IS NULL OR NEW.keeper_call->>'w' !~ '^[a-f0-9]{64}$' OR NEW.keeper_call->>'k' IS NULL OR length(NEW.keeper_call->>'k')>100
 OR (NEW.keeper_call->>'a' IN('u','b') AND NEW.keeper_call->>'k' !~ '^blob:fs:(blobs|uploads|witnesses):[a-f0-9-]{36}:(quarantine-json|lock:[a-f0-9-]{36})$')
 OR (NEW.keeper_call->>'a' IN('c','d','z') AND (NEW.keeper_call->>'t' IS DISTINCT FROM (CASE WHEN NEW.keeper_call->>'a'='z' THEN 'absent-prefix' ELSE 'known-close' END) OR NEW.keeper_call->>'k' IS DISTINCT FROM 'event:'||(CASE NEW.keeper_call->>'a' WHEN 'c' THEN 'upload-known-close:' WHEN 'd' THEN 'business-known-close:' ELSE 'upload-absent-close:' END)||(NEW.keeper_call->>'c')))
 OR (NEW.keeper_call->>'a' IN('u','b') AND NEW.keeper_call->>'t' NOT IN('unused-quarantine','released-lock'))
 OR (NEW.keeper_call->>'t'='unused-quarantine' AND (NEW.keeper_call->>'a'<>'u' OR NEW.keeper_call->>'k' !~ '^blob:fs:blobs:[a-f0-9-]{36}:quarantine-json$'))
 OR (NEW.keeper_call->>'t'='released-lock' AND NEW.keeper_call->>'k' !~ '^blob:fs:(blobs|uploads|witnesses):[a-f0-9-]{36}:lock:[a-f0-9-]{36}$')
 OR (NEW.keeper_call->>'a'='b' AND (NEW.keeper_call->>'t'<>'released-lock' OR NEW.keeper_call->>'k' !~ '^blob:fs:witnesses:[a-f0-9-]{36}:lock:[a-f0-9-]{36}$'))
 OR (NEW.keeper_call->>'q')::uuid IS NULL OR (NEW.keeper_call->>'c')::uuid IS NULL
 OR jsonb_typeof(NEW.keeper_call->'s') IS DISTINCT FROM 'number' OR (NEW.keeper_call->>'s')::integer NOT BETWEEN 0 AND 127
 OR (NEW.keeper_call->>'a' IN('u','b') AND (NEW.keeper_call->>'s')::integer>31)
 OR (NEW.keeper_call->>'a' IN('c','d') AND (NEW.keeper_call->>'s')::integer>3)) THEN
  RAISE EXCEPTION '198 exact marker field shape' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $bound198$;
CREATE OR REPLACE FUNCTION public.ordinary187_resource_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,ordinary187_private SET TimeZone='UTC' AS $guard187$
DECLARE x ordinary187_private.contexts%ROWTYPE;e ordinary187_private.journal%ROWTYPE;row0 jsonb;old0 jsonb;new0 jsonb;
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION '187 original evidence cannot truncate' USING ERRCODE='42501';END IF;
 IF session_user<>'postgres' OR current_setting('role',true) NOT IN('none','dyna_app') OR current_setting('session_replication_role')<>'origin' THEN RAISE EXCEPTION '187 original app-role transport' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT x FROM ordinary187_private.contexts WHERE backend_pid=pg_backend_pid() AND xid=pg_current_xact_id();
 SELECT * INTO STRICT e FROM ordinary187_private.journal WHERE root_key=x.root_key AND epoch=x.epoch AND kind='epoch' FOR SHARE;
 IF x.keeper_call->>'a'='n' THEN
  PERFORM ordinary187_private.quota_renew_effect202(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP IN('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END,CASE WHEN TG_OP IN('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END);
  RETURN NEW;
 END IF;
 IF current_setting('role',true)='none' THEN
  IF x.keeper_call->>'a' IN('c','d','z') THEN
   PERFORM ordinary187_private.keeper_close_effect198(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP IN('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END,CASE WHEN TG_OP IN('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END);
  ELSE
  PERFORM ordinary187_private.keeper_release_effect198(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP IN('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END,CASE WHEN TG_OP IN('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END);
  END IF;
  RETURN NEW;
 END IF;
 row0:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 IF (row0->>'tenant_id')::uuid IS DISTINCT FROM x.tenant_id OR nullif(current_setting('app.tenant_id',true),'')::uuid IS DISTINCT FROM x.tenant_id THEN RAISE EXCEPTION '187 exact resource tenant' USING ERRCODE='42501';END IF;
 IF row0 ? 'actor_id' AND ((row0->>'actor_id')::uuid IS DISTINCT FROM x.actor_id OR (row0->>'api_key_id')::uuid IS DISTINCT FROM x.api_key_id) THEN RAISE EXCEPTION '187 exact resource principal' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME IN('large_import_parts173','large_import_batches173') AND NOT EXISTS(SELECT FROM public.large_import_blobs173 b187 WHERE b187.tenant_id=x.tenant_id AND b187.id=(row0->>'blob_id')::uuid AND b187.actor_id=x.actor_id AND b187.api_key_id IS NOT DISTINCT FROM x.api_key_id) THEN RAISE EXCEPTION '187 exact blob parent principal' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME='large_import_events173' AND NOT EXISTS(SELECT FROM public.large_import_jobs173 j187 WHERE j187.tenant_id=x.tenant_id AND j187.id=(row0->>'job_id')::uuid AND j187.actor_id=x.actor_id AND j187.api_key_id IS NOT DISTINCT FROM x.api_key_id) THEN RAISE EXCEPTION '187 exact job parent principal' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME IN('large_import_quota_resources173','large_import_quota_terminal_witnesses173','large_import_quota_terminal_receipts173') AND NOT EXISTS(SELECT FROM public.large_import_quota_reservations173 q187 WHERE q187.tenant_id=x.tenant_id AND q187.id=(row0->>'reservation_id')::uuid AND q187.actor_id=x.actor_id AND q187.api_key_id IS NOT DISTINCT FROM x.api_key_id) THEN RAISE EXCEPTION '187 exact reservation parent principal' USING ERRCODE='42501';END IF;
 IF x.mode='growth' THEN
  IF e.payload_text::jsonb->>'state'<>'OPEN' THEN RAISE EXCEPTION '187 poisoned growth DML' USING ERRCODE='55000';END IF;
  IF NOT EXISTS(SELECT FROM ordinary187_private.journal o187 JOIN pg_stat_activity p187 ON p187.pid=(o187.payload_text::jsonb->>'parent_pid')::integer AND p187.backend_start=(o187.payload_text::jsonb->>'parent_start')::timestamptz AND p187.datname=current_database() WHERE(o187.root_key,o187.epoch,o187.id)=(x.root_key,x.epoch,x.original_id) AND o187.kind='original' AND o187.payload_text::jsonb->>'state'='OPEN') THEN RAISE EXCEPTION '187 growth requires same live original companion' USING ERRCODE='55000';END IF;
 ELSE
  -- Existing keeper functions remain mandatory and decisive. This is an additional no-growth envelope, not a replacement for native original token/hash/bytes/FS proofs.
  old0:=CASE WHEN TG_OP IN('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END;new0:=CASE WHEN TG_OP IN('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END;
  IF e.payload_text::jsonb->>'state' NOT IN('OPEN','POISONED') OR TG_OP='DELETE' THEN RAISE EXCEPTION '187 terminal exact epoch/no delete' USING ERRCODE='42501';END IF;
  IF TG_TABLE_NAME='large_import_jobs173' AND TG_OP='UPDATE' THEN
   IF new0-'lease_token'-'leased_at' IS DISTINCT FROM old0-'lease_token'-'leased_at' OR NEW.lease_token IS NOT NULL OR NEW.leased_at IS NOT NULL THEN RAISE EXCEPTION '187 terminal job only exact lease release' USING ERRCODE='23514';END IF;
  ELSIF TG_TABLE_NAME='large_import_quota_resources173' AND TG_OP='UPDATE' THEN
   IF new0-'state' IS DISTINCT FROM old0-'state' OR NEW.state<>'released' OR OLD.state NOT IN('settled','quarantined') THEN RAISE EXCEPTION '187 terminal resource only exact no-growth release' USING ERRCODE='23514';END IF;
  ELSIF TG_TABLE_NAME='large_import_quota_resources173' AND TG_OP='INSERT' THEN
   IF NEW.kind<>'event' OR NEW.state<>'settled' OR NEW.resource_key !~ '^event:(quota-terminal-witness|quota-terminal-receipt|upload-known-close|upload-absent-close|business-known-close):[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' OR NEW.payload_text IS NULL OR NEW.byte_count<>octet_length(NEW.payload_text) OR NEW.sha256<>encode(sha256(convert_to(NEW.payload_text,'UTF8')),'hex') OR NEW.payload_text::jsonb->>'schema' NOT IN('private-quota-terminal-witness/v1','private-business-lock-terminal-witness/v1','quota-terminal-receipt/v1','quota-known-close-evidence/v1','quota-absent-close-evidence/v1') THEN RAISE EXCEPTION '187 terminal only native close evidence' USING ERRCODE='23514';END IF;
  ELSIF TG_TABLE_NAME='large_import_quota_reservations173' AND TG_OP='UPDATE' THEN
   IF OLD.state<>'open' OR NEW.state NOT IN('unknown','retained') THEN RAISE EXCEPTION '187 terminal reservation only original open' USING ERRCODE='23514';END IF;
   IF NEW.state='unknown' THEN
    IF new0-'state' IS DISTINCT FROM old0-'state' THEN RAISE EXCEPTION '187 unknown preserves every original charge/field' USING ERRCODE='23514';END IF;
   ELSIF new0-ARRAY['state','outcome','raw_charge','metadata_charge','objects_charge','closed_at','inventory_sha256']::text[] IS DISTINCT FROM old0-ARRAY['state','outcome','raw_charge','metadata_charge','objects_charge','closed_at','inventory_sha256']::text[] OR NEW.outcome IS NULL OR NEW.outcome NOT IN('ready','absent') OR NEW.raw_charge<0 OR NEW.raw_charge>OLD.raw_ceiling OR NEW.metadata_charge<0 OR NEW.metadata_charge>OLD.metadata_ceiling OR NEW.objects_charge<0 OR NEW.objects_charge>OLD.objects_ceiling OR NEW.closed_at IS NULL OR NEW.inventory_sha256 IS NULL THEN
    RAISE EXCEPTION '187 retained original capacity/identity' USING ERRCODE='23514';
   END IF;
  ELSIF TG_TABLE_NAME NOT IN('large_import_quota_terminal_witnesses173','large_import_quota_terminal_receipts173') OR TG_OP<>'INSERT' THEN
   RAISE EXCEPTION '187 terminal growth refused' USING ERRCODE='42501';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $guard187$;
CREATE OR REPLACE FUNCTION public.ordinary187_private_valid() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $ordinary187_definition$
DECLARE bound187 record;observation187 jsonb;
BEGIN
 WITH funcs AS MATERIALIZED(SELECT p.*,n.nspname AS schema FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='ordinary187_private' OR(n.nspname='public' AND((starts_with(p.proname,'ordinary187_') AND p.proname NOT IN('ordinary187_approve','ordinary187_private_valid','ordinary187_profile_project','ordinary187_valid')) OR p.proname='large_import_quota_reserve173' OR starts_with(p.proname,'ordinary198_') OR p.proname IN('ordinary202_quota_renew_preview','ordinary202_quota_renew_pair')))),rels AS MATERIALIZED(SELECT c.* FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ordinary187_private' AND c.relkind IN('r','p','v','m','f','S')),trigs AS MATERIALIZED(SELECT t.* FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND(n.nspname='ordinary187_private' OR(n.nspname='public' AND starts_with(t.tgname,'ordinary187_')))),defaults AS MATERIALIZED(SELECT d.* FROM pg_catalog.pg_default_acl d WHERE d.defaclrole='postgres'::regrole AND(d.defaclnamespace=0 OR d.defaclnamespace=(SELECT oid FROM pg_catalog.pg_namespace WHERE nspname='ordinary187_private')))
SELECT
 (SELECT count(*)::integer FROM pg_catalog.pg_namespace WHERE nspname='ordinary187_private') schemas,
 (SELECT count(*)::integer FROM rels) relations,
 (SELECT count(*)::integer FROM funcs) functions,
 (SELECT count(*)::integer FROM funcs WHERE prokind<>'f') non_functions,
 (SELECT count(*)::integer FROM pg_catalog.pg_attribute WHERE attrelid IN(SELECT oid FROM rels) AND attnum>0 AND NOT attisdropped) columns,
 (SELECT count(*)::integer FROM pg_catalog.pg_attribute WHERE attrelid IN(SELECT oid FROM rels) AND attnum>0 AND attisdropped) dropped_columns,
 (SELECT count(*)::integer FROM pg_catalog.pg_constraint WHERE conrelid IN(SELECT oid FROM rels)) constraints,
 (SELECT count(*)::integer FROM pg_catalog.pg_index WHERE indrelid IN(SELECT oid FROM rels)) indexes,
 (SELECT count(*)::integer FROM pg_catalog.pg_policy WHERE polrelid IN(SELECT oid FROM rels)) policies,
 (SELECT count(*)::integer FROM pg_catalog.pg_inherits WHERE inhrelid IN(SELECT oid FROM rels) OR inhparent IN(SELECT oid FROM rels)) inheritance_edges,
 (SELECT count(*)::integer FROM trigs) triggers,
 (SELECT count(*)::integer FROM pg_catalog.pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid IN(SELECT oid FROM rels) AND a.attnum>0) column_acl_entries,
 (SELECT count(*)::integer FROM funcs p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x) function_acl_entries,
 (SELECT count(*)::integer FROM rels c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x) table_acl_entries,
 (SELECT count(*)::integer FROM pg_catalog.pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x WHERE n.nspname='ordinary187_private') schema_acl_entries,
 (SELECT count(*)::integer FROM defaults) default_acl_rows,
 (SELECT count(*)::integer FROM defaults d CROSS JOIN LATERAL aclexplode(d.defaclacl) x) default_acl_entries INTO bound187;
 IF bound187.schemas IS DISTINCT FROM 1 OR bound187.relations IS DISTINCT FROM 2 OR bound187.functions IS DISTINCT FROM 41 OR bound187.non_functions IS DISTINCT FROM 0 OR bound187.columns IS DISTINCT FROM 24 OR bound187.dropped_columns IS DISTINCT FROM 0 OR bound187.constraints IS DISTINCT FROM 35 OR bound187.indexes IS DISTINCT FROM 3 OR bound187.policies IS DISTINCT FROM 0 OR bound187.inheritance_edges IS DISTINCT FROM 0 OR bound187.triggers IS DISTINCT FROM 22 OR bound187.column_acl_entries IS DISTINCT FROM 0 OR bound187.function_acl_entries IS DISTINCT FROM 46 OR bound187.table_acl_entries IS DISTINCT FROM 16 OR bound187.schema_acl_entries IS DISTINCT FROM 2 OR bound187.default_acl_rows<>0 OR bound187.default_acl_entries<>0 THEN RETURN false;END IF;
 WITH funcs AS MATERIALIZED(SELECT p.*,n.nspname AS schema FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='ordinary187_private' OR(n.nspname='public' AND((starts_with(p.proname,'ordinary187_') AND p.proname NOT IN('ordinary187_approve','ordinary187_private_valid','ordinary187_profile_project','ordinary187_valid')) OR p.proname='large_import_quota_reserve173' OR starts_with(p.proname,'ordinary198_') OR p.proname IN('ordinary202_quota_renew_preview','ordinary202_quota_renew_pair')))),rels AS MATERIALIZED(SELECT c.* FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ordinary187_private' AND c.relkind IN('r','p','v','m','f','S')),trigs AS MATERIALIZED(SELECT t.* FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND(n.nspname='ordinary187_private' OR(n.nspname='public' AND starts_with(t.tgname,'ordinary187_')))),defaults AS MATERIALIZED(SELECT d.* FROM pg_catalog.pg_default_acl d WHERE d.defaclrole='postgres'::regrole AND(d.defaclnamespace=0 OR d.defaclnamespace=(SELECT oid FROM pg_catalog.pg_namespace WHERE nspname='ordinary187_private')))
, texts AS MATERIALIZED(
 SELECT pg_get_functiondef(oid) s FROM funcs
 UNION ALL SELECT pg_get_function_identity_arguments(oid) FROM funcs
 UNION ALL SELECT pg_get_function_result(oid) FROM funcs
 UNION ALL SELECT prosrc FROM funcs
 UNION ALL SELECT pg_get_expr(proargdefaults,0) FROM funcs
 UNION ALL SELECT proconfig::text FROM funcs
 UNION ALL SELECT proargnames::text FROM funcs
 UNION ALL SELECT proallargtypes::text FROM funcs
 UNION ALL SELECT probin FROM funcs
 UNION ALL SELECT prosqlbody::text FROM funcs
 UNION ALL SELECT pg_get_indexdef(indexrelid) FROM pg_catalog.pg_index WHERE indrelid IN(SELECT oid FROM rels)
 UNION ALL SELECT pg_get_constraintdef(oid,true) FROM pg_catalog.pg_constraint WHERE conrelid IN(SELECT oid FROM rels)
 UNION ALL SELECT pg_get_expr(adbin,adrelid) FROM pg_catalog.pg_attrdef WHERE adrelid IN(SELECT oid FROM rels)
 UNION ALL SELECT pg_get_triggerdef(oid,true) FROM trigs
 UNION ALL SELECT pg_get_expr(tgqual,tgrelid) FROM trigs
 UNION ALL SELECT encode(tgargs,'hex') FROM trigs
 UNION ALL SELECT reloptions::text FROM rels
 UNION ALL SELECT pg_get_expr(relpartbound,oid) FROM rels
 UNION ALL SELECT attoptions::text FROM pg_catalog.pg_attribute WHERE attrelid IN(SELECT oid FROM rels) AND attnum>0
 UNION ALL SELECT attfdwoptions::text FROM pg_catalog.pg_attribute WHERE attrelid IN(SELECT oid FROM rels) AND attnum>0
 UNION ALL SELECT attmissingval::text FROM pg_catalog.pg_attribute WHERE attrelid IN(SELECT oid FROM rels) AND attnum>0
 UNION ALL SELECT pg_get_expr(polqual,polrelid) FROM pg_catalog.pg_policy WHERE polrelid IN(SELECT oid FROM rels)
 UNION ALL SELECT pg_get_expr(polwithcheck,polrelid) FROM pg_catalog.pg_policy WHERE polrelid IN(SELECT oid FROM rels))
SELECT coalesce(sum(octet_length(to_jsonb(s)::text)),0)::bigint::text encoded_definition_bytes,
 coalesce(max(octet_length(to_jsonb(s)::text)),0)::bigint::text largest_definition_bytes FROM texts INTO bound187;
 IF bound187.encoded_definition_bytes::bigint>1048576 OR bound187.largest_definition_bytes::bigint>1048576 THEN RETURN false;END IF;
 WITH funcs AS MATERIALIZED(SELECT p.*,n.nspname AS schema FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='ordinary187_private' OR(n.nspname='public' AND((starts_with(p.proname,'ordinary187_') AND p.proname NOT IN('ordinary187_approve','ordinary187_private_valid','ordinary187_profile_project','ordinary187_valid')) OR p.proname='large_import_quota_reserve173' OR starts_with(p.proname,'ordinary198_') OR p.proname IN('ordinary202_quota_renew_preview','ordinary202_quota_renew_pair')))),rels AS MATERIALIZED(SELECT c.* FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ordinary187_private' AND c.relkind IN('r','p','v','m','f','S')),trigs AS MATERIALIZED(SELECT t.* FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND(n.nspname='ordinary187_private' OR(n.nspname='public' AND starts_with(t.tgname,'ordinary187_')))),defaults AS MATERIALIZED(SELECT d.* FROM pg_catalog.pg_default_acl d WHERE d.defaclrole='postgres'::regrole AND(d.defaclnamespace=0 OR d.defaclnamespace=(SELECT oid FROM pg_catalog.pg_namespace WHERE nspname='ordinary187_private')))
SELECT jsonb_build_object('schema','native187-supplement-observation/v1',
 'schemas',(SELECT jsonb_agg(jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'acl',(SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type,pg_get_userbyid(x.grantor),x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x))) FROM pg_catalog.pg_namespace n WHERE n.nspname='ordinary187_private'),
 'default_acls',(SELECT coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',CASE WHEN d.defaclnamespace=0 THEN NULL ELSE(SELECT nspname FROM pg_catalog.pg_namespace WHERE oid=d.defaclnamespace)END,'object_type',d.defaclobjtype,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee)END,x.privilege_type,pg_get_userbyid(x.grantor),x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type),'[]'::jsonb) FROM aclexplode(d.defaclacl)x)) ORDER BY CASE WHEN d.defaclnamespace=0 THEN '' ELSE(SELECT nspname FROM pg_catalog.pg_namespace WHERE oid=d.defaclnamespace)END,d.defaclobjtype),'[]'::jsonb) FROM defaults d),
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'kind',c.relkind,'persistence',c.relpersistence,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'replica_identity',c.relreplident,'options',c.reloptions,'partition',c.relispartition,'partition_bound',pg_get_expr(c.relpartbound,c.oid),'acl',(SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type,pg_get_userbyid(x.grantor),x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x),
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'position',a.attnum,'type_schema',tn.nspname,'type_name',ty.typname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'dropped',a.attisdropped,'has_missing',a.atthasmissing,'missing_value',a.attmissingval::text,'storage',a.attstorage,'compression',a.attcompression,'options',a.attoptions,'fdw_options',a.attfdwoptions,'collation_schema',cn.nspname,'collation_name',co.collname,'acl',a.attacl::text,'default',pg_get_expr(ad.adbin,ad.adrelid)) ORDER BY a.attnum) FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_type ty ON ty.oid=a.atttypid LEFT JOIN pg_catalog.pg_namespace tn ON tn.oid=ty.typnamespace LEFT JOIN pg_catalog.pg_collation co ON co.oid=a.attcollation LEFT JOIN pg_catalog.pg_namespace cn ON cn.oid=co.collnamespace LEFT JOIN pg_catalog.pg_attrdef ad ON(ad.adrelid,ad.adnum)=(a.attrelid,a.attnum) WHERE a.attrelid=c.oid AND a.attnum>0),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('name',ic.relname,'access_method',am.amname,'unique',i.indisunique,'primary',i.indisprimary,'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'immediate',i.indimmediate,'nulls_not_distinct',i.indnullsnotdistinct,'key_columns',i.indnkeyatts,'columns',i.indnatts,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY ic.relname) FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class ic ON ic.oid=i.indexrelid JOIN pg_catalog.pg_am am ON am.oid=ic.relam WHERE i.indrelid=c.oid),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('name',k.conname,'type',k.contype,'deferrable',k.condeferrable,'initially_deferred',k.condeferred,'validated',k.convalidated,'definition',pg_get_constraintdef(k.oid,true)) ORDER BY k.conname) FROM pg_catalog.pg_constraint k WHERE k.conrelid=c.oid),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid),'roles',(SELECT array_agg(CASE WHEN v=0 THEN 'PUBLIC' ELSE pg_get_userbyid(v) END ORDER BY CASE WHEN v=0 THEN 'PUBLIC' ELSE pg_get_userbyid(v) END) FROM unnest(p.polroles)v)) ORDER BY p.polname),'[]'::jsonb) FROM pg_catalog.pg_policy p WHERE p.polrelid=c.oid)) ORDER BY c.relname) FROM rels c),
