3_resource_key_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_tenant_id_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_witness_text_check","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_witness_text_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses17_classification_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses17_original_bytes_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses17_original_state_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses17_reservation_id_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses17_witness_sha256_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses1_original_sha256_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses1_tenant_id_client_key_key","relation":"large_import_quota_terminal_witnesses173"}]},"functions":[{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, w boolean","leakproof":false,"signature":"large_import173_admit(uuid,uuid,uuid,text,text,boolean)","definition":"CREATE OR REPLACE FUNCTION public.large_import173_admit(u uuid, t uuid, k uuid, r text, h text, w boolean)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE x record;v_now timestamptz;\nBEGIN\n IF u IS NULL OR t IS NULL OR r IS NULL OR r NOT IN(''admin'',''operator'',''viewer'') OR h IS NULL OR h !~ ''^[a-f0-9]{64}$'' OR w IS NULL THEN\n  RAISE EXCEPTION ''Invalid metadata authority'' USING ERRCODE=''42501'';\n END IF;\n -- SD current_user is the module owner. The caller remains the dedicated owner''s SESSION dyna_app connection.\n IF current_setting(''role'',true) IS DISTINCT FROM ''dyna_app''\n OR session_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=to_regclass(''public.large_import173_certificate'')))\n OR t IS DISTINCT FROM nullif(current_setting(''app.tenant_id'',true),'''')::uuid THEN\n  RAISE EXCEPTION ''Metadata app-role tenant transport mismatch'' USING ERRCODE=''42501'';\n END IF;\n -- Owner startup MUST independently pin the complete current body/catalog graph before setting app role.\n -- This leaf check alone is not self-attestation. The new helper+grant must be in that compiled certificate graph.\n IF public.large_import173_valid() IS DISTINCT FROM true THEN\n  RAISE EXCEPTION ''Metadata173 is not certified'' USING ERRCODE=''55000'';\n END IF;\n -- Same order as native170 pin path; independent authority, without its lifecycle.\n -- Actual metadata checkpoint caller must be inside BEGIN; locks then survive through its COMMIT/ROLLBACK.\n PERFORM 1 FROM public.users WHERE id=u FOR SHARE;\n PERFORM 1 FROM public.tenants WHERE id=t FOR SHARE;\n PERFORM 1 FROM public.account_security WHERE user_id=u FOR SHARE;\n PERFORM 1 FROM public.workspace_security_policies WHERE tenant_id=t FOR SHARE;\n PERFORM 1 FROM public.memberships WHERE(user_id,tenant_id)=(u,t) FOR SHARE;\n IF k IS NULL THEN\n  PERFORM 1 FROM public.sessions WHERE(token_hash,user_id,tenant_id)=(h,u,t) FOR SHARE;\n ELSE\n  PERFORM 1 FROM public.api_keys WHERE(id,user_id,tenant_id)=(k,u,t) FOR SHARE;\n END IF;\n v_now:=clock_timestamp();\n IF k IS NULL THEN\n  SELECT m.role,coalesce(a.version,0)::text account_version,true scope_ok,\n   least(s.expires_at,CASE WHEN coalesce(p.require_mfa,false) THEN s.mfa_verified_at+interval ''8 hours'' ELSE s.expires_at END) deadline,\n   coalesce(p.require_mfa,false) AND NOT(coalesce(a.enabled_at IS NOT NULL AND s.mfa_verified_at IS NOT NULL AND s.mfa_verified_at>v_now-interval ''8 hours'',false)) mfa_required INTO x\n  FROM public.sessions s JOIN public.users z ON z.id=s.user_id JOIN public.tenants n ON n.id=s.tenant_id\n  JOIN public.memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)\n  LEFT JOIN public.account_security a ON a.user_id=z.id LEFT JOIN public.workspace_security_policies p ON p.tenant_id=n.id\n  WHERE(s.token_hash,s.user_id,s.tenant_id)=(h,u,t) AND s.expires_at>v_now AND s.account_version=coalesce(a.version,0);\n ELSE\n  SELECT m.role,coalesce(a.version,0)::text account_version,k0.expires_at deadline,\n   k0.scopes@>CASE WHEN w THEN ARRAY[''products:read'',''products:write'']::text[] ELSE ARRAY[''products:read'']::text[] END scope_ok,\n   coalesce(p.require_mfa,false) AND a.enabled_at IS NULL mfa_required INTO x\n  FROM public.api_keys k0 JOIN public.users z ON z.id=k0.user_id JOIN public.tenants n ON n.id=k0.tenant_id\n  JOIN public.memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)\n  LEFT JOIN public.account_security a ON a.user_id=z.id LEFT JOIN public.workspace_security_policies p ON p.tenant_id=n.id\n  WHERE(k0.id,k0.token_hash,k0.user_id,k0.tenant_id)=(k,h,u,t) AND k0.revoked_at IS NULL AND k0.expires_at>v_now;\n END IF;\n IF x.role IS NULL OR x.deadline IS NULL OR NOT isfinite(x.deadline) OR x.deadline<=clock_timestamp() THEN\n  RAISE EXCEPTION ''Expired metadata authority'' USING ERRCODE=''28000'';\n END IF;\n IF x.role<>r THEN RAISE EXCEPTION ''Metadata role changed'' USING ERRCODE=''40001'';END IF;\n IF NOT coalesce(x.scope_ok,false) OR coalesce(x.mfa_required,true) OR(w AND x.role<>''admin'') THEN\n  RAISE EXCEPTION ''Missing current metadata authority'' USING ERRCODE=''42501'';\n END IF;\nEND\n$function$\n","volatility":"v","body_sha256":"239d1eb13343a59f2ca8a736c89eaf56d62192cc883e240137a3a86bfd5b5501","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","w"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"trigger","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"large_import173_append_guard()","definition":"CREATE OR REPLACE FUNCTION public.large_import173_append_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE b public.large_import_blobs173%ROWTYPE;oldpart public.large_import_parts173%ROWTYPE;n bigint;j jsonb;\nBEGIN\n IF TG_OP<>''INSERT'' THEN RAISE EXCEPTION ''Large import evidence is append only'' USING ERRCODE=''23514'';END IF;\n IF TG_TABLE_NAME=''large_import_events173'' THEN\n  SELECT state_text::jsonb INTO j FROM public.large_import_jobs173 WHERE tenant_id=NEW.tenant_id AND id=NEW.job_id;\n  IF j->''events''->(NEW.sequence::integer) IS DISTINCT FROM NEW.event_text::jsonb OR (j->>''revision'')::bigint IS NULL OR (j->>''revision'')::bigint<NEW.revision THEN RAISE EXCEPTION ''Event does not match saved job'' USING ERRCODE=''23514'';END IF;RETURN NEW;\n END IF;\n SELECT * INTO STRICT b FROM public.large_import_blobs173 WHERE tenant_id=NEW.tenant_id AND id=NEW.blob_id FOR UPDATE;\n IF b.raw_sha256 IS NOT NULL THEN RAISE EXCEPTION ''Original blob is sealed'' USING ERRCODE=''23514'';END IF;\n IF TG_TABLE_NAME=''large_import_parts173'' THEN\n  SELECT * INTO oldpart FROM public.large_import_parts173 WHERE (tenant_id,blob_id,offset_bytes)=(NEW.tenant_id,NEW.blob_id,NEW.offset_bytes);\n  IF FOUND THEN IF (oldpart.byte_count,oldpart.sha256) IS DISTINCT FROM (NEW.byte_count,NEW.sha256) THEN RAISE EXCEPTION ''Part replay differs'' USING ERRCODE=''23