;m jsonb;d jsonb;batch public.large_import_batches173%ROWTYPE;n integer:=0;\nBEGIN\n IF TG_OP=''DELETE'' THEN RAISE EXCEPTION ''Raw blob is retained'' USING ERRCODE=''23514'';END IF;\n IF TG_OP=''INSERT'' THEN\n  IF NEW.raw_sha256 IS NOT NULL OR NEW.raw_bytes IS NOT NULL OR NEW.completed_eof IS NOT NULL OR NEW.parse_valid IS NOT NULL OR NEW.manifest_text IS NOT NULL OR NEW.manifest_sha256 IS NOT NULL THEN RAISE EXCEPTION ''Original blob must start as empty unsealed upload'' USING ERRCODE=''23514'';END IF;\n  RETURN NEW;\n END IF;\n IF (NEW.tenant_id,NEW.id,NEW.actor_id,NEW.api_key_id,NEW.storage_id,NEW.spec_text,NEW.max_bytes,NEW.created_at) IS DISTINCT FROM (OLD.tenant_id,OLD.id,OLD.actor_id,OLD.api_key_id,OLD.storage_id,OLD.spec_text,OLD.max_bytes,OLD.created_at) THEN RAISE EXCEPTION ''Raw identity/spec are immutable'' USING ERRCODE=''23514'';END IF;\n IF OLD.raw_sha256 IS NOT NULL AND (NEW.raw_sha256,NEW.raw_bytes,NEW.completed_eof,NEW.parse_valid) IS DISTINCT FROM (OLD.raw_sha256,OLD.raw_bytes,OLD.completed_eof,OLD.parse_valid) THEN RAISE EXCEPTION ''Raw seal is immutable'' USING ERRCODE=''23514'';END IF;\n IF OLD.manifest_text IS NOT NULL AND (NEW.manifest_text,NEW.manifest_sha256) IS DISTINCT FROM (OLD.manifest_text,OLD.manifest_sha256) THEN RAISE EXCEPTION ''Manifest is immutable'' USING ERRCODE=''23514'';END IF;\n SELECT coalesce(sum(byte_count),0) INTO total FROM public.large_import_parts173 WHERE tenant_id=NEW.tenant_id AND blob_id=NEW.id;\n IF NEW.raw_bytes IS NOT NULL AND NEW.raw_bytes<>total THEN RAISE EXCEPTION ''Raw seal byte count differs'' USING ERRCODE=''23514'';END IF;\n IF NEW.manifest_text IS NOT NULL THEN m:=NEW.manifest_text::jsonb;\n  IF jsonb_typeof(m) IS DISTINCT FROM ''object'' OR m->>''schema'' IS DISTINCT FROM ''large-core-import-file/v1'' OR jsonb_typeof(m->''raw'') IS DISTINCT FROM ''object'' OR m#>>''{raw,sha256}'' IS DISTINCT FROM NEW.raw_sha256 OR jsonb_typeof(m#>''{raw,byte_count}'') IS DISTINCT FROM ''number'' OR (m#>>''{raw,byte_count}'') !~ ''^[1-9][0-9]*$'' OR (m#>>''{raw,byte_count}'')::bigint IS DISTINCT FROM NEW.raw_bytes OR m#>''{raw,completed_eof}'' IS DISTINCT FROM ''true''::jsonb OR m#>''{raw,parse_valid}'' IS DISTINCT FROM ''true''::jsonb OR jsonb_typeof(m->''batches'') IS DISTINCT FROM ''array'' OR jsonb_typeof(m->''records'') IS DISTINCT FROM ''number'' OR (m->>''records'') !~ ''^[1-9][0-9]*$'' OR jsonb_typeof(m->''total_batches'') IS DISTINCT FROM ''number'' OR (m->>''total_batches'') !~ ''^[1-9][0-9]*$'' THEN RAISE EXCEPTION ''Manifest raw seal differs'' USING ERRCODE=''23514'';END IF;\n  IF m->>''format'' IS DISTINCT FROM ''csv'' AND m->>''format'' IS DISTINCT FROM ''xml'' OR (SELECT count(*) FROM jsonb_object_keys(m->''raw''))<>4 OR NOT (m->''raw'' ?& ARRAY[''sha256'',''byte_count'',''completed_eof'',''parse_valid'']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(m) x WHERE x<>ALL(ARRAY[''schema'',''format'',''raw'',''records'',''total_batches'',''batches'',''header'',''raw_header''])) OR NOT (m ?& ARRAY[''schema'',''format'',''raw'',''records'',''total_batches'',''batches'']) THEN RAISE EXCEPTION ''Invalid manifest shape'' USING ERRCODE=''23514'';END IF;\n  IF m->>''format''=''csv'' THEN IF jsonb_typeof(m->''header'') IS DISTINCT FROM ''array'' OR jsonb_typeof(m->''raw_header'') IS DISTINCT FROM ''array'' THEN RAISE EXCEPTION ''CSV header is required'' USING ERRCODE=''23514'';END IF;IF jsonb_array_length(m->''header'') NOT BETWEEN 1 AND 1000 OR jsonb_array_length(m->''raw_header'') IS DISTINCT FROM jsonb_array_length(m->''header'') OR EXISTS(SELECT 1 FROM jsonb_array_elements(m->''header'') x WHERE jsonb_typeof(x) IS DISTINCT FROM ''string'') OR EXISTS(SELECT 1 FROM jsonb_array_elements(m->''raw_header'') x WHERE jsonb_typeof(x) IS DISTINCT FROM ''string'') THEN RAISE EXCEPTION ''CSV header differs'' USING ERRCODE=''23514'';END IF;ELSIF m ? ''header'' OR m ? ''raw_header'' THEN RAISE EXCEPTION ''XML cannot claim CSV headers'' USING ERRCODE=''23514'';END IF;\n  FOR d IN SELECT value FROM jsonb_array_elements(m->''batches'') LOOP\n   SELECT * INTO STRICT batch FROM public.large_import_batches173 WHERE tenant_id=NEW.tenant_id AND blob_id=NEW.id AND index=n;\n   IF jsonb_typeof(d) IS DISTINCT FROM ''object'' OR jsonb_typeof(d->''index'') IS DISTINCT FROM ''number'' OR (d->>''index'') !~ ''^(0|[1-9][0-9]*)$'' OR (d->>''index'')::integer IS DISTINCT FROM n OR d->>''id'' IS DISTINCT FROM batch.id OR d->>''ref'' IS DISTINCT FROM (''large-import-batch/v1:''||NEW.id::text||'':''||n::text||'':''||batch.id) OR jsonb_typeof(d->''rows'') IS DISTINCT FROM ''number'' OR (d->>''rows'') !~ ''^[1-9][0-9]*$'' OR (d->>''rows'')::integer IS DISTINCT FROM jsonb_array_length(batch.batch_text::jsonb->''records'') OR d->''normalized_bytes'' IS DISTINCT FROM batch.batch_text::jsonb->''normalized_bytes'' OR d->''record_spans'' IS DISTINCT FROM (SELECT jsonb_agg(value->''span'' ORDER BY ord) FROM jsonb_array_elements(batch.batch_text::jsonb->''records'') WITH ORDINALITY x(value,ord)) THEN RAISE EXCEPTION ''Manifest batch differs'' USING ERRCODE=''23514'';END IF;IF (SELECT count(*) FROM jsonb_object_keys(d))<>6 OR NOT (d ?& ARRAY[''index'',''id'',''rows'',''normalized_bytes'',''record_spans'',''ref'']) THEN RAISE EXCEPTION ''Invalid manifest descriptor shape'' USING ERRCODE=''23514'';END IF;records_count:=records_count+(d->>''rows'')::integer;n:=n+1;\n  END LOOP;\n  IF n=0 OR (m->>''records'')::bigint IS DISTINCT FROM records_count OR (m->>''total_batches'')::integer IS DISTINCT FROM n OR n<>(SELECT count(*) FROM public.large_import_batches173 WHERE tenant_id=NEW.tenant_id AND blob_id=NEW.id) THEN RAISE EXCEPTION ''Manifest batch count differs'' USING ERRCODE=''23514'';END IF;\n END IF;RETURN NEW;\nEND $function$\n","volatility":"v","body_sha256":"9fb461bdb64c2b54bcbe4ee9bc6f7c49f7592021e47b1f94c5bb529924b3bba7","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":false},{"acl":[["postgre