ect_keys(n->''principal''))<>3 OR NOT (n->''principal'' ?& ARRAY[''tenantId'',''userId'',''apiKeyId'']) OR (SELECT count(*) FROM jsonb_object_keys(n->''raw''))<>3 OR NOT (n->''raw'' ?& ARRAY[''id'',''sha256'',''byte_count'']) THEN RAISE EXCEPTION ''Invalid principal/raw descriptor keys'' USING ERRCODE=''23514'';END IF;\n IF jsonb_typeof(n->''core'') IS DISTINCT FROM ''array'' OR jsonb_typeof(n->''events'') IS DISTINCT FROM ''array'' OR jsonb_typeof(n->''pim'') IS DISTINCT FROM ''object'' OR jsonb_typeof(n->''approved'') IS DISTINCT FROM ''boolean'' OR jsonb_typeof(n->''manifest'') IS DISTINCT FROM ''object'' OR jsonb_typeof(n->''parsing_spec'') IS DISTINCT FROM ''object'' OR (SELECT count(*) FROM jsonb_object_keys(n))<>12 OR EXISTS(SELECT 1 FROM jsonb_object_keys(n) x WHERE x<>ALL(ARRAY[''schema'',''id'',''revision'',''principal'',''raw'',''manifest'',''parsing_spec'',''plan_hash'',''approved'',''core'',''pim'',''events''])) THEN RAISE EXCEPTION ''Invalid large import state shape'' USING ERRCODE=''23514'';END IF;\n IF TG_OP=''INSERT'' THEN IF NEW.revision<>0 OR jsonb_array_length(n->''events'')<>0 OR NEW.lease_fence IS DISTINCT FROM 0::bigint OR NEW.lease_token IS NOT NULL OR NEW.leased_at IS NOT NULL THEN RAISE EXCEPTION ''Large import must start revision zero'' USING ERRCODE=''23514'';END IF;RETURN NEW;END IF;\n -- Every UPDATE requires the genuine current backend to hold the exact app adapter bigint key.\n -- This proves exclusive serialization at this checkpoint, not IAM or session-versus-xact lifetime.\n lock_key:=hashtextextended(''large-import173:''||NEW.tenant_id::text||'':''||NEW.id::text,0);\n IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks l WHERE l.locktype=''advisory'' AND l.pid=pg_backend_pid() AND l.database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database()) AND l.mode=''ExclusiveLock'' AND l.granted IS TRUE AND l.objsubid=1 AND l.classid::bigint=((lock_key>>32)&4294967295::bigint) AND l.objid::bigint=(lock_key&4294967295::bigint)) THEN RAISE EXCEPTION ''Large import checkpoint requires owned advisory lock'' USING ERRCODE=''23514'';END IF;\n IF (NEW.tenant_id,NEW.id,NEW.actor_id,NEW.api_key_id,NEW.plan_hash,NEW.created_at) IS DISTINCT FROM (OLD.tenant_id,OLD.id,OLD.actor_id,OLD.api_key_id,OLD.plan_hash,OLD.created_at) THEN RAISE EXCEPTION ''Large import plan identity is immutable'' USING ERRCODE=''23514'';END IF;\n IF NEW.state_text=OLD.state_text AND NEW.state_sha256=OLD.state_sha256 AND NEW.revision=OLD.revision THEN\n  IF NOT (NEW.lease_fence=OLD.lease_fence+1 AND NEW.lease_token IS NOT NULL AND NEW.leased_at IS NOT NULL OR NEW.lease_fence=OLD.lease_fence AND NEW.lease_token IS NULL AND NEW.leased_at IS NULL AND OLD.lease_token IS NOT NULL) THEN RAISE EXCEPTION ''Invalid monotone lease transition'' USING ERRCODE=''23514'';END IF;RETURN NEW;\n END IF;\n IF NEW.lease_token IS DISTINCT FROM OLD.lease_token OR NEW.lease_fence<>OLD.lease_fence OR NEW.lease_token IS NULL OR NEW.revision<>OLD.revision+1 OR public.large_import173_immutable(n) IS DISTINCT FROM public.large_import173_immutable(b) OR (b->>''approved'')::boolean AND (n->>''approved'')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION ''Large import CAS/immutable plan differs'' USING ERRCODE=''23514'';END IF;\n IF jsonb_array_length(n->''events'')<>jsonb_array_length(b->''events'')+1 OR (SELECT coalesce(jsonb_agg(v ORDER BY ord),''[]''::jsonb) FROM jsonb_array_elements(n->''events'') WITH ORDINALITY x(v,ord) WHERE ord<=jsonb_array_length(b->''events'')) IS DISTINCT FROM b->''events'' OR (n->''events''->-1->>''sequence'')::bigint IS DISTINCT FROM jsonb_array_length(b->''events'') THEN RAISE EXCEPTION ''Large import events are append only'' USING ERRCODE=''23514'';END IF;\n FOR i IN 0..jsonb_array_length(b->''core'')-1 LOOP FOR k IN SELECT unnest(ARRAY[''preview'',''execution'',''consent'']) LOOP IF b->''core''->i ? k AND n->''core''->i->k IS DISTINCT FROM b->''core''->i->k THEN RAISE EXCEPTION ''Core receipt is immutable'' USING ERRCODE=''23514'';END IF;END LOOP;END LOOP;\n FOR pimkey,a IN SELECT key,value FROM jsonb_each(b->''pim'') LOOP\n  IF jsonb_typeof(n->''pim''->pimkey) IS DISTINCT FROM ''array'' OR jsonb_array_length(n->''pim''->pimkey)<jsonb_array_length(a) THEN RAISE EXCEPTION ''PIM history was removed'' USING ERRCODE=''23514'';END IF;\n  FOR i IN 0..jsonb_array_length(a)-1 LOOP p:=a->i;c:=n->''pim''->pimkey->i;\n   FOR k IN SELECT unnest(ARRAY[''number'',''mapping'',''stageKey'',''previewKey'',''applyKey'',''stage'',''preview'',''consent'',''applied'']) LOOP IF p ? k AND c->k IS DISTINCT FROM p->k THEN RAISE EXCEPTION ''PIM attempt/receipt is immutable'' USING ERRCODE=''23514'';END IF;END LOOP;\n   IF p->>''previewAttempted''=''true'' AND c->>''previewAttempted'' IS DISTINCT FROM ''true'' OR p->>''applyAttempted''=''true'' AND c->>''applyAttempted'' IS DISTINCT FROM ''true'' THEN RAISE EXCEPTION ''PIM uncertainty latch was removed'' USING ERRCODE=''23514'';END IF;\n  END LOOP;\n END LOOP;RETURN NEW;\nEND $function$\n","volatility":"v","body_sha256":"f35ea5172cf827ccf7ba18d8fd99862d3e3aa399aa0c980d72b9075f39157c15","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"sql","parallel":"u","arguments":"","leakproof":false,"signature":"large_import173_metadata()","definition":"CREATE OR REPLACE FUNCTION public.large_import173_metadata()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\n-- Fixed owner SELECT, also used verbatim by startup; it invokes no candidate helper.\n-- Portable semantic identifiers; generated FK trigger allocation names/OIDs are deliberately excluded.\nWITH RECURSIVE own AS (SELECT c.* FROM pg_class c WHERE c.relnamespace=''public''::regnamespace\n AND (starts_with(c.relname,''large_import_'') OR starts_with(c.relname,''large_import173_''))),\n own_functions AS (SELECT p.* FROM pg_proc p WHERE p.pronamespace=''public''::regnamespace\n AND (starts_with(p.proname,''large_import_'') OR starts_with(p.proname,''large_import173_''))),\n reachable(role_oid) AS (SELECT oid FROM pg_roles WHERE rolname=''dyna_app'' UNION SELECT relowner FROM own UNION SELECT nspowner FROM pg_namespace WHERE oid=''public''::regnamespace UNION SELECT m.roleid FROM pg_auth_members m JOIN reachable r ON r.role_oid=m.member)\nSELECT jsonb_build_object(\n ''namespace'',(SELECT jsonb_build_object(''name'',nspname,''owner'',pg_get_userbyid(nspowner),''acl_is_null'',nspacl IS NULL,''acl'',public.pim_dictionary_acl_metadata(coalesce(nspacl,acldefault(''n''::\"char\",nspowner)))) FROM pg_namespace WHERE oid=''public''::regnamespace),\n ''default_acl'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''owner'',pg_get_userbyid(defaclrole),''schema'',CASE WHEN defaclnamespace=0 THEN NULL ELSE defaclnamespace::regnamespace::text END,''kind'',defaclobjtype,''acl'',public.pim_dictionary_acl_metadata(defaclacl)) ORDER BY pg_get_userbyid(defaclrole)::text,defaclnamespace::regnamespace::text,defaclobjtype),''[]''::jsonb) FROM pg_default_acl WHERE defaclrole IN(SELECT role_oid FROM reachable) AND defaclnamespace IN(0,''public''::regnamespace::oid)),\n ''reserved'',(SELECT jsonb_build_object(''constraints'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''name'',conname,''relation'',conrelid::regclass::text) ORDER BY conrelid::regclass::text,conname),''[]''::jsonb) FROM pg_constraint WHERE connamespace=''public''::regnamespace AND (starts_with(conname,''large_import_'') OR starts_with(conname,''large_import173_''))),''triggers'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''name'',tgname,''relation'',tgrelid::regclass::text) ORDER BY tgrelid::regclass::text,tgname),''[]''::jsonb) FROM pg_trigger WHERE NOT tgisinternal AND (starts_with(tgname,''large_import_'') OR starts_with(tgname,''large_import173_''))),''policies'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''name'',polname,''relation'',polrelid::regclass::text) ORDER BY polrelid::regclass::text,polname),''[]''::jsonb) FROM pg_policy WHERE starts_with(polname,''large_import_'') OR starts_with(polname,''large_import173_'')))),\n ''classes'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''name'',relname,''kind'',relkind,''owner'',pg_get_userbyid(relowner),''persistence'',relpersistence,''acl'',public.pim_dictionary_acl_metadata(coalesce(relacl,acldefault(''r''::\"char\",relowner)))) ORDER BY relname),''[]''::jsonb) FROM own),\n ''relations'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''name'',c.relname,''kind'',c.relkind,''owner'',pg_get_userbyid(c.relowner),''persistence'',c.relpersistence,''rls'',c.relrowsecurity,''force_rls'',c.relforcerowsecurity,''replica_identity'',c.relreplident,''options'',c.reloptions,''access_method'',am.amname,\n ''acl'',public.pim_dictionary_acl_metadata(coalesce(c.relacl,acldefault(''r''::\"char\",c.relowner))),\n ''columns'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''position'',a.attnum,''dropped'',a.attisdropped,''dimensions'',a.attndims,''length'',a.attlen,''by_value'',a.attbyval,''alignment'',a.attalign,''has_missing'',a.atthasmissing,''missing_value'',to_jsonb(a.attmissingval),''name'',a.attname,''type'',format_type(a.atttypid,a.atttypmod),''not_null'',a.attnotnull,''identity'',a.attidentity,''generated'',a.attgenerated,''storage'',a.attstorage,''compression'',a.attcompression,''statistics'',a.attstattarget,''options'',a.attoptions,''collation'',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END,''default'',pg_get_expr(d.adbin,d.adrelid),''acl'',public.pim_dictionary_acl_metadata(a.attacl)) ORDER BY a.attnum),''[]''::jsonb) FROM pg_attribute a LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE a.attrelid=c.oid AND a.attnum>0),\n ''constraints'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''name'',conname,''kind'',contype,''validated'',convalidated,''enforced'',conenforced,''period'',conperiod,''local'',conislocal,''inheritance_count'',coninhcount,''no_inherit'',connoinherit,''parent'',CASE WHEN conparentid=0 THEN NULL ELSE (SELECT jsonb_build_object(''name'',par.conname,''relation'',par.conrelid::regclass::text) FROM pg_constraint par WHERE par.oid=con.conparentid) END,''deferrable'',condeferrable,''deferred'',condeferred,''definition'',pg_get_constraintdef(oid,true),''columns'',(SELECT jsonb_agg(a.attname ORDER BY n) FROM unnest(conkey) WITH ORDINALITY k(attnum,n) JOIN pg_attribute a ON(a.attrelid,a.attnum)=(conrelid,k.attnum)),''foreign_relation'',CASE WHEN confrelid=0 THEN NULL ELSE confrelid::regclass::text END,''foreign_columns'',(SELECT jsonb_agg(a.attname ORDER BY n) FROM unnest(confkey) WITH ORDINALITY k(attnum,n) JOIN pg_attribute a ON(a.attrelid,a.attnum)=(confrelid,k.attnum)),''update'',confupdtype,''delete'',confdeltype,''match'',confmatchtype) ORDER BY conname),''[]''::jsonb) FROM pg_constraint con WHERE con.conrelid=c.oid),\n ''indexes'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''name'',idx.relname,''definition'',pg_get_indexdef(i.indexrelid),''valid'',i.indisvalid,''ready'',i.indisready,''live'',i.indislive,''unique'',i.indisunique,''primary'',i.indisprimary,''clustered'',i.indisclustered,''replica_identity'',i.indisreplident,''options'',idx.reloptions,''owner'',pg_get_userbyid(idx.relowner),''access_method'',iam.amname) ORDER BY idx.relname),''[]''::jsonb) FROM pg_index i JOIN pg_class idx ON idx.oid=i.indexrelid LEFT JOIN pg_am iam ON iam.oid=idx.relam WHERE i.indrelid=c.oid),\n ''policies'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''name'',polname,''command'',polcmd,''permissive'',polpermissive,''roles'',(SELECT jsonb_agg(CASE WHEN id=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(id) END ORDER BY CASE WHEN id=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(id)::text END) FROM unnest(polroles) r(id)),''using'',pg_get_expr(polqual,polrelid),''check'',pg_get_expr(polwithcheck,polrelid)) ORDER BY polname),''[]''::jsonb) FROM pg_policy WHERE polrelid=c.oid),\n ''triggers'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''name'',tgname,''type'',tgtype,''enabled'',tgenabled,''definition'',pg_get_triggerdef(oid,true),''function'',tgfoid::regprocedure::text,''arguments_hex'',encode(tgargs,''hex''),''deferrable'',tgdeferrable,''deferred'',tginitdeferred,''parent'',CASE WHEN tgparentid=0 THEN NULL ELSE (SELECT tgname FROM pg_trigger p WHERE p.oid=t.tgparentid) END) ORDER BY tgname),''[]''::jsonb) FROM pg_trigger t WHERE tgrelid=c.oid AND NOT tgisinternal)) ORDER BY c.relname),''[]''::jsonb) FROM own c LEFT JOIN pg_am am ON am.oid=c.relam WHERE c.relkind IN(''r'',''p'',''v'',''m'',''S'',''f'')),\n ''functions'',(SELECT coalesce(jsonb_agg(public.pim_dictionary_function_metadata(oid)||jsonb_build_object(''body_sha256'',encode(sha256(convert_to(prosrc,''UTF8'')),''hex'')) ORDER BY oid::regprocedure::text),''[]''::jsonb) FROM own_functions),\n ''types'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''name'',t.typname,''kind'',t.typtype,''category'',t.typcategory,''owner'',pg_get_userbyid(t.typowner),''relation'',CASE WHEN t.typrelid=0 THEN NULL ELSE t.typrelid::regclass::text END,''element'',CASE WHEN t.typelem=0 THEN NULL ELSE format_type(t.typelem,NULL) END,''not_null'',t.typnotnull,''default'',t.typdefault,''acl'',public.pim_dictionary_acl_metadata(coalesce(t.typacl,acldefault(''T''::\"char\",t.typowner)))) ORDER BY t.typname),''[]''::jsonb) FROM pg_type t WHERE t.typnamespace=''public''::regnamespace AND (starts_with(t.typname,''large_import_'') OR starts_with(t.typname,''large_import173_'') OR starts_with(t.typname,''_large_import_'') OR starts_with(t.typname,''_large_import173_''))),\n ''ri'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''relation'',tr.tgrelid::regclass::text,''constraint_relation'',con.conrelid::regclass::text,''constraint'',con.conname,''definition'',pg_get_constraintdef(con.oid,true),''type'',tr.tgtype,''enabled'',tr.tgenabled,''function'',tr.tgfoid::regprocedure::text,''deferrable'',tr.tgdeferrable,''deferred'',tr.tginitdeferred) ORDER BY tr.tgrelid::regclass::text,con.conrelid::regclass::text,con.conname,tr.tgtype,tr.tgfoid::regprocedure::text),''[]''::jsonb) FROM pg_trigger tr JOIN pg_constraint con ON con.oid=tr.tgconstraint WHERE tr.tgisinternal AND (con.conrelid IN(SELECT oid FROM own) OR con.confrelid IN(SELECT oid FROM own))),\n ''roles'',(SELECT coalesce(jsonb_agg(to_jsonb(r)-''oid''-''rolpassword'' ORDER BY rolname),''[]''::jsonb) FROM pg_roles r WHERE oid IN(SELECT role_oid FROM reachable)),\n ''memberships'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''role'',pg_get_userbyid(roleid),''member'',pg_get_userbyid(member),''grantor'',pg_get_userbyid(grantor),''admin'',admin_option,''inherit'',inherit_option,''set'',set_option) ORDER BY roleid::regrole::text,member::regrole::text,grantor::regrole::text),''[]''::jsonb) FROM pg_auth_members WHERE member IN(SELECT role_oid FROM reachable) OR roleid IN(SELECT role_oid FROM reachable))\n) profile\n$function$\n","volatility":"s","body_sha256":"81524c6bc5da32a658b18f0c3f5fef32d768691fda0664bc98ae248665b5612a","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":null,"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"large_import173_parents_valid()","definition":"CREATE OR REPLACE FUNCTION public.large_import173_parents_valid()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE expected record;live_sha text;\nBEGIN\n -- Delegation is permitted only for these exact native172 bodies. The certificate\n -- relation forces the successor172 branch; no legacy fallback or cached result.\n IF to_regclass(''public.nested172_certificate'') IS NULL THEN RETURN false;END IF;\n FOR expected IN SELECT * FROM (VALUES\n  (''public.pim_dictionary_valid()'', ''15e70233f2034a1b19b049711f24d94d64ea0080c90625bb44ebb1ce49560c7e''),\n  (''public.cooperation171_valid()'', ''550e10f6a3be197027f6c988acf6d5d9bd0b5fb7ca0fb1d3f862fdd0fcd08a02''),\n  (''public.nested172_valid()'', ''1d3e63bd885f67080c1853096fea874330c8ced95159d9281939121758ba411a''),\n  (''public.allegro_oauth_recovery_guards()'', ''21639c3a667015d3f6fcaad2a8dede2cee11e06f92c7ca877606100ebda9e72a''),\n  (''public.b2b_credit_guards()'', ''893976b1d7c74acaadfb73d889d428e85e5094dc1a4f5d2b0594f9285e6cd5fa''),\n  (''public.b2b_invoice_guards()'', ''11193b4ee37704b67d9406bff59ae3f9f55a70695042154f5fb84b75a5002d93''),\n  (''public.buyer_address_guards()'', ''390878abaad2515009a8ae2093f8f4f3d1a1c5ede13ad09ec7b846b965de70d1''),\n  (''public.catalog_stock_control_guards()'', ''ef9c31fbabca36776256efe76dcd16265c9f742ce4a64cbd7cc000c056baf225''),\n  (''public.catalog_stock_count_guards()'', ''1afbf9ac78263f0ef3cffece731866a5e31f98f8eaf9a65149cb9711fed1b98c''),\n  (''public.catalog_stock_legacy_group_guards()'', ''6c029457e72db444bbbf027e81ac944e5176024192d47166b10ce7b7c7e2bbdc''),\n  (''public.catalog_stock_return_guards()'', ''10e530165ee50fdc8dc19501d97ac41819ed00ecf22b99995e0bcd24ce8453ec''),\n  (''public.competitor_observation_guards()'', ''b6088d080b4287caa3aaaa5715a48c47d8ab271b4deeb10bdb818b04bf2e6438''),\n  (''public.credit_source_upgrade_valid()'', ''f190ad4c0910b8c4fc1b096f8083c8fb31e0608cdb5e1322746c432b1cc9b476''),\n  (''public.fa3_draft_guards()'', ''96df6ad175f209dc8fb3745e3309ef7b90ad6beae50e2739a5d832078a261ec4''),\n  (''public.financial_return_guards()'', ''a93da2ff6e455726f85d6cc2b5b8b61cde4100e1d835dcfd5b0f707b2307f671''),\n  (''public.financial_return_upgrade_valid()'', ''42700137d0b72c471