OR encode(sha256(convert_to(p::text,''UTF8'')),''hex'') IS DISTINCT FROM c.profile_sha256\n OR public.large_import173_predecessor_map() IS DISTINCT FROM c.predecessor_map\n OR encode(sha256(convert_to(c.predecessor_map::text,''UTF8'')),''hex'') IS DISTINCT FROM c.predecessor_sha256\n OR c.module_sql_sha256 IS DISTINCT FROM ''7fafb32748feabb30345c87509936c36730c748923012ca3f54b3e0cde175138'' THEN RETURN false;END IF;\n RETURN public.large_import173_parents_valid();\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND\n$function$\n","volatility":"s","body_sha256":"58b68b0436150efc777db963b95f82035c20d2f0f33cb24e189b167dded76560","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":null,"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"expected_profile_sha256 text","leakproof":false,"signature":"large_import173_validate_recovered(text)","definition":"CREATE OR REPLACE FUNCTION public.large_import173_validate_recovered(expected_profile_sha256 text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nBEGIN\n -- Detached restoration compares portable descriptors, roles and bodies; never claims restored OID equality.\n PERFORM public.large_import173_require(expected_profile_sha256);RETURN true;\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND\n$function$\n","volatility":"s","body_sha256":"dee202c9a413276483b51901e4052cdb2bca42c9cdb25de67062b33820e29578","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["expected_profile_sha256"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"trigger","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"large_import_core_review173_guard()","definition":"CREATE OR REPLACE FUNCTION public.large_import_core_review173_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE j public.large_import_jobs173%ROWTYPE; old_review public.large_import_core_reviews173%ROWTYPE;\n state jsonb; r jsonb; b jsonb; c jsonb; page jsonb; resolution jsonb; row_json jsonb; native_row jsonb;\n canonical_scope text; projection jsonb; projected_batches jsonb:=''[]''::jsonb; actual_rows jsonb; request_text text; rows_text text;\n p public.catalog_file_import_previews%ROWTYPE; nr public.catalog_file_import_rows%ROWTYPE;\n n integer:=0; page_no integer; count_rows integer; total_rows integer:=0;\n lock_key bigint; ref jsonb; ids uuid[]:=ARRAY[]::uuid[]; batches integer[]:=ARRAY[]::integer[];\n links jsonb:=''[]''::jsonb; target uuid; old_revision bigint;\nBEGIN\n IF TG_OP<>''INSERT'' THEN RAISE EXCEPTION ''CoreReview history is append only'' USING ERRCODE=''23514''; END IF;\n -- SECURITY DEFINER is solely for trigger-local reads/private predicates; no callable app EXECUTE grants.\n -- This role/tenant evidence is not a genuine current Actor/session/IAM substitute.\n IF NOT (current_setting(''role'',true)=''dyna_app'' OR current_setting(''role'',true)=''none'' AND session_user=''dyna_app'')\n OR nullif(current_setting(''app.tenant_id'',true),'''')::uuid IS DISTINCT FROM NEW.tenant_id\n THEN RAISE EXCEPTION ''CoreReview requires native app role and tenant'' USING ERRCODE=''42501''; END IF;\n lock_key:=hashtextextended(''large-import173:''||NEW.tenant_id::text||'':''||NEW.job_id::text,0);\n IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks l WHERE l.locktype=''advisory''\n AND l.pid=pg_backend_pid() AND l.database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())\n AND l.mode=''ExclusiveLock'' AND l.granted IS TRUE AND l.objsubid=1\n AND l.classid::bigint=((lock_key>>32)&4294967295::bigint) AND l.objid::bigint=(lock_key&4294967295::bigint))\n THEN RAISE EXCEPTION ''CoreReview requires exact owned Job advisory key'' USING ERRCODE=''23514''; END IF;\n SELECT * INTO STRICT j FROM public.large_import_jobs173 WHERE tenant_id=NEW.tenant_id AND id=NEW.job_id FOR UPDATE;\n IF j.actor_id IS DISTINCT FROM NEW.actor_id OR j.api_key_id IS DISTINCT FROM NEW.api_key_id\n OR j.revision IS DISTINCT FROM NEW.job_revision OR j.lease_fence IS DISTINCT FROM NEW.lease_fence\n OR j.lease_token IS NULL OR j.leased_at IS NULL\n THEN RAISE EXCEPTION ''CoreReview current Job owner/revision/fence differs'' USING ERRCODE=''23514''; END IF;\n -- lease_token comparison against the private caller token is additionally enforced by the same-client adapter.\n -- No token is stored in immutable review evidence; actor/API-key presence is not authenticated authority.\n state:=j.state_text::jsonb; r:=NEW.review_text::jsonb;\n IF public.large_import_core_review173_keys(r,ARRAY[''schema'',''revision'',''source_plan_hash'',''raw'',''parsing_spec'',''batches'',''aggregate_scope_hash'',''approved_scope_hash'']) IS DISTINCT FROM true\n OR r->>''schema'' IS DISTINCT FROM ''large-import-core-review/v1''\n OR jsonb_typeof(r->''revision'') IS DISTINCT FROM ''number'' OR (r->>''revision'') !~ ''^(0|[1-9][0-9]*)$''\n OR (r->>''revision'')::numeric IS DISTINCT FROM NEW.revision::numeric\n OR r->>''source_plan_hash'' IS DISTINCT FROM j.plan_hash OR public.large_import_core_review173_ref(r->''raw'') IS DISTINCT FROM true OR r->''raw'' IS DISTINCT FROM state->''raw''\n OR r->''parsing_spec'' IS DISTINCT FROM state->''parsing_spec'' OR state->''approved'' IS DISTINCT FROM ''true''::jsonb\n OR jsonb_typeof(r->''batches'') IS DISTINCT FROM ''array''\n OR jsonb_array_length(r->''batches'') IS DISTINCT FROM jsonb_array_length(state->''core'') OR jsonb_array_length(r->''batches'')=0\n OR r->>''aggregate_scope_hash'' IS DISTINCT FROM NEW.aggregate_scope_hash\n OR r->''approved_scope_hash'' IS DISTINCT FROM coalesce(to_jsonb(NEW.approved_scope_hash),''null''::jsonb)\n OR jsonb_array_length(NEW.request_texts) IS DISTINCT FROM jsonb_array_length(r->''batches'')\n OR jsonb_array_length(NEW.row_texts) IS DISTINCT FROM jsonb_array_length(r->''batches'')\n THEN RAISE EXCEPTION ''CoreReview closed envelope/Job scope differs'' USING ERRCODE=''23514''; END IF;\n FOR b IN SELECT value FROM jsonb_array_elements(r->''batches'') LOOP\n  c:=state->''core''->n;\n  IF public.large_import_core_review173_keys(b,ARRAY[''index'',''preview_id'',''scope_hash'',''preview_key'',''execute_key'',''request_hash'',''rows_hash'',''resolution'',''eligibility'',''preview'']) IS DISTINCT FROM true\n  OR b->''index'' IS DISTINCT FROM to_jsonb(n)\n  OR b->>''preview_id'' IS DISTINCT FROM c#>>''{preview,ack,head,id}''\n  OR b->>''scope_hash'' IS DISTINCT FROM c#>>''{preview,ack,head,scope_hash}''\n  OR b->>''preview_key'' IS DISTINCT FROM c->>''previewKey'' OR b->>''execute_key'' IS DISTINCT FROM c->>''executeKey''\n  OR jsonb_typeof(b->''request_hash'') IS DISTINCT FROM ''string'' OR (b->>''request_hash'') !~ ''^[a-f0-9]{64}$''\n  OR jsonb_typeof(b->''rows_hash'') IS DISTINCT FROM ''string'' OR (b->>''rows_hash'') !~ ''^[a-f0-9]{64}$''\n  OR public.large_import_core_review173_keys(b#>''{preview,ack}'',ARRAY[''head'',''witness'',''reused'']) IS DISTINCT FROM true\n  OR public.large_import_core_review173_ref(b#>''{preview,ack,witness}'') IS DISTINCT FROM true\n  OR jsonb_typeof(b#>''{preview,ack,reused}'') IS DISTINCT FROM ''boolean''\n  OR public.large_import_core_review173_keys(b->''preview'',ARRAY[''ack'',''pages'']) IS DISTINCT FROM true\n  OR b#>''{preview,ack}'' IS DISTINCT FROM c#>''{preview,ack}''\n  OR jsonb_typeof(b#>''{preview,pages}'') IS DISTINCT FROM ''array''\n  OR jsonb_array_length(b#>''{preview,pages}'') NOT BETWEEN 1 AND 5\n  OR jsonb_typeof(b->''resolution'') IS DISTINCT FROM ''array''\n  THEN RAISE EXCEPTION ''CoreReview batch/native keys differ'' USING ERRCODE=''23514''; END IF;\n  IF jsonb_typeof(NEW.request_texts->n) IS DISTINCT FROM ''string'' OR jsonb_typeof(NEW.row_texts->n) IS DISTINCT FROM ''string''\n  THEN RAISE EXCEPTION ''CoreReview exact digest texts are required'' USING ERRCODE=''23514''; END IF;\n  request_text:=NEW.request_texts->>n; rows_text:=NEW.row_texts->>n;\n  IF encode(sha256(convert_to(request_text,''UTF8'')),''hex'') IS DISTINCT FROM b->>''request_hash''\n  OR request_text::jsonb IS DISTINCT FROM c->''request''\n  OR encode(sha256(convert_to(rows_text,''UTF8'')),''hex'') IS DISTINCT FROM b->>''rows_hash''\n  THEN RAISE EXCEPTION ''CoreReview exact text digests differ'' USING ERRCODE=''23514''; END IF;\n  SELECT * INTO STRICT p FROM public.catalog_file_import_previews WHERE tenant_id=NEW.tenant_id AND id=(b->>''preview_id'')::uuid;\n  IF p.actor_id IS DISTINCT FROM NEW.actor_id OR p.client_key IS DISTINCT FROM (b->>''preview_key'')::uuid\n  OR p.scope_hash IS DISTINCT FROM b->>''scope_hash'' OR p.ready IS DISTINCT FROM true\n  OR p.config IS DISTINCT FROM ((c->''request'')-ARRAY[''content'',''client_key''])\n  OR p.source IS DISTINCT FROM (CASE WHEN NEW.api_key_id IS NULL THEN ''manual'' ELSE ''api'' END)\n  OR (b#>''{preview,ack,head}'') IS DISTINCT FROM jsonb_build_object(''id'',p.id,''actor_id'',p.actor_id,''scope_hash'',p.scope_hash,\n    ''total'',p.total,''created'',p.created,''updated'',p.updated,''unchanged'',p.unchanged,''invalid'',p.invalid,''ready'',p.ready,\n    ''created_at'',b#>''{preview,ack,head,created_at}'',''config'',p.config,''active_product_rules'',jsonb_array_length(p.rules_snapshot))\n  -- The existing HTTP pg Date projection is millisecond precision; preserve native UTC timestamp separately.\n  OR jsonb_typeof(b#>''{preview,ack,head,created_at}'') IS DISTINCT FROM ''string''\n  OR (b#>>''{preview,ack,head,created_at}'')::timestamptz IS DISTINCT FROM date_trunc(''milliseconds'',p.created_at)\n  OR (SELECT count(*) FROM public.catalog_file_import_rows WHERE tenant_id=NEW.tenant_id AND preview_id=p.id)<>p.total\n  THEN RAISE EXCEPTION ''CoreReview actual native preview differs'' USING ERRCODE=''23514''; END IF;\n  SELECT jsonb_agg((to_jsonb(x)-ARRAY[''tenant_id'',''preview_id'',''byte_count''])||jsonb_build_object(''changes'',x.input) ORDER BY x.index)\n  INTO actual_rows FROM public.catalog_file_import_rows x WHERE x.tenant_id=NEW.tenant_id AND x.preview_id=p.id;\n  IF rows_text::jsonb IS DISTINCT FROM actual_rows\n  OR (SELECT jsonb_agg(rr.v ORDER BY pg.page_ord,rr.ord)\n    FROM jsonb_array_elements(c#>''{preview,pages}'') WITH ORDINALITY pg(page_value,page_ord)\n    CROSS JOIN LATERAL jsonb_array_elements(pg.page_value->''rows'') WITH ORDINALITY rr(v,ord)) IS DISTINCT FROM actual_rows\n  THEN RAISE EXCEPTION ''CoreReview digest text/full saved rows differ from native producer'' USING ERRCODE=''23514''; END IF;\n  page_no:=0;count_rows:=0;\n  FOR page IN SELECT value FROM jsonb_array_elements(b#>''{preview,pages}'') LOOP\n   IF public.large_import_core_review173_keys(page,ARRAY[''head'',''rows'',''next'',''witness'']) IS DISTINCT FROM true\n   OR page->''head'' IS DISTINCT FROM b#>''{preview,ack,head}'' OR public.large_import_core_review173_ref(page->''witness'') IS DISTINCT FROM true\n   OR jsonb_typeof(page->''rows'') IS DISTINCT FROM ''array'' OR jsonb_array_length(page->''rows'') NOT BETWEEN 1 AND 100\n   THEN RAISE EXCEPTION ''CoreReview closed page differs'' USING ERRCODE=''23514''; END IF;\n   FOR row_json IN SELECT value FROM jsonb_array_elements(page->''rows'') LOOP\n    SELECT * INTO STRICT nr FROM public.catalog_file_import_rows WHERE tenant_id=NEW.tenant_id AND preview_id=p.id AND index=count_rows;\n    native_row:=(to_jsonb(nr)-ARRAY[''tenant_id'',''preview_id'',''byte_count''])||jsonb_build_object(''changes'',nr.input);\n    resolution:=b->''resolution''->count_rows;\n    IF row_json IS DISTINCT FROM native_row OR nr.errors IS DISTINCT FROM ''[]''::jsonb OR nr.operation NOT IN (''create'',''update'',''unchanged'')\n    OR nr.identity_value IS DISTINCT FROM c->''identities''->>count_rows\n    OR public.large_import_core_review173_keys(resolution,ARRAY[''ordinal'',''product_id'',''operation'']) IS DISTINCT FROM true\n    OR resolution->''ordinal'' IS DISTINCT FROM to_jsonb(total_rows) OR nr.product_id IS NULL\n    OR jsonb_typeof(resolution->''product_id'') IS DISTINCT FROM ''string''\n    OR (resolution->>''product_id'') !~* ''^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$''\n    OR (resolution->>''product_id'')::uuid IS DISTINCT FROM nr.product_id\n    OR resolution->>''operation'' IS DISTINCT FROM nr.operation OR nr.product_id=ANY(ids)\n    OR (nr.after->>''id'')::uuid IS DISTINCT FROM nr.product_id OR jsonb_typeof(nr.after->''components'') IS DISTINCT FROM ''array''\n    THEN RAISE EXCEPTION ''CoreReview full native row/resolution differs'' USING ERRCODE=''23514''; END IF;\n    ids:=array_append(ids,nr.product_id);batches:=array_append(batches,n);\n    IF nr.after->>''parent_id'' IS NOT NULL THEN links:=links||jsonb_build_array(jsonb_build_object(''batch'',n,''id'',(nr.after->>''parent_id'')::uuid)); END IF;\n    FOR ref IN SELECT value FROM jsonb_array_elements(nr.after->''components'') LOOP\n     IF jsonb_typeof(ref->''product_id'') IS DISTINCT FROM ''string'' OR (ref->>''product_id'') !~* ''^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$''\n     THEN RAISE EXCEPTION ''CoreReview native component UUID is required'' USING ERRCODE=''23514''; END IF;\n     links:=links||jsonb_build_array(jsonb_build_object(''batch'',n,''id'',(ref->>''product_id'')::uuid));\n    END LOOP;\n    count_rows:=count_rows+1;total_rows:=total_rows+1;\n   END LOOP;\n   IF page_no=jsonb_array_length(b#>''{preview,pages}'')-1 THEN\n    IF page->''next'' IS DISTINCT FROM ''null''::jsonb THEN RAISE EXCEPTION ''CoreReview final cursor differs'' USING ERRCODE=''23514''; END IF;\n   ELSIF page->''next'' IS DISTINCT FROM to_jsonb(count_rows::text) OR count_rows>=p.total\n   THEN RAISE EXCEPTION ''CoreReview intermediate cursor differs'' USING ERRCODE=''23514''; END IF;\n   page_no:=page_no+1;\n  END LOOP;\n  IF count_rows<>p.total OR count_rows<>jsonb_array_length(c->''identities'') OR count_rows<>jsonb_array_length(b->''resolution'')\n  THEN RAISE EXCEPTION ''CoreReview full batch count differs'' USING ERRCODE=''23514''; END IF;\n  IF public.large_import_core_review173_keys(b->''eligibility'',ARRAY[''eligible'',''authority_revision'',''source_hash'',''sources'',''quota_witness'']) IS DISTINCT FROM true\n  OR jsonb_typeof(b#>''{eligibility,eligible}'') IS DISTINCT FROM ''boolean''\n  OR jsonb_typeof(b#>''{eligibility,authority_revision}'') IS DISTINCT FROM ''string'' OR length(b#>>''{eligibility,authority_revision}'')=0\n  OR jsonb_typeof(b#>''{eligibility,source_hash}'') IS DISTINCT FROM ''string'' OR (b#>>''{eligibility,source_hash}'') !~ ''^[a-f0-9]{64}$''\n  OR jsonb_typeof(b#>''{eligibility,sources}'') IS DISTINCT FROM ''array'' OR jsonb_array_length(b#>''{eligibility,sources}'')=0\n  OR public.large_import_core_review173_ref(b#>''{eligibility,quota_witness}'') IS DISTINCT FROM true\n  THEN RAISE EXCEPTION ''CoreReview eligibility witness shape differs'' USING ERRCODE=''23514''; END IF;\n  FOR ref IN SELECT value FROM jsonb_array_elements(b#>''{eligibility,sources}'') LOOP\n   IF public.large_import_core_review173_ref(ref) IS DISTINCT FROM true THEN RAISE EXCEPTION ''CoreReview source witness shape differs'' USING ERRCODE=''23514''; END IF;\n  END LOOP;\n  projected_batches:=projected_batches||jsonb_build_array(jsonb_build_object(''index'',n,''preview_id'',b->''preview_id'',''scope_hash'',b->''scope_hash'',\n    ''preview_key'',b->''preview_key'',''execute_key'',b->''execute_key'',''request_hash'',b->''request_hash'',''rows_hash'',b->''rows_hash'',''resolution'',b->''resolution'',\n    ''source_hash'',b#>''{eligibility,source_hash}'',''authority_revision'',b#>''{eligibility,authority_revision}''));\n  n:=n+1;\n END LOOP;\n IF total_rows<>(state#>>''{manifest,records}'')::integer THEN RAISE EXCEPTION ''CoreReview whole record count differs'' USING ERRCODE=''23514''; END IF;\n FOR ref IN SELECT value FROM jsonb_array_elements(links) LOOP\n  target:=(ref->>''id'')::uuid;\n  IF target=ANY(ids) AND batches[array_position(ids,target)]<>(ref->>''batch'')::integer\n  THEN RAISE EXCEPTION ''CoreReview cross-batch dependency requires separate plan'' USING ERRCODE=''23514''; END IF;\n END LOOP;\n projection:=jsonb_build_object(''schema'',r->''schema'',''source_plan_hash'',r->''source_plan_hash'',''raw'',r->''raw'',''parsing_spec'',r->''parsing_spec'',''batches'',projected_batches);\n IF NEW.scope_text::jsonb IS DISTINCT FROM projection\n THEN RAISE EXCEPTION ''CoreReview exact scope text business projection differs'' USING ERRCODE=''23514''; END IF;\n -- Only exact scope projection reaches this native serializer. Full request/rows are NEVER passed.\n canonical_scope:=public.large_import_core_scope173_text(projection);\n IF NEW.scope_text IS DISTINCT FROM canonical_scope\n OR NEW.aggregate_scope_hash IS DISTINCT FROM encode(sha256(convert_to(canonical_scope,''UTF8'')),''hex'')\n THEN RAISE EXCEPTION ''CoreReview scope native canonical bytes/hash differ'' USING ERRCODE=''23514''; END IF;\n IF NEW.approved_scope_hash IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->''batches'') b WHERE b#>''{eligibility,eligible}'' IS DISTINCT FROM ''true''::jsonb)\n THEN RAISE EXCEPTION ''CoreReview approval requires every eligibility witness true'' USING ERRCODE=''23514''; END IF;\n SELECT * INTO old_review FROM public.large_import_core_reviews173 WHERE tenant_id=NEW.tenant_id AND job_id=NEW.job_id ORDER BY revision DESC LIMIT 1;\n IF FOUND THEN\n  -- A lost-COMMIT retry is a byte-identical no-op, not a second historical INSERT.\n  IF (NEW.actor_id,NEW.api_key_id,NEW.revision,NEW.review_text,NEW.review_sha256,NEW.aggregate_scope_hash,NEW.approved_scope_hash,NEW.scope_text,NEW.request_texts,NEW.row_texts)\n    IS NOT DISTINCT FROM (old_review.actor_id,old_review.api_key_id,old_review.revision,old_review.review_text,old_review.review_sha256,old_review.aggregate_scope_hash,old_review.approved_scope_hash,old_review.scope_text,old_review.request_texts,old_review.row_texts)\n  THEN RETURN NULL; END IF;\n  old_revision:=old_review.revision;\n ELSE\n  old_revision:=-1;\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(state->''core'') c WHERE c ? ''execution'')\n  OR EXISTS(SELECT 1 FROM public.catalog_file_import_executions e WHERE e.tenant_id=NEW.tenant_id\n    AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->''batches'') b WHERE e.preview_id=(b->>''preview_id'')::uuid))\n  THEN RAISE EXCEPTION ''Initial CoreReview cannot follow a product execution'' USING ERRCODE=''23514''; END IF;\n END IF;\n IF NEW.revision<>old_revision+1 THEN RAISE EXCEPTION ''CoreReview append revision differs'' USING ERRCODE=''23514''; END IF;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(state->''core'') WITH ORDINALITY bc(v,i)\n  WHERE NOT bc.v ? ''execution'' AND EXISTS(SELECT 1 FROM jsonb_array_elements(state->''events'') e WHERE e->>''kind''=''core-execute-attempt'' AND e->''batch''=to_jsonb((bc.i-1)::integer)))\n THEN RAISE EXCEPTION ''Unresolved original execution requires exact-key recovery'' USING ERRCODE=''23514''; END IF;\n -- Native canonical scope is enforced by the exact scoped serializer above. Native parity still requires Root PG gate.\n -- Full request/rows retain TEXT SHA + native business equality + strict JS bytes, no native whole-tree number serializer.\n -- Current Actor/session/IAM/source/quota admittance is still the genuine injected ports.admit / validateCoreBatch ABI;\n -- no such standalone native173 ABI is implemented/certified. Candidate activation is therefore NOT_APPLY_READY.\n -- A later composed current-admit/cert guard MUST close this external native-IAM trust boundary before activation.\n -- Missing ABI refuses deterministically; mere presence is NOT a certified IAM/call-context proof.\n -- Activation also requires owner-external certificate/preflight and a genuine same-transaction ports.admit.\n IF to_regprocedure(''public.large_import173_admit(uuid,uuid,uuid,text,text,boolean)'') IS NULL\n THEN RAISE EXCEPTION ''CoreReview current native admission ABI is absent'' USING ERRCODE=''0A000''; END IF;\n RETURN NEW;\nEND $function$\n","volatility":"v","body_sha256":"27072195adc4f1f2581af15f2f9c24e495a4f967c59e3a9afc2a96cebd7eb0d0","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":null,"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"sql","parallel":"u","arguments":"v jsonb, names text[]","leakproof":false,"signature":"large_import_core_review173_keys(jsonb,text[])","definition":"CREATE OR REPLACE FUNCTION public.large_import_core_review173_keys(v jsonb, names text[])\n RETURNS boolean\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''pg_catalog''\nAS $function$\n SELECT CASE WHEN jsonb_typeof(v)=''object'' THEN\n   (SELECT count(*) FROM jsonb_object_keys(v))=cardinality(names) AND v ?& names\n ELSE false END\n$function$\n","volatility":"i","body_sha256":"6d1374e0e4b405bb067f9f2bbb9a9ccff4e06642664a365262848b2f59adb6a5","returns_set":false,"configuration":["search_path=pg_catalog"],"argument_modes":null,"argument_names":["v","names"],"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"sql","parallel":"u","arguments":"v jsonb","leakproof":false,"signature":"large_import_core_review173_ref(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.large_import_core_review173_ref(v jsonb)\n RETURNS boolean\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n SELECT public.large_import_core_review173_keys(v,ARRAY[''id'',''sha256'',''byte_count''])\n AND jsonb_typeof(v->''id'')=''string'' AND length(v->>''id'')>0\n AND jsonb_typeof(v->''sha256'')=''string'' AND (v->>''sha256'')~''^[a-f0-9]{64}$''\n AND jsonb_typeof(v->''byte_count'')=''number'' AND (v->>''byte_count'')~''^(0|[1-9][0-9]*)$''\n AND (v->>''byte_count'')::numeric BETWEEN 0 AND 9007199254740991\n$function$\n","volatility":"i","body_sha256":"3aeca9a5e0b16349e1bb4d7db34cf1133d48bed1a3390e153819bacef771212d","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":["v"],"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"bigint","strict":true,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"s text","leakproof":false,"signature":"large_import_core_scope173_index(text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_core_scope173_index(s text)\n RETURNS bigint\n LANGUAGE plpgsql\n IMMUTABLE STRICT\n SET search_path TO ''pg_catalog''\nAS $function$\nBEGIN\n -- JS array-index property: canonical decimal0..2^32-2.2^32-1 and zero-padded names are ordinary strings.\n IF length(s)=0 OR length(s)>10 OR s~''[^0-9]'' OR length(s)>1 AND left(s,1)=''0'' THEN RETURN NULL;END IF;\n IF s::numeric<=4294967294 THEN RETURN s::bigint;END IF;\n RETURN NULL;\nEND $function$\n","volatility":"i","body_sha256":"3eb1ac03b91724a2a228bbbabfb42d13fc5681973ad8a0a4c5faa0b728b4c45c","returns_set":false,"configuration":["search_path=pg_catalog"],"argument_modes":null,"argument_names":["s"],"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"text","strict":false,"defaults":"0","language":"plpgsql","parallel":"u","arguments":"v jsonb, depth integer","leakproof":false,"signature":"large_import_core_scope173_json(jsonb,integer)","definition":"CREATE OR REPLACE FUNCTION public.large_import_core_scope173_json(v jsonb, depth integer DEFAULT 0)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE kind text:=jsonb_typeof(v); out text;n numeric;\nBEGIN\n IF depth<0 OR depth>8 OR v IS NULL THEN RAISE EXCEPTION ''Scope canonical JSON depth/SQL-null differs'' USING ERRCODE=''23514'';END IF;\n CASE kind\n WHEN ''null'' THEN RETURN ''null'';\n WHEN ''boolean'' THEN RETURN CASE WHEN v=''true''::jsonb THEN ''true'' ELSE ''false'' END;\n WHEN ''string'' THEN RETURN public.large_import_core_scope173_quote(v#>>''{}'');\n WHEN ''number'' THEN\n  n:=(v#>>''{}'')::numeric;\n  IF n<>trunc(n) OR abs(n)>9007199254740991 THEN RAISE EXCEPTION ''Only actual scope safe integers are serializable'' USING ERRCODE=''23514'';END IF;\n  -- JS JSON.stringify(-0)=0; scale/exponent spellings have no authority. No request/rows number reaches here.\n  RETURN trunc(n)::text;\n WHEN ''array'' THEN\n  SELECT ''[''||coalesce(string_agg(public.large_import_core_scope173_json(value,depth+1),'','' ORDER BY ord),'''')||'']'' INTO out\n  FROM jsonb_array_elements(v) WITH ORDINALITY x(value,ord);RETURN out;\n WHEN ''object'' THEN\n  SELECT ''{''||coalesce(string_agg(public.large_import_core_scope173_quote(key)||'':''||public.large_import_core_scope173_json(value,depth+1),'',''\n    ORDER BY CASE WHEN public.large_import_core_scope173_index(key) IS NULL THEN 1 ELSE 0 END,\n    public.large_import_core_scope173_index(key),public.large_import_core_scope173_utf16_key(key)),'''')||''}'' INTO out\n  FROM jsonb_each(v);RETURN out;\n ELSE RAISE EXCEPTION ''Scope canonical JSON type differs'' USING ERRCODE=''23514'';\n END CASE;\nEND $function$\n","volatility":"i","body_sha256":"917300bd4aee02a0a7190045dc19abd3fd07f0912926fec5f165f722d4b2014f","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":["v","depth"],"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"text","strict":true,"defaults":null,"language":"sql","parallel":"u","arguments":"s text","leakproof":false,"signature":"large_import_core_scope173_quote(text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_core_scope173_quote(s text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE STRICT\n SET search_path TO ''pg_catalog''\nAS $function$\n SELECT chr(34)||coalesce(string_agg(CASE\n  WHEN cp=34 OR cp=92 THEN chr(92)||ch\n  WHEN cp=8 THEN chr(92)||''b'' WHEN cp=9 THEN chr(92)||''t'' WHEN cp=10 THEN chr(92)||''n''\n  WHEN cp=12 THEN chr(92)||''f'' WHEN cp=13 THEN chr(92)||''r''\n  WHEN cp<32 THEN chr(92)||''u''||lpad(to_hex(cp),4,''0'')\n  ELSE ch END,'''' ORDER BY i),'''')||chr(34)\n FROM (SELECT i,substr(s,i,1) ch,ascii(substr(s,i,1)) cp FROM generate_series(1,char_length(s)) i) x\n$function$\n","volatility":"i","body_sha256":"3160d024209b65a6811aa603ea012414250eab677a3b1482db0bda43611aff5a","returns_set":false,"configuration":["search_path=pg_catalog"],"argument_modes":null,"argument_names":["s"],"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"text","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"scope jsonb","leakproof":false,"signature":"large_import_core_scope173_text(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.large_import_core_scope173_text(scope jsonb)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE spec jsonb;b jsonb;r jsonb;k text;value jsonb;cap bigint;batch_no integer:=0;ordinal integer:=0;text_value text;\nBEGIN\n IF getdatabaseencoding()<>''UTF8'' THEN RAISE EXCEPTION ''Scope Unicode serialization requires UTF8 database'' USING ERRCODE=''0A000'';END IF;\n -- These constraints match frozen Job Spec/Ref limits; they NEVER validate/narrow full request or rows.\n IF public.large_import_core_review173_keys(scope,ARRAY[''schema'',''source_plan_hash'',''raw'',''parsing_spec'',''batches'']) IS DISTINCT FROM true\n OR scope->>''schema'' IS DISTINCT FROM ''large-import-core-review/v1''\n OR jsonb_typeof(scope->''source_plan_hash'') IS DISTINCT FROM ''string'' OR (scope->>''source_plan_hash'') !~ ''^[a-f0-9]{64}$''\n OR public.large_import_core_review173_keys(scope->''raw'',ARRAY[''id'',''sha256'',''byte_count'']) IS DISTINCT FROM true\n OR jsonb_typeof(scope#>''{raw,id}'') IS DISTINCT FROM ''string'' OR length(scope#>>''{raw,id}'')=0 OR octet_length(scope#>>''{raw,id}'')>500\n OR jsonb_typeof(scope#>''{raw,sha256}'') IS DISTINCT FROM ''string'' OR (scope#>>''{raw,sha256}'') !~ ''^[a-f0-9]{64}$''\n OR jsonb_typeof(scope#>''{raw,byte_count}'') IS DISTINCT FROM ''number''\n OR (scope#>>''{raw,byte_count}'')::numeric<>trunc((scope#>>''{raw,byte_count}'')::numeric)\n OR (scope#>>''{raw,byte_count}'')::numeric NOT BETWEEN 0 AND 67108864\n OR jsonb_typeof(scope->''batches'') IS DISTINCT FROM ''array'' OR jsonb_array_length(scope->''batches'') NOT BETWEEN 1 AND 100000\n THEN RAISE EXCEPTION ''Scope canonical projection shape differs'' USING ERRCODE=''23514'';END IF;\n spec:=scope->''parsing_spec'';\n IF spec->>''format''=''csv'' THEN\n  IF jsonb_typeof(spec) IS DISTINCT FROM ''object'' OR NOT(spec ?& ARRAY[''format'',''delimiter''])\n  OR EXISTS(SELECT 1 FROM jsonb_object_keys(spec) AS object_keys(key_name) WHERE object_keys.key_name<>ALL(ARRAY[''format'',''delimiter'',''limits'']))\n  OR jsonb_typeof(spec->''delimiter'') IS DISTINCT FROM ''string'' OR spec->>''delimiter'' NOT IN ('','','';'',chr(9),''|'')\n  THEN RAISE EXCEPTION ''Scope CSV Spec differs'' USING ERRCODE=''23514'';END IF;\n ELSE\n  IF jsonb_typeof(spec) IS DISTINCT FROM ''object'' OR spec->>''format'' IS DISTINCT FROM ''xml'' OR NOT(spec ?& ARRAY[''format'',''recordPath''])\n  OR EXISTS(SELECT 1 FROM jsonb_object_keys(spec) AS object_keys(key_name) WHERE object_keys.key_name<>ALL(ARRAY[''format'',''recordPath'',''limits'']))\n  OR jsonb_typeof(spec->''recordPath'') IS DISTINCT FROM ''string'' OR length(spec->>''recordPath'')=0\n  OR octet_length(public.large_import_core_scope173_utf16_key(spec->>''recordPath''))/2>1024\n  THEN RAISE EXCEPTION ''Scope XML Spec differs'' USING ERRCODE=''23514'';END IF;\n END IF;\n IF spec ? ''limits'' THEN\n  IF jsonb_typeof(spec->''limits'') IS DISTINCT FROM ''object'' THEN RAISE EXCEPTION ''Scope limits differ'' USING ERRCODE=''23514'';END IF;\n  FOR k,value IN SELECT fields.key,fields.value FROM jsonb_each(spec->''limits'') fields LOOP\n   cap:=CASE k WHEN ''maxFileBytes'' THEN 30000000 WHEN ''maxRecords'' THEN 100000 WHEN ''batchRows'' THEN 500 WHEN ''batchBytes'' THEN 2097152\n    WHEN ''maxRecordBytes'' THEN 1048576 WHEN ''maxTokenBytes'' THEN 1048576 WHEN ''maxColumns'' THEN 1000 WHEN ''xmlDepth'' THEN 16 WHEN ''xmlNodes'' THEN 1000000 ELSE NULL END;\n   IF cap IS NULL OR jsonb_typeof(value) IS DISTINCT FROM ''number'' OR (value#>>''{}'')::numeric<>trunc((value#>>''{}'')::numeric)\n   OR (value#>>''{}'')::numeric NOT BETWEEN 1 AND cap THEN RAISE EXCEPTION ''Scope actual Spec limit differs'' USING ERRCODE=''23514'';END IF;\n  END LOOP;\n END IF;\n FOR b IN SELECT elements.value FROM jsonb_array_elements(scope->''batches'') elements LOOP\n  IF public.large_import_core_review173_keys(b,ARRAY[''index'',''preview_id'',''scope_hash'',''preview_key'',''execute_key'',''request_hash'',''rows_hash'',''resolution'',''source_hash'',''authority_revision'']) IS DISTINCT FROM true\n  OR b->''index'' IS DISTINCT FROM to_jsonb(batch_no)\n  OR jsonb_typeof(b->''authority_revision'') IS DISTINCT FROM ''string'' OR length(b->>''authority_revision'')=0\n  OR jsonb_typeof(b->''resolution'') IS DISTINCT FROM ''array'' OR jsonb_array_length(b->''resolution'') NOT BETWEEN 1 AND 500\n  THEN RAISE EXCEPTION ''Scope batch projection differs'' USING ERRCODE=''23514'';END IF;\n  FOREACH k IN ARRAY ARRAY[''scope_hash'',''request_hash'',''rows_hash'',''source_hash''] LOOP\n   IF jsonb_typeof(b->k) IS DISTINCT FROM ''string'' OR (b->>k) !~ ''^[a-f0-9]{64}$'' THEN RAISE EXCEPTION ''Scope hash scalar differs'' USING ERRCODE=''23514'';END IF;\n  END LOOP;\n  FOREACH k IN ARRAY ARRAY[''preview_id'',''preview_key'',''execute_key''] LOOP\n   IF jsonb_typeof(b->k) IS DISTINCT FROM ''string'' OR (b->>k) !~* ''^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$''\n   THEN RAISE EXCEPTION ''Scope UUID scalar differs'' USING ERRCODE=''23514'';END IF;\n  END LOOP;\n  FOR r IN SELECT elements.value FROM jsonb_array_elements(b->''resolution'') elements LOOP\n   IF public.large_import_core_review173_keys(r,ARRAY[''ordinal'',''product_id'',''operation'']) IS DISTINCT FROM true OR r->''ordinal'' IS DISTINCT FROM to_jsonb(ordinal)\n   OR ordinal>=100000 OR jsonb_typeof(r->''product_id'') IS DISTINCT FROM ''string'' OR (r->>''product_id'') !~* ''^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$''\n   OR jsonb_typeof(r->''operation'') IS DISTINCT FROM ''string'' OR r->>''operation'' NOT IN (''create'',''update'',''unchanged'')\n   THEN RAISE EXCEPTION ''Scope resolution projection differs'' USING ERRCODE=''23514'';END IF;\n   ordinal:=ordinal+1;\n  END LOOP;\n  batch_no:=batch_no+1;\n END LOOP;\n text_value:=public.large_import_core_scope173_json(scope);\n IF octet_length(text_value)>67108864 THEN RAISE EXCEPTION ''Scope canonical text exceeds metadata bound'' USING ERRCODE=''54000'';END IF;\n RETURN text_value;\nEND $function$\n","volatility":"i","body_sha256":"d36a1230f3c98ef00d0ce3e2ca7e687fe5517aaf4a94394cd9b57bb1eded447c","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":["scope"],"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"bytea","strict":true,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"s text","leakproof":false,"signature":"large_import_core_scope173_utf16_key(text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_core_scope173_utf16_key(s text)\n RETURNS bytea\n LANGUAGE plpgsql\n IMMUTABLE STRICT\n SET search_path TO ''pg_catalog''\nAS $function$\nDECLARE i integer; cp integer; out text:='''';\nBEGIN\n FOR i IN 1..char_length(s) LOOP\n  cp:=ascii(substr(s,i,1));\n  IF cp<65536 THEN out:=out||lpad(to_hex(cp),4,''0'');\n  ELSE cp:=cp-65536;out:=out||lpad(to_hex(55296+cp/1024),4,''0'')||lpad(to_hex(56320+cp%1024),4,''0'');END IF;\n END LOOP;\n RETURN decode(out,''hex'');\nEND $function$\n","volatility":"i","body_sha256":"458dd8f7104fac8525aec5424a759a23634c7cb8ff40a5f39cf3f2dc800cf9b9","returns_set":false,"configuration":["search_path=pg_catalog"],"argument_modes":null,"argument_names":["s"],"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid","leakproof":false,"signature":"large_import_quota_absent_begin173(uuid,uuid,uuid,text,text,uuid,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_absent_begin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;old record;x record;policy_count integer;prefix0 text;paths0 text[];resources0 jsonb;\nBEGIN\n IF current_setting(''transaction_isolation'') IS DISTINCT FROM ''read committed'' THEN RAISE EXCEPTION ''Absent reconciliation requires READ COMMITTED'' USING ERRCODE=''25000'';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:global'',0));PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:tenant:''||t::text,0));\n PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN(''global'',''tenant:''||t::text) ORDER BY scope FOR SHARE;GET DIAGNOSTICS policy_count=ROW_COUNT;\n IF policy_count<>2 THEN RAISE EXCEPTION ''Absent reconciliation quota policies missing'' USING ERRCODE=''55000'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.kind IS DISTINCT FROM ''upload'' OR client0 IS NULL THEN RAISE EXCEPTION ''Absent reconciliation upload not owned'' USING ERRCODE=''42501'';END IF;\n IF b.state=''retained'' THEN\n  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=''event:upload-absent-close:''||client0::text AND state=''settled'';\n  IF NOT FOUND OR b.outcome IS DISTINCT FROM ''absent'' OR old.payload_text::jsonb->''receipt''->>''client_key'' IS DISTINCT FROM client0::text THEN RAISE EXCEPTION ''Absent reconciliation original key conflict'' USING ERRCODE=''23505'';END IF;\n  RETURN jsonb_build_object(''reused'',true,''reservation'',to_jsonb(b)-''token_hash'',''receipt'',old.payload_text::jsonb->''receipt'');\n END IF;\n IF b.state IS DISTINCT FROM ''unknown'' THEN RAISE EXCEPTION ''Absent reconciliation requires committed unknown writer fence'' USING ERRCODE=''40001'';END IF;\n -- UPDATE conflicts with every mandatory writer SHARE pin. A prior writer completes before this cut;\n -- strengthened publication_pin requires OPEN, so no later writer may publish while/after UNKNOWN.\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n prefix0:=t::text||''/''||u::text||''/''||CASE WHEN k IS NULL THEN ''sessions'' ELSE ''key-''||k::text END;\n paths0:=ARRAY[t::text,t::text||''/''||u::text,prefix0,prefix0||''/uploads'',prefix0||''/uploads/''||b.request_id::text];\n SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE \"C\"),''[]''::jsonb) INTO resources0 FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;\n IF jsonb_array_length(resources0)<>5 THEN RAISE EXCEPTION ''Absent reconciliation requires exact five-directory prefix'' USING ERRCODE=''23514'';END IF;\n FOR x IN SELECT * FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q ORDER BY resource_key COLLATE \"C\" FOR UPDATE LOOP\n  IF x.state IS DISTINCT FROM ''intent'' OR x.kind IS DISTINCT FROM ''blob'' OR x.payload_text IS NULL\n  OR x.payload_text::jsonb->>''schema'' IS DISTINCT FROM ''private-directory-allocation/v1''\n  OR NOT ((x.payload_text::jsonb->>''path'')=ANY(paths0))\n  OR x.payload_text::jsonb IS DISTINCT FROM jsonb_build_object(''schema'',''private-directory-allocation/v1'',''path'',x.payload_text::jsonb->>''path'',''mode'',448)\n  OR x.resource_key IS DISTINCT FROM ''blob:fs:directory:''||encode(sha256(convert_to(x.payload_text::jsonb->>''path'',''UTF8'')),''hex'')\n  OR x.byte_count IS DISTINCT FROM octet_length(x.payload_text)::bigint OR x.sha256 IS DISTINCT FROM encode(sha256(convert_to(x.payload_text,''UTF8'')),''hex'') THEN RAISE EXCEPTION ''Absent reconciliation original directory allocation mismatch'' USING ERRCODE=''23514'';END IF;\n END LOOP;\n IF (SELECT count(DISTINCT z.payload_text::jsonb->>''path'') FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q)<>5 THEN RAISE EXCEPTION ''Absent reconciliation duplicate paths'' USING ERRCODE=''23514'';END IF;\n -- Conservative scope: this special prefix accepts no actor-owned blob/job/review metadata at all.\n -- Child parts/batches/events cannot exist without their FK parents. General failed uploads use a different keeper.\n IF EXISTS(SELECT 1 FROM public.large_import_blobs173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k)\n OR EXISTS(SELECT 1 FROM public.large_import_jobs173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k)\n OR EXISTS(SELECT 1 FROM public.large_import_core_reviews173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k) THEN RAISE EXCEPTION ''Absent reconciliation has native upload/business metadata'' USING ERRCODE=''23514'';END IF;\n RETURN jsonb_build_object(''reused'',false,''reservation'',to_jsonb(b)-''token_hash'',''resources'',resources0,''expected_paths'',to_jsonb(paths0));\nEND $function$\n","volatility":"v","body_sha256":"ee00c5cf55d44316abbd4daa134557f6191b2395859141fcb85d4ae3b1add54a","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","client0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text","leakproof":false,"signature":"large_import_quota_absent_finish173(uuid,uuid,uuid,text,text,uuid,text,uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_absent_finish173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE fact jsonb;p jsonb;wanted jsonb;path0 jsonb;b record;receipt0 jsonb;evidence0 text;inventory0 text;key0 text;\nBEGIN\n fact:=public.large_import_quota_absent_begin173(u,t,k,r,h,q,token,client0);IF fact->''reused''=''true''::jsonb THEN RETURN fact;END IF;\n IF proof0 IS NULL OR octet_length(proof0)>1048576 THEN RAISE EXCEPTION ''Absent reconciliation bounded private proof required'' USING ERRCODE=''22023'';END IF;\n p:=proof0::jsonb;\n SELECT coalesce(jsonb_agg(jsonb_build_object(''resource_key'',z->>''resource_key'',''kind'',z->>''kind'',''byte_count'',z->''byte_count'',''sha256'',z->>''sha256'',''state'',z->>''state'',''payload_text'',z->>''payload_text'') ORDER BY z->>''resource_key'' COLLATE \"C\"),''[]''::jsonb) INTO wanted FROM jsonb_array_elements(fact->''resources'') z;\n IF jsonb_typeof(p) IS DISTINCT FROM ''object'' OR (SELECT count(*) FROM jsonb_object_keys(p))<>7 OR p->>''schema'' IS DISTINCT FROM ''private-upload-absent-close/v1''\n OR p->''scope'' IS DISTINCT FROM jsonb_build_object(''tenantId'',t,''actorId'',u,''apiKeyId'',k) OR p->>''reservation_id'' IS DISTINCT FROM q::text\n OR p->>''request_id'' IS DISTINCT FROM fact->''reservation''->>''request_id'' OR p->''resources'' IS DISTINCT FROM wanted\n OR jsonb_typeof(p->''fs_cut'') IS DISTINCT FROM ''array'' OR jsonb_array_length(p->''fs_cut'')<>6\n OR p->''fs_cut''->0->>''path'' IS DISTINCT FROM ''.'' OR p->''fs_cut''->0->>''state'' IS DISTINCT FROM ''present''\n OR p->''fs_cut''->0->>''kind'' IS DISTINCT FROM ''directory'' OR p->''fs_cut''->0->>''mode'' IS DISTINCT FROM ''448''\n OR p->''metadata_cut'' IS DISTINCT FROM jsonb_build_object(''blobs'',0,''jobs'',0,''reviews'',0) THEN RAISE EXCEPTION ''Absent reconciliation full original proof mismatch'' USING ERRCODE=''23514'';END IF;\n FOR path0 IN SELECT value FROM jsonb_array_elements(fact->''expected_paths'') LOOP\n  IF (SELECT count(*) FROM jsonb_array_elements(p->''fs_cut'') z WHERE z=jsonb_build_object(''path'',path0,''state'',''absent''))<>1 THEN RAISE EXCEPTION ''Absent reconciliation missing exact absent path'' USING ERRCODE=''23514'';END IF;\n END LOOP;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q;\n inventory0:=encode(sha256(convert_to(proof0,''UTF8'')),''hex'');receipt0:=jsonb_build_object(''schema'',''quota-absent-close-receipt/v1'',''client_key'',client0,''tenant_id'',t,''reservation_id'',q,''request_id'',b.request_id,''inventory_sha256'',inventory0,''released_directory_count'',5,''native_time'',clock_timestamp());\n evidence0:=jsonb_build_object(''schema'',''quota-absent-close-evidence/v1'',''inventory_text'',proof0,''receipt'',receipt0)::text;key0:=''event:upload-absent-close:''||client0::text;\n -- One retained metadata resource stores the immutable original cut and receipt. Original five byte counts/hashes/payloads never change.\n IF 2::numeric*octet_length(evidence0)>b.metadata_ceiling OR 2>b.objects_ceiling THEN RAISE EXCEPTION ''Absent reconciliation evidence exceeds original ceiling'' USING ERRCODE=''54000'';END IF;\n INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,''event'',octet_length(evidence0),encode(sha256(convert_to(evidence0,''UTF8'')),''hex''),''settled'',evidence0);\n UPDATE public.large_import_quota_resources173 SET state=''released'' WHERE tenant_id=t AND reservation_id=q AND resource_key<>key0;\n UPDATE public.large_import_quota_reservations173 SET state=''retained'',outcome=''absent'',raw_charge=0,metadata_charge=2::numeric*octet_length(evidence0),objects_charge=2,closed_at=clock_timestamp(),inventory_sha256=inventory0 WHERE tenant_id=t AND id=q RETURNING * INTO b;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n RETURN jsonb_build_object(''reused'',false,''reservation'',to_jsonb(b)-''token_hash'',''receipt'',receipt0);\nEND $function$\n","volatility":"v","body_sha256":"17c0a9533798c88fc530667c699bb9743d2eef49bdec5aa777ed85047b462eb0","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","client0","proof0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text","leakproof":false,"signature":"large_import_quota_authorize173(uuid,uuid,uuid,text,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_authorize173(u uuid, t uuid, k uuid, r text, h text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE policy_count integer;\nBEGIN\n -- VOLATILE SPI queries need fresh statement snapshots after the global advisory wait.\n -- RR/serializable snapshots established by prior IAM reads cannot safely sum cross-tenant allocations.\n IF current_setting(''transaction_isolation'') IS DISTINCT FROM ''read committed'' THEN\n  RAISE EXCEPTION ''Quota writes require READ COMMITTED'' USING ERRCODE=''25000'';\n END IF;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\n -- Every allocation/final settlement uses this identical global -> tenant order, including cross-tenant calls.\n PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:global'',0));\n PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:tenant:''||t::text,0));\n PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN(''global'',''tenant:''||t::text) ORDER BY scope FOR SHARE;\n GET DIAGNOSTICS policy_count=ROW_COUNT;\n IF policy_count<>2 THEN\n  RAISE EXCEPTION ''Quota inventory/policy unavailable'' USING ERRCODE=''55000'';\n END IF;\nEND $function$\n","volatility":"v","body_sha256":"60aa87e2205075621dedfbbcabad7a57cc265181dc0dcb56f10bffc7d2f2fbd0","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, outcome0 text, inventory text, keys0 text[]","leakproof":false,"signature":"large_import_quota_close173(uuid,uuid,uuid,text,text,uuid,text,text,text,text[])","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_close173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, outcome0 text, inventory text, keys0 text[])\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;x record;actual_keys text[];\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF token IS NULL OR outcome0 IS NULL OR outcome0 NOT IN(''ready'',''quarantined'',''unknown'') THEN RAISE EXCEPTION ''Quota close shape'' USING ERRCODE=''22023'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND THEN RAISE EXCEPTION ''Quota close not owned'' USING ERRCODE=''42501'';END IF;\n IF outcome0=''unknown'' THEN\n  IF b.state=''retained'' THEN RETURN to_jsonb(b)-''token_hash'';END IF;\n  UPDATE public.large_import_quota_reservations173 SET state=''unknown'' WHERE tenant_id=t AND id=q RETURNING * INTO b;RETURN to_jsonb(b)-''token_hash''; -- Ceiling never released by expiry, revocation, uncertain commit, pending file or unknown ACK.\n END IF;\n IF inventory IS NULL OR inventory !~ ''^[a-f0-9]{64}$'' OR keys0 IS NULL OR array_position(keys0,NULL) IS NOT NULL THEN RAISE EXCEPTION ''Complete private inventory required'' USING ERRCODE=''22023'';END IF;\n SELECT coalesce(array_agg(resource_key ORDER BY resource_key COLLATE \"C\"),ARRAY[]::text[]) INTO actual_keys FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n -- Use a second explicit aggregate record; do not rely on row/text aliases or nullable checks.\n SELECT coalesce(sum(byte_count) FILTER(WHERE kind=''raw'' AND state<>''released''),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>''raw'' AND state<>''released''),0) metadata_used,coalesce(sum(CASE WHEN state=''released'' THEN 0 WHEN kind=''raw'' THEN 1 ELSE 2 END),0) objects_used,count(*) FILTER(WHERE state=''intent'') pending INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n IF actual_keys IS DISTINCT FROM keys0 OR x.pending<>0 THEN RAISE EXCEPTION ''Quota incomplete resource inventory'' USING ERRCODE=''23514'';END IF;\n IF b.state=''retained'' THEN\n  IF b.outcome IS DISTINCT FROM outcome0 OR b.inventory_sha256 IS DISTINCT FROM inventory OR b.raw_charge IS DISTINCT FROM x.raw_used OR b.metadata_charge IS DISTINCT FROM x.metadata_used OR b.objects_charge IS DISTINCT FROM x.objects_used THEN RAISE EXCEPTION ''Quota close replay conflict'' USING ERRCODE=''23505'';END IF;RETURN to_jsonb(b)-''token_hash'';\n END IF;\n UPDATE public.large_import_quota_reservations173 SET state=''retained'',outcome=outcome0,raw_charge=x.raw_used,metadata_charge=x.metadata_used,objects_charge=x.objects_used,closed_at=clock_timestamp(),inventory_sha256=inventory WHERE tenant_id=t AND id=q RETURNING * INTO b;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);RETURN to_jsonb(b)-''token_hash'';\nEND $function$\n","volatility":"v","body_sha256":"72d28007ca59c21d93728ac0a9608f2e3767af3d5b1432064f5876fe8da5387b","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","outcome0","inventory","keys0"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, kind0 text, n bigint, sha text, payload text","leakproof":false,"signature":"large_import_quota_intent173(uuid,uuid,uuid,text,text,uuid,text,text,text,bigint,text,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_intent173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, kind0 text, n bigint, sha text, payload text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;old record;x record;\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF token IS NULL OR key0 IS NULL OR length(key0) NOT BETWEEN 1 AND 200 OR kind0 IS NULL OR kind0 NOT IN(''raw'',''blob'',''batch'',''job'',''review'',''event'') OR key0 !~ ''^(raw|blob|batch|job|review|event):[a-z0-9:-]{1,160}$'' OR split_part(key0,'':'',1) IS DISTINCT FROM kind0 OR n IS NULL OR n<0 OR sha IS NULL OR sha !~ ''^[a-f0-9]{64}$'' THEN RAISE EXCEPTION ''Quota intent shape'' USING ERRCODE=''22023'';END IF;\n IF (kind0=''raw'' AND payload IS NOT NULL) OR (kind0<>''raw'' AND (payload IS NULL OR octet_length(payload) IS DISTINCT FROM n OR encode(sha256(convert_to(payload,''UTF8'')),''hex'') IS DISTINCT FROM sha)) THEN RAISE EXCEPTION ''Quota exact metadata payload bytes'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND THEN RAISE EXCEPTION ''Quota reservation not owned'' USING ERRCODE=''42501'';END IF;\n SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n IF FOUND THEN\n  IF old.kind IS DISTINCT FROM kind0 OR old.byte_count IS DISTINCT FROM n OR old.sha256 IS DISTINCT FROM sha OR old.payload_text IS DISTINCT FROM payload THEN RAISE EXCEPTION ''Quota resource replay conflict'' USING ERRCODE=''23505'';END IF;\n  IF old.state=''released'' THEN RAISE EXCEPTION ''Terminal allocation cannot authorize publication'' USING ERRCODE=''23505'';END IF;\n  IF old.state=''settled'' OR old.state=''quarantined'' THEN RETURN to_jsonb(old)-''token_hash'';END IF;\n  RAISE EXCEPTION ''Pending resource requires inspection, not duplicate write'' USING ERRCODE=''40001'';\n END IF;\n IF b.state IS DISTINCT FROM ''open'' OR b.expires_at<=clock_timestamp() THEN RAISE EXCEPTION ''Quota lease expired; retained allocation requires reconciliation'' USING ERRCODE=''40001'';END IF;\n SELECT coalesce(sum(byte_count) FILTER(WHERE kind=''raw'' AND state<>''released''),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>''raw'' AND state<>''released''),0) metadata_used,coalesce(sum(CASE WHEN state=''released'' THEN 0 WHEN kind=''raw'' THEN 1 ELSE 2 END),0) objects_used INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n IF x.raw_used+(CASE WHEN kind0=''raw'' THEN n ELSE 0 END)>b.raw_ceiling OR x.metadata_used+(CASE WHEN kind0<>''raw'' THEN n*2::numeric ELSE 0 END)>b.metadata_ceiling OR x.objects_used+(CASE WHEN kind0=''raw'' THEN 1 ELSE 2 END)>b.objects_ceiling THEN RAISE EXCEPTION ''Quota resource ceiling exhausted'' USING ERRCODE=''54000'';END IF;\n INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,kind0,n,sha,''intent'',payload) RETURNING * INTO old;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);RETURN to_jsonb(old)-''token_hash'';\nEND $function$\n","volatility":"v","body_sha256":"c54a395fbf83109e340eb7a195a6d7d856c5ecb88c264736d2dea3c48dc03311","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","kind0","n","sha","payload"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb","leakproof":false,"signature":"large_import_quota_intent_many173(uuid,uuid,uuid,text,text,uuid,text,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_intent_many173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;old record;x record;v jsonb;key0 text;kind0 text;n bigint;sha text;payload text;seen text[]:=ARRAY[]::text[];result jsonb:=''[]''::jsonb;new_raw numeric:=0;new_metadata numeric:=0;new_objects numeric:=0;new_count integer:=0;\nBEGIN\n -- Same existing READ COMMITTED/full currentIAM/global -> tenant -> policy order.\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF q IS NULL OR token IS NULL OR token !~ ''^[a-f0-9]{64}$'' OR items IS NULL OR jsonb_typeof(items) IS DISTINCT FROM ''array'' THEN RAISE EXCEPTION ''Quota group shape'' USING ERRCODE=''22023'';END IF;\n IF jsonb_array_length(items) NOT BETWEEN 1 AND 64 OR octet_length(items::text)>8388608 THEN RAISE EXCEPTION ''Quota group bound'' USING ERRCODE=''22023'';END IF;\n -- Validate ALL shapes before reservation/resource mutation. Text payload is compared exactly,\n -- never JSON-projected or normalized; caller bytes/hash include original UTF8 serialization.\n FOR v IN SELECT value FROM jsonb_array_elements(items) LOOP\n  IF jsonb_typeof(v) IS DISTINCT FROM ''object'' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v) key) IS DISTINCT FROM ARRAY[''byte_count'',''key'',''kind'',''payload_text'',''sha256'']::text[] OR jsonb_typeof(v->''key'') IS DISTINCT FROM ''string'' OR jsonb_typeof(v->''kind'') IS DISTINCT FROM ''string'' OR jsonb_typeof(v->''sha256'') IS DISTINCT FROM ''string'' OR jsonb_typeof(v->''byte_count'') IS DISTINCT FROM ''number'' OR (v->>''byte_count'') !~ ''^(0|[1-9][0-9]{0,15})$'' THEN RAISE EXCEPTION ''Quota group item shape'' USING ERRCODE=''22023'';END IF;\n  key0:=v->>''key'';kind0:=v->>''kind'';n:=(v->>''byte_count'')::bigint;sha:=v->>''sha256'';payload:=v->>''payload_text'';\n  IF key0 !~ ''^(raw|blob|batch|job|review|event):[a-z0-9:-]{1,160}$'' OR kind0 NOT IN(''raw'',''blob'',''batch'',''job'',''review'',''event'') OR split_part(key0,'':'',1) IS DISTINCT FROM kind0 OR sha !~ ''^[a-f0-9]{64}$'' OR n>9007199254740991 OR key0=ANY(seen) THEN RAISE EXCEPTION ''Quota group item identity'' USING ERRCODE=''22023'';END IF;\n  IF (kind0=''raw'' AND jsonb_typeof(v->''payload_text'') IS DISTINCT FROM ''null'') OR (kind0<>''raw'' AND (jsonb_typeof(v->''payload_text'') IS DISTINCT FROM ''string'' OR octet_length(payload) IS DISTINCT FROM n OR encode(sha256(convert_to(payload,''UTF8'')),''hex'') IS DISTINCT FROM sha)) THEN RAISE EXCEPTION ''Quota group exact payload'' USING ERRCODE=''23514'';END IF;\n  seen:=array_append(seen,key0);\n END LOOP;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND THEN RAISE EXCEPTION ''Quota group reservation not owned'' USING ERRCODE=''42501'';END IF;\n -- Lock complete existing group in C byte order before any insertion. Reservation UPDATE also\n -- fences competing inserts under the unchanged native global lock protocol.\n PERFORM 1 FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=ANY(seen) ORDER BY resource_key COLLATE \"C\" FOR UPDATE;\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''key'') COLLATE \"C\" LOOP\n  key0:=v->>''key'';kind0:=v->>''kind'';n:=(v->>''byte_count'')::bigint;sha:=v->>''sha256'';payload:=v->>''payload_text'';\n  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n  IF FOUND THEN\n   IF old.kind IS DISTINCT FROM kind0 OR old.byte_count IS DISTINCT FROM n OR old.sha256 IS DISTINCT FROM sha OR old.payload_text IS DISTINCT FROM payload THEN RAISE EXCEPTION ''Quota group replay conflict'' USING ERRCODE=''23505'';END IF;\n   IF old.state=''released'' THEN RAISE EXCEPTION ''Terminal allocation cannot authorize publication'' USING ERRCODE=''23505'';END IF;\n   IF old.state NOT IN(''settled'',''quarantined'') THEN RAISE EXCEPTION ''Pending resource requires inspection'' USING ERRCODE=''40001'';END IF;\n  ELSE\n   IF b.state IS DISTINCT FROM ''open'' OR b.expires_at<=clock_timestamp() THEN RAISE EXCEPTION ''Quota group lease unavailable'' USING ERRCODE=''40001'';END IF;\n   new_count:=new_count+1;new_raw:=new_raw+(CASE WHEN kind0=''raw'' THEN n ELSE 0 END);new_metadata:=new_metadata+(CASE WHEN kind0<>''raw'' THEN n*2::numeric ELSE 0 END);new_objects:=new_objects+(CASE WHEN kind0=''raw'' THEN 1 ELSE 2 END);\n  END IF;\n END LOOP;\n IF new_count>0 THEN\n SELECT coalesce(sum(byte_count) FILTER(WHERE kind=''raw'' AND state<>''released''),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>''raw'' AND state<>''released''),0) metadata_used,coalesce(sum(CASE WHEN state=''released'' THEN 0 WHEN kind=''raw'' THEN 1 ELSE 2 END),0) objects_used INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n IF x.raw_used+new_raw>b.raw_ceiling OR x.metadata_used+new_metadata>b.metadata_ceiling OR x.objects_used+new_objects>b.objects_ceiling THEN RAISE EXCEPTION ''Quota group ceiling exhausted'' USING ERRCODE=''54000'';END IF;\n END IF;\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''key'') COLLATE \"C\" LOOP\n  key0:=v->>''key'';SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n  IF NOT FOUND THEN INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,v->>''kind'',(v->>''byte_count'')::bigint,v->>''sha256'',''intent'',v->>''payload_text'') RETURNING * INTO old;END IF;\n  result:=result||jsonb_build_array(to_jsonb(old));\n END LOOP;\n -- No saved verdict: complete graph + locked currentIAM again, after group effects. An elapsed\n -- new-write deadline rolls back the entire group. Exact settled replay never extends expiry.\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\n IF new_count>0 AND b.expires_at<=clock_timestamp() THEN RAISE EXCEPTION ''Quota group deadline elapsed'' USING ERRCODE=''40001'';END IF;\n RETURN result;\nEND $function$\n","volatility":"v","body_sha256":"06ef881ab76d92494cc45b7340d1031f458810e6d02c822a24f418f2ad93b5d8","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","items"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, w boolean","leakproof":false,"signature":"large_import_quota_keeper_admit173(uuid,uuid,uuid,text,text,boolean)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_keeper_admit173(u uuid, t uuid, k uuid, r text, h text, w boolean)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE x record;v_now timestamptz;\nBEGIN\n IF u IS NULL OR t IS NULL OR r IS NULL OR r NOT IN(''admin'',''operator'',''viewer'') OR h IS NULL OR h !~ ''^[a-f0-9]{64}$'' OR w IS NULL THEN\n  RAISE EXCEPTION ''Invalid metadata authority'' USING ERRCODE=''42501'';\n END IF;\n -- SD current_user is the module owner. The caller is a fresh, private dedicated owner keeper connection with role NONE; no role reset.\n IF current_setting(''role'',true) IS DISTINCT FROM ''none''\n OR session_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=to_regclass(''public.large_import173_certificate'')))\n OR t IS DISTINCT FROM nullif(current_setting(''app.tenant_id'',true),'''')::uuid THEN\n  RAISE EXCEPTION ''Private keeper owner-role tenant transport mismatch'' USING ERRCODE=''42501'';\n END IF;\n -- Owner startup MUST independently pin the complete current body/catalog graph before invoking the private keeper ABI.\n -- This leaf check alone is not self-attestation. The new helper+grant must be in that compiled certificate graph.\n IF public.large_import173_valid() IS DISTINCT FROM true THEN\n  RAISE EXCEPTION ''Metadata173 is not certified'' USING ERRCODE=''55000'';\n END IF;\n -- Same order as native170 pin path; independent authority, without its lifecycle.\n -- Actual metadata checkpoint caller must be inside BEGIN; locks then survive through its COMMIT/ROLLBACK.\n PERFORM 1 FROM public.users WHERE id=u FOR SHARE;\n PERFORM 1 FROM public.tenants WHERE id=t FOR SHARE;\n PERFORM 1 FROM public.account_security WHERE user_id=u FOR SHARE;\n PERFORM 1 FROM public.workspace_security_policies WHERE tenant_id=t FOR SHARE;\n PERFORM 1 FROM public.memberships WHERE(user_id,tenant_id)=(u,t) FOR SHARE;\n IF k IS NULL THEN\n  PERFORM 1 FROM public.sessions WHERE(token_hash,user_id,tenant_id)=(h,u,t) FOR SHARE;\n ELSE\n  PERFORM 1 FROM public.api_keys WHERE(id,user_id,tenant_id)=(k,u,t) FOR SHARE;\n END IF;\n v_now:=clock_timestamp();\n IF k IS NULL THEN\n  SELECT m.role,coalesce(a.version,0)::text account_version,true scope_ok,\n   least(s.expires_at,CASE WHEN coalesce(p.require_mfa,false) THEN s.mfa_verified_at+interval ''8 hours'' ELSE s.expires_at END) deadline,\n   coalesce(p.require_mfa,false) AND NOT(coalesce(a.enabled_at IS NOT NULL AND s.mfa_verified_at IS NOT NULL AND s.mfa_verified_at>v_now-interval ''8 hours'',false)) mfa_required INTO x\n  FROM public.sessions s JOIN public.users z ON z.id=s.user_id JOIN public.tenants n ON n.id=s.tenant_id\n  JOIN public.memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)\n  LEFT JOIN public.account_security a ON a.user_id=z.id LEFT JOIN public.workspace_security_policies p ON p.tenant_id=n.id\n  WHERE(s.token_hash,s.user_id,s.tenant_id)=(h,u,t) AND s.expires_at>v_now AND s.account_version=coalesce(a.version,0);\n ELSE\n  SELECT m.role,coalesce(a.version,0)::text account_version,k0.expires_at deadline,\n   k0.scopes@>CASE WHEN w THEN ARRAY[''products:read'',''products:write'']::text[] ELSE ARRAY[''products:read'']::text[] END scope_ok,\n   coalesce(p.require_mfa,false) AND a.enabled_at IS NULL mfa_required INTO x\n  FROM public.api_keys k0 JOIN public.users z ON z.id=k0.user_id JOIN public.tenants n ON n.id=k0.tenant_id\n  JOIN public.memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)\n  LEFT JOIN public.account_security a ON a.user_id=z.id LEFT JOIN public.workspace_security_policies p ON p.tenant_id=n.id\n  WHERE(k0.id,k0.token_hash,k0.user_id,k0.tenant_id)=(k,h,u,t) AND k0.revoked_at IS NULL AND k0.expires_at>v_now;\n END IF;\n IF x.role IS NULL OR x.deadline IS NULL OR NOT isfinite(x.deadline) OR x.deadline<=clock_timestamp() THEN\n  RAISE EXCEPTION ''Expired metadata authority'' USING ERRCODE=''28000'';\n END IF;\n IF x.role<>r THEN RAISE EXCEPTION ''Metadata role changed'' USING ERRCODE=''40001'';END IF;\n IF NOT coalesce(x.scope_ok,false) OR coalesce(x.mfa_required,true) OR(w AND x.role<>''admin'') THEN\n  RAISE EXCEPTION ''Missing current metadata authority'' USING ERRCODE=''42501'';\n END IF;\nEND\n$function$\n","volatility":"v","body_sha256":"734ce613962ab35ec98bf714b152a959e5f2aa2fb2baf0191720d52de6b7a27b","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","w"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, q uuid, token text, key0 text, n bigint, sha text","leakproof":false,"signature":"large_import_quota_lock_cleanup_pin173(uuid,uuid,uuid,uuid,text,text,bigint,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_lock_cleanup_pin173(u uuid, t uuid, k uuid, q uuid, token text, key0 text, n bigint, sha text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;x record;\nBEGIN\n IF current_setting(''role'',true) IS DISTINCT FROM ''dyna_app'' OR current_setting(''app.tenant_id'',true) IS DISTINCT FROM t::text\n OR session_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=''public.large_import173_certificate''::regclass))\n OR public.large_import173_valid() IS DISTINCT FROM true THEN RAISE EXCEPTION ''Cleanup requires certified owned app transport'' USING ERRCODE=''42501'';END IF;\n -- No global/tenant quota locks: caller already committed intents; no new capacity or receipt allocation occurs here.\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR SHARE;\n IF NOT FOUND OR b.kind IS DISTINCT FROM ''upload'' OR b.state=''retained'' THEN RAISE EXCEPTION ''Cleanup reservation not active/owned'' USING ERRCODE=''42501'';END IF;\n SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0 FOR SHARE;\n IF NOT FOUND OR x.kind IS DISTINCT FROM ''blob'' OR x.state=''released'' OR x.byte_count IS DISTINCT FROM n OR x.sha256 IS DISTINCT FROM sha\n OR key0 !~ ''^blob:fs:(blobs|uploads|witnesses):[a-f0-9-]{36}:lock:[a-f0-9-]{36}$''\n OR (x.payload_text::jsonb->>''schema'') IS DISTINCT FROM ''private-import-lock/v1''\n OR (x.payload_text::jsonb->>''id'') IS DISTINCT FROM split_part(key0,'':'',6)\n OR (SELECT count(*) FROM jsonb_object_keys(x.payload_text::jsonb))<>2 THEN\n RAISE EXCEPTION ''Cleanup only permits original exact transient lock'' USING ERRCODE=''42501'';END IF;\nEND $function$\n","volatility":"v","body_sha256":"a791212d48162da3cb71f1d67db5f4f38252bcf03dc73570d4bf532a45afbe1d","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","q","token","key0","n","sha"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid","leakproof":false,"signature":"large_import_quota_owned_close_begin173(uuid,uuid,uuid,text,text,uuid,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_owned_close_begin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;policy_count integer;old record;snapshot0 jsonb;\nBEGIN\n IF current_setting(''transaction_isolation'') IS DISTINCT FROM ''read committed'' THEN RAISE EXCEPTION ''Terminal writes require READ COMMITTED'' USING ERRCODE=''25000'';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:global'',0));PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:tenant:''||t::text,0));\n PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN(''global'',''tenant:''||t::text) ORDER BY scope FOR SHARE;GET DIAGNOSTICS policy_count=ROW_COUNT;\n IF policy_count<>2 THEN RAISE EXCEPTION ''Terminal quota policy absent'' USING ERRCODE=''55000'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.kind NOT IN(''job'',''review'') OR client0 IS NULL THEN RAISE EXCEPTION ''Known-close business request not owned'' USING ERRCODE=''42501'';END IF;\n IF b.state=''retained'' THEN\n  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=''event:business-known-close:''||client0::text AND state=''settled'';\n  IF NOT FOUND OR b.outcome<>''ready'' OR old.payload_text::jsonb->''receipt''->>''client_key'' IS DISTINCT FROM client0::text THEN RAISE EXCEPTION ''Known-close original key conflict'' USING ERRCODE=''23505'';END IF;\n  RETURN jsonb_build_object(''reused'',true,''reservation'',to_jsonb(b)-''token_hash'',''receipt'',old.payload_text::jsonb->''receipt''); -- no fresh cut or callback on exact old-key recovery\n END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE \"C\"),''[]''::jsonb) INTO snapshot0 FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;\n IF jsonb_array_length(snapshot0)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot0) x WHERE x->>''state'' NOT IN(''settled'',''released'')) THEN RAISE EXCEPTION ''Known close has pending original allocations'' USING ERRCODE=''40001'';END IF;\n RETURN jsonb_build_object(''reused'',false,''reservation'',to_jsonb(b)-''token_hash'',''resources'',snapshot0);\nEND $function$\n","volatility":"v","body_sha256":"d7dd88adb51e571a8e124bec7e5dae9f7e6bdef6796eafc326e7f70f65ce0948","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","client0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text","leakproof":false,"signature":"large_import_quota_owned_close_finish173(uuid,uuid,uuid,text,text,uuid,text,uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_owned_close_finish173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE fact jsonb;p jsonb;wanted jsonb;b record;job0 record;actual0 jsonb;charges record;receipt0 jsonb;evidence0 text;key0 text;inventory0 text;\nBEGIN\n fact:=public.large_import_quota_owned_close_begin173(u,t,k,r,h,q,token,client0);IF fact->''reused''=''true''::jsonb THEN RETURN fact;END IF;\n IF proof0 IS NULL OR octet_length(proof0)>8388608 THEN RAISE EXCEPTION ''Known-close bounded private proof required'' USING ERRCODE=''22023'';END IF;\n p:=proof0::jsonb;\n SELECT coalesce(jsonb_agg(jsonb_build_object(''resource_key'',z->>''resource_key'',''kind'',z->>''kind'',''byte_count'',z->''byte_count'',''sha256'',z->>''sha256'',''state'',z->>''state'') ORDER BY z->>''resource_key'' COLLATE \"C\"),''[]''::jsonb) INTO wanted FROM jsonb_array_elements(fact->''resources'') z;\n IF jsonb_typeof(p) IS DISTINCT FROM ''object'' OR (SELECT count(*) FROM jsonb_object_keys(p))<>9 OR p->>''schema'' IS DISTINCT FROM ''private-business-known-close/v1''\n OR p->''scope'' IS DISTINCT FROM jsonb_build_object(''tenantId'',t,''actorId'',u,''apiKeyId'',k) OR p->>''reservation_id'' IS DISTINCT FROM q::text\n OR p->>''request_id'' IS DISTINCT FROM fact->''reservation''->>''request_id'' OR p->''resources'' IS DISTINCT FROM wanted\n OR p->>''kind'' IS DISTINCT FROM fact->''reservation''->>''kind'' OR jsonb_typeof(p->''fs_cut'') IS DISTINCT FROM ''array''\n OR jsonb_typeof(p->''metadata_cut'') IS DISTINCT FROM ''object'' THEN RAISE EXCEPTION ''Known-close full original inventory mismatch'' USING ERRCODE=''23514'';END IF;\n IF EXISTS(SELECT 1 FROM public.large_import_quota_resources173 z WHERE z.tenant_id=t AND z.reservation_id=q AND z.state=''released'' AND NOT EXISTS(SELECT 1 FROM public.large_import_quota_terminal_receipts173 e WHERE(e.tenant_id,e.reservation_id,e.resource_key)=(z.tenant_id,z.reservation_id,z.resource_key))) THEN RAISE EXCEPTION ''Released allocation lacks immutable native receipt'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO job0 FROM public.large_import_jobs173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND id=(p->>''job_id'')::uuid FOR SHARE;\n IF NOT FOUND OR job0.lease_token IS NOT NULL OR job0.leased_at IS NOT NULL THEN RAISE EXCEPTION ''Business job is not owned/quiescent'' USING ERRCODE=''40001'';END IF;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(job0.state_text::jsonb->''core'') batch WHERE jsonb_typeof(batch->''execution'') IS DISTINCT FROM ''object'')\n OR EXISTS(SELECT 1 FROM jsonb_each(job0.state_text::jsonb->''pim'') group0 CROSS JOIN LATERAL jsonb_array_elements(group0.value) attempt WHERE ((attempt->>''applyAttempted'')::boolean AND jsonb_typeof(attempt->''applied'') IS DISTINCT FROM ''object'') OR ((attempt->>''previewAttempted'')::boolean AND jsonb_typeof(attempt->''preview'') IS DISTINCT FROM ''object''))\n THEN RAISE EXCEPTION ''Unresolved original business outcome'' USING ERRCODE=''40001'';END IF;\n PERFORM 1 FROM public.large_import_events173 WHERE tenant_id=t AND job_id=job0.id ORDER BY sequence FOR SHARE;\n PERFORM 1 FROM public.large_import_core_reviews173 WHERE tenant_id=t AND job_id=job0.id ORDER BY revision FOR SHARE;\n SELECT jsonb_build_object(''job'',jsonb_build_object(''state_text'',job0.state_text,''state_sha256'',job0.state_sha256,''revision'',job0.revision,''lease_fence'',job0.lease_fence::text,''lease_token'',job0.lease_token,''leased_at'',job0.leased_at),\n ''events'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''sequence'',e.sequence,''revision'',e.revision,''event_text'',e.event_text,''event_sha256'',e.event_sha256) ORDER BY e.sequence),''[]''::jsonb) FROM public.large_import_events173 e WHERE e.tenant_id=t AND e.job_id=job0.id),\n ''reviews'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''revision'',v.revision,''review_text'',v.review_text,''review_sha256'',v.review_sha256,''job_revision'',v.job_revision,''lease_fence'',v.lease_fence::text,''scope_text'',v.scope_text,''request_texts'',v.request_texts,''row_texts'',v.row_texts) ORDER BY v.revision),''[]''::jsonb) FROM public.large_import_core_reviews173 v WHERE v.tenant_id=t AND v.job_id=job0.id)) INTO actual0;\n IF p->''metadata_cut'' IS DISTINCT FROM actual0 THEN RAISE EXCEPTION ''Business native metadata cut mismatch'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q;\n inventory0:=encode(sha256(convert_to(proof0,''UTF8'')),''hex'');receipt0:=jsonb_build_object(''schema'',''quota-known-close-receipt/v1'',''client_key'',client0,''tenant_id'',t,''reservation_id'',q,''request_id'',b.request_id,''inventory_sha256'',inventory0,''native_time'',clock_timestamp());\n evidence0:=jsonb_build_object(''schema'',''quota-known-close-evidence/v1'',''inventory_text'',proof0,''receipt'',receipt0)::text;key0:=''event:business-known-close:''||client0::text;\n IF octet_length(evidence0)>8388608 THEN RAISE EXCEPTION ''Known-close evidence limit'' USING ERRCODE=''54000'';END IF;\n SELECT coalesce(sum(byte_count) FILTER(WHERE kind=''raw'' AND state<>''released''),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>''raw'' AND state<>''released''),0) metadata_used,coalesce(sum(CASE WHEN state=''released'' THEN 0 WHEN kind=''raw'' THEN 1 ELSE 2 END),0) objects_used INTO charges FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n IF charges.raw_used>b.raw_ceiling OR charges.metadata_used+2::numeric*octet_length(evidence0)>b.metadata_ceiling OR charges.objects_used+2>b.objects_ceiling THEN RAISE EXCEPTION ''Known-close evidence exceeds original ceiling'' USING ERRCODE=''54000'';END IF;\n INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,''event'',octet_length(evidence0),encode(sha256(convert_to(evidence0,''UTF8'')),''hex''),''settled'',evidence0);\n UPDATE public.large_import_quota_reservations173 SET state=''retained'',outcome=''ready'',raw_charge=charges.raw_used,metadata_charge=charges.metadata_used+2::numeric*octet_length(evidence0),objects_charge=charges.objects_used+2,closed_at=clock_timestamp(),inventory_sha256=inventory0 WHERE tenant_id=t AND id=q RETURNING * INTO b;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n RETURN jsonb_build_object(''reused'',false,''reservation'',to_jsonb(b)-''token_hash'',''receipt'',receipt0);\nEND $function$\n","volatility":"v","body_sha256":"6cf5b74cdcc248bbb9ca5c1dac763968f5747a2cce22bcbde9a9a15579fb0cf8","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","client0","proof0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid","leakproof":false,"signature":"large_import_quota_owned_release_begin173(uuid,uuid,uuid,text,text,uuid,text,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_owned_release_begin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;x record;receipt record;classification text;policy_count integer;\nBEGIN\n IF current_setting(''transaction_isolation'') IS DISTINCT FROM ''read committed'' THEN RAISE EXCEPTION ''Terminal writes require READ COMMITTED'' USING ERRCODE=''25000'';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:global'',0));PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:tenant:''||t::text,0));\n PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN(''global'',''tenant:''||t::text) ORDER BY scope FOR SHARE;\n GET DIAGNOSTICS policy_count=ROW_COUNT;\n IF policy_count<>2 THEN RAISE EXCEPTION ''Terminal quota policy absent'' USING ERRCODE=''55000'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.kind NOT IN(''job'',''review'') OR client0 IS NULL THEN RAISE EXCEPTION ''Terminal business reservation not owned'' USING ERRCODE=''42501'';END IF;\n SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0 FOR UPDATE;\n IF NOT FOUND OR x.kind<>''blob'' THEN RAISE EXCEPTION ''Only exact business witness locks are terminal candidates'' USING ERRCODE=''22023'';END IF;\n IF x.state=''released'' THEN\n  SELECT * INTO receipt FROM public.large_import_quota_terminal_receipts173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n  IF NOT FOUND OR receipt.client_key IS DISTINCT FROM client0 THEN RAISE EXCEPTION ''Terminal exact-key recovery conflict'' USING ERRCODE=''23505'';END IF;\n  RETURN jsonb_build_object(''reused'',true,''receipt'',to_jsonb(receipt)); -- Read original receipt; no FS callback, new evidence, time or key.\n END IF;\n IF b.state=''retained'' THEN RAISE EXCEPTION ''Closed quota cannot be rewritten'' USING ERRCODE=''42501'';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true); -- Refresh after reservation lock, before the private FS cut.\n IF key0 ~ ''^blob:fs:witnesses:[a-f0-9-]{36}:lock:[a-f0-9-]{36}$'' AND x.state IN(''intent'',''settled'') THEN classification:=''released-lock'';\n ELSE RAISE EXCEPTION ''Allocation is not an owned witness lock'' USING ERRCODE=''22023'';END IF;\n RETURN jsonb_build_object(''reused'',false,''classification'',classification,''reservation'',to_jsonb(b)-''token_hash'',''resource'',to_jsonb(x));\nEND $function$\n","volatility":"v","body_sha256":"529eeacc46303fb9fc5b1bcedc6c9128290941b3b032fab6777c2364b2fa2e73","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","client0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid, witness0 text, classification0 text","leakproof":false,"signature":"large_import_quota_owned_release_finish173(uuid,uuid,uuid,text,text,uuid,text,text,uuid,text,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_owned_release_finish173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid, witness0 text, classification0 text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE fact jsonb;b record;x record;blob0 record;w jsonb;receipt0 text;wkey text;rkey text;charges record;extra_metadata numeric;extra_objects bigint:=4;\nBEGIN\n fact:=public.large_import_quota_owned_release_begin173(u,t,k,r,h,q,token,key0,client0);\n IF fact->''reused''=''true''::jsonb THEN RETURN fact;END IF;\n IF classification0 IS DISTINCT FROM fact->>''classification'' OR witness0 IS NULL OR octet_length(witness0)>8388608 THEN RAISE EXCEPTION ''Terminal witness shape'' USING ERRCODE=''22023'';END IF;\n w:=witness0::jsonb;\n IF jsonb_typeof(w) IS DISTINCT FROM ''object'' OR (SELECT count(*) FROM jsonb_object_keys(w))<>10 OR w->>''schema'' IS DISTINCT FROM ''private-business-lock-terminal-witness/v1''\n OR w->''scope'' IS DISTINCT FROM jsonb_build_object(''tenantId'',t,''actorId'',u,''apiKeyId'',k)\n OR w->>''reservation_id'' IS DISTINCT FROM q::text OR w->>''resource_key'' IS DISTINCT FROM key0 OR w->>''classification'' IS DISTINCT FROM classification0\n OR jsonb_typeof(w->''fs_cut'') IS DISTINCT FROM ''array'' OR jsonb_array_length(w->''fs_cut'')<1 THEN RAISE EXCEPTION ''Terminal witness full binding'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q;\n SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n IF w->>''request_id'' IS DISTINCT FROM b.request_id::text OR w->>''original_sha256'' IS DISTINCT FROM x.sha256 OR w->>''byte_count'' IS DISTINCT FROM x.byte_count::text THEN RAISE EXCEPTION ''Terminal original allocation changed'' USING ERRCODE=''23514'';END IF;\n IF w->>''kind'' IS DISTINCT FROM b.kind OR classification0 IS DISTINCT FROM ''released-lock'' THEN RAISE EXCEPTION ''Business witness reservation mismatch'' USING ERRCODE=''23514'';END IF;\n IF classification0=''released-lock'' AND x.payload_text::jsonb IS DISTINCT FROM jsonb_build_object(''schema'',''private-import-lock/v1'',''id'',split_part(key0,'':'',6)::uuid) THEN RAISE EXCEPTION ''Released lock context mismatch'' USING ERRCODE=''23514'';END IF;\n -- Keep old count/hash/payload immutable. A terminal disposition is distinct from pretending absent bytes were settled.\n receipt0:=jsonb_build_object(''schema'',''quota-terminal-receipt/v1'',''tenant_id'',t,''reservation_id'',q,''resource_key'',key0,''client_key'',client0,''classification'',classification0,''old_state'',x.state,''original_sha256'',x.sha256,''original_bytes'',x.byte_count,''witness_sha256'',encode(sha256(convert_to(witness0,''UTF8'')),''hex''),''native_time'',clock_timestamp())::text;\n wkey:=''event:quota-terminal-witness:''||client0::text;rkey:=''event:quota-terminal-receipt:''||client0::text;\n extra_metadata:=2::numeric*(octet_length(witness0)+octet_length(receipt0));\n SELECT coalesce(sum(byte_count) FILTER(WHERE kind=''raw'' AND state<>''released''),0) raw_used,\n  coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>''raw'' AND state<>''released'' AND resource_key<>key0),0) metadata_used,\n  coalesce(sum(CASE WHEN state=''released'' OR resource_key=key0 THEN 0 WHEN kind=''raw'' THEN 1 ELSE 2 END),0) objects_used INTO charges\n FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n IF charges.raw_used>b.raw_ceiling OR charges.metadata_used+extra_metadata>b.metadata_ceiling OR charges.objects_used+extra_objects>b.objects_ceiling THEN RAISE EXCEPTION ''Terminal evidence exceeds original reserved ceiling'' USING ERRCODE=''54000'';END IF;\n INSERT INTO public.large_import_quota_terminal_witnesses173 VALUES(t,q,key0,client0,witness0,encode(sha256(convert_to(witness0,''UTF8'')),''hex''),classification0,x.state,x.sha256,x.byte_count,clock_timestamp());\n INSERT INTO public.large_import_quota_terminal_receipts173 VALUES(t,q,key0,client0,receipt0,encode(sha256(convert_to(receipt0,''UTF8'')),''hex''),clock_timestamp());\n INSERT INTO public.large_import_quota_resources173 VALUES(t,q,wkey,''event'',octet_length(witness0),encode(sha256(convert_to(witness0,''UTF8'')),''hex''),''settled'',witness0),(t,q,rkey,''event'',octet_length(receipt0),encode(sha256(convert_to(receipt0,''UTF8'')),''hex''),''settled'',receipt0);\n UPDATE public.large_import_quota_resources173 SET state=''released'' WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n RETURN jsonb_build_object(''reused'',false,''receipt'',jsonb_build_object(''receipt_text'',receipt0,''receipt_sha256'',encode(sha256(convert_to(receipt0,''UTF8'')),''hex''),''client_key'',client0));\nEND $function$\n","volatility":"v","body_sha256":"30616a3860706f13a1374402e9a7baba877da0c4dcf8281d32fc2e049aea0a61","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","client0","witness0","classification0"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, n bigint, sha text","leakproof":false,"signature":"large_import_quota_publication_pin173(uuid,uuid,uuid,text,text,uuid,text,text,bigint,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_publication_pin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, n bigint, sha text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;x record;\nBEGIN\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR SHARE;\n IF NOT FOUND OR b.state IS DISTINCT FROM ''open'' THEN RAISE EXCEPTION ''Publication reservation is not active/owned'' USING ERRCODE=''42501'';END IF;\n SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0 FOR SHARE;\n IF NOT FOUND OR x.state=''released'' OR x.byte_count IS DISTINCT FROM n OR x.sha256 IS DISTINCT FROM sha THEN RAISE EXCEPTION ''Publication allocation changed/terminal'' USING ERRCODE=''40001'';END IF;\nEND $function$\n","volatility":"v","body_sha256":"f012443a27ade40482d3ac47fd2a43ef55a84061f2067fbd78ec39a0c5293062","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","n","sha"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb","leakproof":false,"signature":"large_import_quota_publication_pin_many173(uuid,uuid,uuid,text,text,uuid,text,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_publication_pin_many173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;x record;v jsonb;seen text[]:=ARRAY[]::text[];\nBEGIN\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\n IF q IS NULL OR token IS NULL OR token !~ ''^[a-f0-9]{64}$'' OR items IS NULL OR jsonb_typeof(items) IS DISTINCT FROM ''array'' THEN RAISE EXCEPTION ''Publication group shape'' USING ERRCODE=''22023'';END IF;\n IF jsonb_array_length(items) NOT BETWEEN 1 AND 64 OR octet_length(items::text)>65536 THEN RAISE EXCEPTION ''Publication group bound'' USING ERRCODE=''22023'';END IF;\n FOR v IN SELECT value FROM jsonb_array_elements(items) LOOP\n  IF jsonb_typeof(v) IS DISTINCT FROM ''object'' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v) key) IS DISTINCT FROM ARRAY[''byte_count'',''key'',''sha256'']::text[] OR jsonb_typeof(v->''key'') IS DISTINCT FROM ''string'' OR (v->>''key'') !~ ''^(raw|blob|batch|job|review|event):[a-z0-9:-]{1,160}$'' OR jsonb_typeof(v->''sha256'') IS DISTINCT FROM ''string'' OR (v->>''sha256'') !~ ''^[a-f0-9]{64}$'' OR jsonb_typeof(v->''byte_count'') IS DISTINCT FROM ''number'' OR (v->>''byte_count'') !~ ''^(0|[1-9][0-9]{0,15})$'' OR (v->>''byte_count'')::numeric>9007199254740991 OR (v->>''key'')=ANY(seen) THEN RAISE EXCEPTION ''Publication group item'' USING ERRCODE=''22023'';END IF;\n  seen:=array_append(seen,v->>''key'');\n END LOOP;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR SHARE;\n IF NOT FOUND OR b.state IS DISTINCT FROM ''open'' THEN RAISE EXCEPTION ''Publication reservation is not active/owned'' USING ERRCODE=''42501'';END IF;\n PERFORM 1 FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=ANY(seen) ORDER BY resource_key COLLATE \"C\" FOR SHARE;\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''key'') COLLATE \"C\" LOOP\n  SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=v->>''key'';\n  IF NOT FOUND OR x.state=''released'' OR x.byte_count IS DISTINCT FROM (v->>''byte_count'')::bigint OR x.sha256 IS DISTINCT FROM v->>''sha256'' THEN RAISE EXCEPTION ''Publication allocation changed/terminal'' USING ERRCODE=''40001'';END IF;\n END LOOP;\n -- Full fresh currentIAM/graph still present on both sides of pins; FS transaction caller also\n -- retains its original late checkpoint AFTER actual writes. There is no cached schema verdict.\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\nEND $function$\n","volatility":"v","body_sha256":"3e8e0c6adedf6290770084ef82ff4bf3fa14f12fbcbab33970ba5f26f6bb6786","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","items"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, request uuid, token text, kind0 text, raw0 bigint, metadata0 bigint, objects0 bigint","leakproof":false,"signature":"large_import_quota_reserve173(uuid,uuid,uuid,text,text,uuid,uuid,text,text,bigint,bigint,bigint)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_reserve173(u uuid, t uuid, k uuid, r text, h text, q uuid, request uuid, token text, kind0 text, raw0 bigint, metadata0 bigint, objects0 bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE old record;p record;x record;today date:=(clock_timestamp() AT TIME ZONE ''UTC'')::date;deadline timestamptz;\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF q IS NULL OR request IS NULL OR token IS NULL OR token !~ ''^[a-f0-9]{64}$'' OR kind0 IS NULL OR kind0 NOT IN(''upload'',''job'',''review'') OR raw0 IS NULL OR raw0<0 OR metadata0 IS NULL OR metadata0<0 OR objects0 IS NULL OR objects0<1 THEN RAISE EXCEPTION ''Quota reservation shape'' USING ERRCODE=''22023'';END IF;\n SELECT * INTO old FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND request_id=request FOR UPDATE;\n IF FOUND THEN\n  IF old.id IS DISTINCT FROM q OR old.actor_id IS DISTINCT FROM u OR old.api_key_id IS DISTINCT FROM k OR old.token_hash IS DISTINCT FROM token OR old.kind IS DISTINCT FROM kind0 OR old.raw_ceiling IS DISTINCT FROM raw0 OR old.metadata_ceiling IS DISTINCT FROM metadata0 OR old.objects_ceiling IS DISTINCT FROM objects0 THEN RAISE EXCEPTION ''Quota request identity conflict'' USING ERRCODE=''23505'';END IF;\n  RETURN (to_jsonb(old)-''token_hash'')||jsonb_build_object(''reused'',true); -- Exact uncertain-ACK lookup. No new capacity, expiry extension, callback rerun or token rotation.\n END IF;\n FOR p IN SELECT * FROM public.large_import_quota_policies173 WHERE scope IN(''global'',''tenant:''||t::text) ORDER BY scope FOR SHARE LOOP\n  SELECT coalesce(sum(CASE WHEN state=''retained'' THEN raw_charge ELSE raw_ceiling END),0) raw_used,\n   coalesce(sum(CASE WHEN state=''retained'' THEN metadata_charge ELSE metadata_ceiling END),0) metadata_used,\n   coalesce(sum(CASE WHEN state=''retained'' THEN objects_charge ELSE objects_ceiling END),0) objects_used,\n   count(*) FILTER(WHERE (opened_at AT TIME ZONE ''UTC'')::date=today) daily_used INTO x\n  FROM public.large_import_quota_reservations173 WHERE p.scope=''global'' OR tenant_id=t;\n  IF x.raw_used+p.baseline_raw+raw0>p.raw_limit OR x.metadata_used+p.baseline_metadata+metadata0>p.metadata_limit OR x.objects_used+p.baseline_objects+objects0>p.objects_limit OR x.daily_used+(CASE WHEN p.baseline_day=today THEN p.baseline_daily ELSE 0 END)+1>p.daily_limit THEN RAISE EXCEPTION ''Retained import quota exhausted'' USING ERRCODE=''54000'';END IF;\n END LOOP;\n SELECT clock_timestamp()+lease_seconds*interval ''1 second'' INTO deadline FROM public.large_import_quota_policies173 WHERE scope=''tenant:''||t::text;\n INSERT INTO public.large_import_quota_reservations173(tenant_id,id,actor_id,api_key_id,request_id,token_hash,kind,raw_ceiling,metadata_ceiling,objects_ceiling,expires_at) VALUES(t,q,u,k,request,token,kind0,raw0,metadata0,objects0,deadline) RETURNING * INTO old;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);RETURN (to_jsonb(old)-''token_hash'')||jsonb_build_object(''reused'',false);\nEND $function$\n","volatility":"v","body_sha256":"5ce0bd45268272956a61fefe19cd00310b48cf1f8c1978e58c64dcfab01877da","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","request","token","kind0","raw0","metadata0","objects0"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, n bigint, sha text, quarantined boolean","leakproof":false,"signature":"large_import_quota_settle173(uuid,uuid,uuid,text,text,uuid,text,text,bigint,text,boolean)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_settle173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, n bigint, sha text, quarantined boolean)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;x record;state0 text;\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF token IS NULL OR key0 IS NULL OR n IS NULL OR n<0 OR sha IS NULL OR quarantined IS NULL THEN RAISE EXCEPTION ''Quota settlement shape'' USING ERRCODE=''22023'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.state=''retained'' THEN RAISE EXCEPTION ''Quota settlement ownership/state'' USING ERRCODE=''42501'';END IF;\n SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0 FOR UPDATE;\n IF NOT FOUND OR x.byte_count IS DISTINCT FROM n OR x.sha256 IS DISTINCT FROM sha THEN RAISE EXCEPTION ''Quota inspected resource mismatch'' USING ERRCODE=''23514'';END IF;\n IF x.state=''released'' THEN RAISE EXCEPTION ''Terminal allocation cannot be settled as retained bytes'' USING ERRCODE=''23505'';END IF;\n state0:=(CASE WHEN quarantined THEN ''quarantined'' ELSE ''settled'' END);\n IF x.state=''quarantined'' AND state0<>''quarantined'' THEN RAISE EXCEPTION ''Quota settlement replay conflict'' USING ERRCODE=''23505'';END IF;\n UPDATE public.large_import_quota_resources173 SET state=state0 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0 RETURNING * INTO x;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);RETURN to_jsonb(x);\nEND $function$\n","volatility":"v","body_sha256":"8bd28f5a3e55d52c64eeea3fd3086097f4a32979ef050465d83611138fa24569","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","n","sha","quarantined"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb","leakproof":false,"signature":"large_import_quota_settle_many173(uuid,uuid,uuid,text,text,uuid,text,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_settle_many173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;x record;v jsonb;key0 text;kind0 text;n bigint;sha text;payload text;state0 text;seen text[]:=ARRAY[]::text[];result jsonb:=''[]''::jsonb;\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF q IS NULL OR token IS NULL OR token !~ ''^[a-f0-9]{64}$'' OR items IS NULL OR jsonb_typeof(items) IS DISTINCT FROM ''array'' THEN RAISE EXCEPTION ''Quota settlement group shape'' USING ERRCODE=''22023'';END IF;\n IF jsonb_array_length(items) NOT BETWEEN 1 AND 64 OR octet_length(items::text)>8388608 THEN RAISE EXCEPTION ''Quota settlement group bound'' USING ERRCODE=''22023'';END IF;\n FOR v IN SELECT value FROM jsonb_array_elements(items) LOOP\n  IF jsonb_typeof(v) IS DISTINCT FROM ''object'' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v) key) IS DISTINCT FROM ARRAY[''byte_count'',''key'',''kind'',''payload_text'',''sha256'',''state'']::text[] OR jsonb_typeof(v->''key'') IS DISTINCT FROM ''string'' OR jsonb_typeof(v->''kind'') IS DISTINCT FROM ''string'' OR jsonb_typeof(v->''sha256'') IS DISTINCT FROM ''string'' OR jsonb_typeof(v->''byte_count'') IS DISTINCT FROM ''number'' OR (v->>''byte_count'') !~ ''^(0|[1-9][0-9]{0,15})$'' OR jsonb_typeof(v->''state'') IS DISTINCT FROM ''string'' THEN RAISE EXCEPTION ''Quota settlement item shape'' USING ERRCODE=''22023'';END IF;\n  key0:=v->>''key'';kind0:=v->>''kind'';n:=(v->>''byte_count'')::bigint;sha:=v->>''sha256'';payload:=v->>''payload_text'';state0:=v->>''state'';\n  IF key0 !~ ''^(raw|blob|batch|job|review|event):[a-z0-9:-]{1,160}$'' OR kind0 NOT IN(''raw'',''blob'',''batch'',''job'',''review'',''event'') OR split_part(key0,'':'',1) IS DISTINCT FROM kind0 OR sha !~ ''^[a-f0-9]{64}$'' OR n>9007199254740991 OR key0=ANY(seen) OR state0 NOT IN(''settled'',''quarantined'') THEN RAISE EXCEPTION ''Quota settlement item identity'' USING ERRCODE=''22023'';END IF;\n  IF (kind0=''raw'' AND jsonb_typeof(v->''payload_text'') IS DISTINCT FROM ''null'') OR (kind0<>''raw'' AND (jsonb_typeof(v->''payload_text'') IS DISTINCT FROM ''string'' OR octet_length(payload) IS DISTINCT FROM n OR encode(sha256(convert_to(payload,''UTF8'')),''hex'') IS DISTINCT FROM sha)) THEN RAISE EXCEPTION ''Quota settlement exact payload'' USING ERRCODE=''23514'';END IF;\n  seen:=array_append(seen,key0);\n END LOOP;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.state=''retained'' THEN RAISE EXCEPTION ''Quota settlement ownership/state'' USING ERRCODE=''42501'';END IF;\n PERFORM 1 FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=ANY(seen) ORDER BY resource_key COLLATE \"C\" FOR UPDATE;\n -- Complete readback group is checked before the first state update; native bindings include\n -- full kind/payload as well as bytes/hash. UNKNOWN may settle prior observed bytes exactly as\n -- old settle173; it never permits new publication, minting or terminal ABSENT reopening.\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''key'') COLLATE \"C\" LOOP\n  SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=v->>''key'';\n  IF NOT FOUND OR x.kind IS DISTINCT FROM v->>''kind'' OR x.byte_count IS DISTINCT FROM (v->>''byte_count'')::bigint OR x.sha256 IS DISTINCT FROM v->>''sha256'' OR x.payload_text IS DISTINCT FROM v->>''payload_text'' THEN RAISE EXCEPTION ''Quota inspected group mismatch'' USING ERRCODE=''23514'';END IF;\n  IF x.state=''released'' OR (x.state=''quarantined'' AND v->>''state''<>''quarantined'') THEN RAISE EXCEPTION ''Quota settlement replay conflict'' USING ERRCODE=''23505'';END IF;\n END LOOP;\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''key'') COLLATE \"C\" LOOP\n  -- Deliberately retains old settle173 DML semantics even for identical-state replay.\n  UPDATE public.large_import_quota_resources173 SET state=v->>''state'' WHERE tenant_id=t AND reservation_id=q AND resource_key=v->>''key'' RETURNING * INTO x;\n  result:=result||jsonb_build_array(to_jsonb(x));\n END LOOP;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\n RETURN result;\nEND $function$\n","volatility":"v","body_sha256":"a4ea1839b0ed83787d295e397534678b4272d94a43179bcc28931445bdf29827","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","items"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text","leakproof":false,"signature":"large_import_quota_snapshot173(uuid,uuid,uuid,text,text,uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_snapshot173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;x jsonb;\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR SHARE;\n IF NOT FOUND THEN RAISE EXCEPTION ''Quota snapshot not owned'' USING ERRCODE=''42501'';END IF;\n SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE \"C\"),''[]''::jsonb) INTO x FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;\n RETURN jsonb_build_object(''reservation'',to_jsonb(b)-''token_hash'',''resources'',x);\nEND $function$\n","volatility":"v","body_sha256":"26649bcb6b833bb791e7d7d333635b2511a222ace3edb1c6de9a0a9e74e0ad99","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid","leakproof":false,"signature":"large_import_quota_terminal_begin173(uuid,uuid,uuid,text,text,uuid,text,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_terminal_begin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;x record;receipt record;classification text;policy_count integer;\nBEGIN\n IF current_setting(''transaction_isolation'') IS DISTINCT FROM ''read committed'' THEN RAISE EXCEPTION ''Terminal writes require READ COMMITTED'' USING ERRCODE=''25000'';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:global'',0));PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:tenant:''||t::text,0));\n PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN(''global'',''tenant:''||t::text) ORDER BY scope FOR SHARE;\n GET DIAGNOSTICS policy_count=ROW_COUNT;\n IF policy_count<>2 THEN RAISE EXCEPTION ''Terminal quota policy absent'' USING ERRCODE=''55000'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.kind<>''upload'' OR client0 IS NULL THEN RAISE EXCEPTION ''Terminal upload reservation not owned'' USING ERRCODE=''42501'';END IF;\n SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0 FOR UPDATE;\n IF NOT FOUND OR x.kind<>''blob'' THEN RAISE EXCEPTION ''Only exact upload cleanup allocations are terminal candidates'' USING ERRCODE=''22023'';END IF;\n IF x.state=''released'' THEN\n  SELECT * INTO receipt FROM public.large_import_quota_terminal_receipts173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n  IF NOT FOUND OR receipt.client_key IS DISTINCT FROM client0 THEN RAISE EXCEPTION ''Terminal exact-key recovery conflict'' USING ERRCODE=''23505'';END IF;\n  RETURN jsonb_build_object(''reused'',true,''receipt'',to_jsonb(receipt)); -- Read original receipt; no FS callback, new evidence, time or key.\n END IF;\n IF b.state=''retained'' THEN RAISE EXCEPTION ''Closed quota cannot be rewritten'' USING ERRCODE=''42501'';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true); -- Refresh after reservation lock, before the private FS cut.\n IF key0 ~ ''^blob:fs:blobs:[a-f0-9-]{36}:quarantine-json$'' AND x.state=''intent'' THEN classification:=''unused-quarantine'';\n ELSIF key0 ~ ''^blob:fs:(blobs|uploads|witnesses):[a-f0-9-]{36}:lock:[a-f0-9-]{36}$'' AND x.state IN(''intent'',''settled'') THEN classification:=''released-lock'';\n ELSE RAISE EXCEPTION ''Allocation is not a cancellable cleanup/lock'' USING ERRCODE=''22023'';END IF;\n RETURN jsonb_build_object(''reused'',false,''classification'',classification,''reservation'',to_jsonb(b)-''token_hash'',''resource'',to_jsonb(x));\nEND $function$\n","volatility":"v","body_sha256":"7c7fc4e216bfe5d5488ae717d1e8167ecbcd15ea98daf917eb5a3d19e8e89a38","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","client0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid","leakproof":false,"signature":"large_import_quota_terminal_close_begin173(uuid,uuid,uuid,text,text,uuid,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_terminal_close_begin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE b record;policy_count integer;old record;snapshot0 jsonb;\nBEGIN\n IF current_setting(''transaction_isolation'') IS DISTINCT FROM ''read committed'' THEN RAISE EXCEPTION ''Terminal writes require READ COMMITTED'' USING ERRCODE=''25000'';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:global'',0));PERFORM pg_advisory_xact_lock(hashtextextended(''large-import173:quota:tenant:''||t::text,0));\n PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN(''global'',''tenant:''||t::text) ORDER BY scope FOR SHARE;GET DIAGNOSTICS policy_count=ROW_COUNT;\n IF policy_count<>2 THEN RAISE EXCEPTION ''Terminal quota policy absent'' USING ERRCODE=''55000'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.kind<>''upload'' OR client0 IS NULL THEN RAISE EXCEPTION ''Known-close upload not owned'' USING ERRCODE=''42501'';END IF;\n IF b.state=''retained'' THEN\n  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=''event:upload-known-close:''||client0::text AND state=''settled'';\n  IF NOT FOUND OR b.outcome<>''ready'' OR old.payload_text::jsonb->''receipt''->>''client_key'' IS DISTINCT FROM client0::text THEN RAISE EXCEPTION ''Known-close original key conflict'' USING ERRCODE=''23505'';END IF;\n  RETURN jsonb_build_object(''reused'',true,''reservation'',to_jsonb(b)-''token_hash'',''receipt'',old.payload_text::jsonb->''receipt''); -- no fresh cut or callback on exact old-key recovery\n END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE \"C\"),''[]''::jsonb) INTO snapshot0 FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;\n IF jsonb_array_length(snapshot0)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot0) x WHERE x->>''state''=''intent'') THEN RAISE EXCEPTION ''Known close has pending original allocations'' USING ERRCODE=''40001'';END IF;\n RETURN jsonb_build_object(''reused'',false,''reservation'',to_jsonb(b)-''token_hash'',''resources'',snapshot0);\nEND $function$\n","volatility":"v","body_sha256":"40781129baeb2b9756351d74242ab2eaab9ba90060a1e7797c8ba0c7a2e78ccb","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","client0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text","leakproof":false,"signature":"large_import_quota_terminal_close_finish173(uuid,uuid,uuid,text,text,uuid,text,uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_terminal_close_finish173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE fact jsonb;p jsonb;wanted jsonb;b record;charges record;receipt0 jsonb;evidence0 text;key0 text;inventory0 text;\nBEGIN\n fact:=public.large_import_quota_terminal_close_begin173(u,t,k,r,h,q,token,client0);IF fact->''reused''=''true''::jsonb THEN RETURN fact;END IF;\n IF proof0 IS NULL OR octet_length(proof0)>8388608 THEN RAISE EXCEPTION ''Known-close bounded private proof required'' USING ERRCODE=''22023'';END IF;\n p:=proof0::jsonb;\n SELECT coalesce(jsonb_agg(jsonb_build_object(''resource_key'',z->>''resource_key'',''kind'',z->>''kind'',''byte_count'',z->''byte_count'',''sha256'',z->>''sha256'',''state'',z->>''state'') ORDER BY z->>''resource_key'' COLLATE \"C\"),''[]''::jsonb) INTO wanted FROM jsonb_array_elements(fact->''resources'') z;\n IF jsonb_typeof(p) IS DISTINCT FROM ''object'' OR (SELECT count(*) FROM jsonb_object_keys(p))<>7 OR p->>''schema'' IS DISTINCT FROM ''private-upload-known-close/v1''\n OR p->''scope'' IS DISTINCT FROM jsonb_build_object(''tenantId'',t,''actorId'',u,''apiKeyId'',k) OR p->>''reservation_id'' IS DISTINCT FROM q::text\n OR p->>''request_id'' IS DISTINCT FROM fact->''reservation''->>''request_id'' OR p->''resources'' IS DISTINCT FROM wanted\n OR jsonb_typeof(p->''fs_cut'') IS DISTINCT FROM ''array'' OR jsonb_array_length(p->''fs_cut'')<1\n OR jsonb_typeof(p->''metadata_cut'') IS DISTINCT FROM ''array'' OR jsonb_array_length(p->''metadata_cut'')<1 THEN RAISE EXCEPTION ''Known-close full original inventory mismatch'' USING ERRCODE=''23514'';END IF;\n IF EXISTS(SELECT 1 FROM public.large_import_quota_resources173 z WHERE z.tenant_id=t AND z.reservation_id=q AND z.state=''released'' AND NOT EXISTS(SELECT 1 FROM public.large_import_quota_terminal_receipts173 e WHERE(e.tenant_id,e.reservation_id,e.resource_key)=(z.tenant_id,z.reservation_id,z.resource_key))) THEN RAISE EXCEPTION ''Released allocation lacks immutable native receipt'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q;\n inventory0:=encode(sha256(convert_to(proof0,''UTF8'')),''hex'');receipt0:=jsonb_build_object(''schema'',''quota-known-close-receipt/v1'',''client_key'',client0,''tenant_id'',t,''reservation_id'',q,''request_id'',b.request_id,''inventory_sha256'',inventory0,''native_time'',clock_timestamp());\n evidence0:=jsonb_build_object(''schema'',''quota-known-close-evidence/v1'',''inventory_text'',proof0,''receipt'',receipt0)::text;key0:=''event:upload-known-close:''||client0::text;\n IF octet_length(evidence0)>8388608 THEN RAISE EXCEPTION ''Known-close evidence limit'' USING ERRCODE=''54000'