NCT FROM manual_inventory_off_fingerprint()\n OR NOT manual_inventory_off_projection_valid()\n OR cert->>''''original160_fingerprint'''' IS DISTINCT FROM b2b_credit_fingerprint() THEN RETURN false;END IF;\n FOR n,v IN SELECT key,value FROM jsonb_each(cert->''''successor_functions'''') LOOP\n SELECT prosrc INTO actual FROM pg_proc WHERE oid=(''''public.''''||n||CASE n WHEN ''''catalog_stock_control_effect_prepare'''' THEN ''''(uuid,uuid,jsonb)'''' WHEN ''''catalog_stock_control_effect_validate'''' THEN ''''(uuid)'''' ELSE ''''()'''' END)::regprocedure;\n IF actual IS DISTINCT FROM v->>''''body'''' THEN RETURN false;END IF;END LOOP;\n IF EXISTS(SELECT FROM migrations WHERE name=''''169_manual_inventory_off'''') THEN RETURN true;END IF;\n IF current_user=ownrole AND session_user=ownrole AND to_regclass(''''pg_temp.manual_inventory_off_install_basis'''') IS NOT NULL THEN\n SELECT EXISTS(SELECT FROM pg_temp.manual_inventory_off_install_basis b WHERE b.owner_name=ownrole AND b.root_xid=pg_current_xact_id()::text AND b.start_at=transaction_timestamp() AND b.backend_pid=pg_backend_pid()\n AND b.original152_manifest=cert->''''original152_manifest'''' AND b.changed_functions=cert->''''predecessor_functions'''') INTO bootstrap;END IF;RETURN bootstrap;\nEXCEPTION WHEN undefined_table OR undefined_function OR undefined_column THEN RETURN false;END$function$\n","volatility":"v","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":true},"warehouse_wz_issuer_guards":{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"warehouse_wz_issuer_guards()","definition":"CREATE OR REPLACE FUNCTION public.warehouse_wz_issuer_guards()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''