_quota_terminal_receipts173_receipt_sha256_not_null","relation":"large_import_quota_terminal_receipts173"},{"name":"large_import_quota_terminal_receipts173_receipt_text_check","relation":"large_import_quota_terminal_receipts173"},{"name":"large_import_quota_terminal_receipts173_receipt_text_not_null","relation":"large_import_quota_terminal_receipts173"},{"name":"large_import_quota_terminal_receipts173_reservation_id_not_null","relation":"large_import_quota_terminal_receipts173"},{"name":"large_import_quota_terminal_receipts173_resource_key_not_null","relation":"large_import_quota_terminal_receipts173"},{"name":"large_import_quota_terminal_receipts173_tenant_id_not_null","relation":"large_import_quota_terminal_receipts173"},{"name":"large_import_quota_terminal_receipts17_tenant_id_client_key_key","relation":"large_import_quota_terminal_receipts173"},{"name":"large_import_quota_terminal_w_tenant_id_reservation_id_res_fkey","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_check","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_classification_check","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_client_key_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_created_at_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_original_bytes_check","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_original_sha256_check","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_original_state_check","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_pkey","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_resource_key_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_tenant_id_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_witness_text_check","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses173_witness_text_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses17_classification_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses17_original_bytes_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses17_original_state_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses17_reservation_id_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses17_witness_sha256_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses1_original_sha256_not_null","relation":"large_import_quota_terminal_witnesses173"},{"name":"large_import_quota_terminal_witnesses1_tenant_id_client_key_key","relation":"large_import_quota_terminal_witnesses173"}]},"functions":[{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, w boolean","leakproof":false,"signature":"large_import173_admit(uuid,uuid,uuid,text,text,boolean)","definition":"CREATE OR REPLACE FUNCTION public.large_import173_admit(u uuid, t uuid, k uuid, r text, h text, w boolean)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE x record;v_now timestamptz;\nBEGIN\n IF u IS NULL OR t IS NULL OR r IS NULL OR r NOT IN(''''admin'''',''''operator'''',''''viewer'''') OR h IS NULL OR h !~ ''''^[a-f0-9]{64}$'''' OR w IS NULL THEN\n  RAISE EXCEPTION ''''Invalid metadata authority'''' USING ERRCODE=''''42501'''';\n END IF;\n -- SD current_user is the module owner. The caller remains the dedicated owner''''s SESSION dyna_app connection.\n IF current_setting(''''role'''',true) IS DISTINCT FROM ''''dyna_app''''\n OR session_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=to_regclass(''''public.large_import173_certificate'''')))\n OR t IS DISTINCT FROM nullif(current_setting(''''app.tenant_id'''',true),'''''''')::uuid THEN\n  RAISE EXCEPTION ''''Metadata app-role tenant transport mismatch'''' USING ERRCODE=''''42501'''';\n END IF;\n -- Owner startup MUST independently pin the complete current body/catalog graph before setting app role.\n -- This leaf check alone is not self-attestation. The new helper+grant must be in that compiled certificate graph.\n IF public.large_import173_valid() IS DISTINCT FROM true THEN\n  RAISE EXCEPTION ''''Metadata173 is not certified'''' USING ERRCODE=''''55000'''';\n END IF;\n -- Same order as native170 pin path; independent authority, without its lifecycle.\n -- Actual metadata checkpoint caller must be inside BEGIN; locks then survive through its COMMIT/ROLLBACK.\n PERFORM 1 FROM public.users WHERE id=u FOR SHARE;\n PERFORM 1 FROM public.tenants WHERE id=t FOR SHARE;\n PERFORM 1 FROM public.account_security WHERE user_id=u FOR SHARE;\n PERFORM 1 FROM public.workspace_security_policies WHERE tenant_id=t FOR SHARE;\n PERFORM 1 FROM public.memberships WHERE(user_id,tenant_id)=(u,t) FOR SHARE;\n IF k IS NULL THEN\n  PERFORM 1 FROM public.sessions WHERE(token_hash,user_id,tenant_id)=(h,u,t) FOR SHARE;\n ELSE\n  PERFORM 1 FROM public.api_keys WHERE(id,user_id,tenant_id)=(k,u,t) FOR SHARE;\n END IF;\n v_now:=clock_timestamp();\n IF k IS NULL THEN\n  SELECT m.role,coalesce(a.version,0)::text account_version,true scope_ok,\n   least(s.expires_at,CASE WHEN coalesce(p.require_mfa,false) THEN s.mfa_verified_at+interval ''''8 hours'''' ELSE s.expires_at END) deadline,\n   coalesce(p.require_mfa,false) AND NOT(coalesce(a.enabled_at IS NOT NULL AND s.mfa_verified_at IS NOT NULL AND s.mfa_verified_at>v_now-interval ''''8 hours'''',false)) mfa_required INTO x\n  FROM public.sessions s JOIN public.users z ON z.id=s.user_id JOIN public.tenants n ON n.id=s.tenant_id\n  JOIN public.memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)\n  LEFT JOIN public.account_security a ON a.user_id=z.id LEFT JOIN public.workspace_security_policies p ON p.tenant_id=n.id\n  WHERE(s.token_hash,s.user_id,s.tenant_id)=(h,u,t) AND s.expires_at>v_now AND s.account_version=coalesce(a.version,0);\n ELSE\n  SELECT m.role,coalesce(a.version,0)::text account_version,k0.expires_at deadline,\n   k0.scopes@>CASE WHEN w THEN ARRAY[''''products:read'''',''''products:write'''']::text[] ELSE ARRAY[''''products:read'''']::text[] END scope_ok,\n   coalesce(p.require_mfa,false) AND a.enabled_at IS NULL mfa_required INTO x\n  FROM public.api_keys k0 JOIN public.users z ON z.id=k0.user_id JOIN public.tenants n ON n.id=k0.tenant_id\n  JOIN public.memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)\n  LEFT JOIN public.account_security a ON a.user_id=z.id LEFT JOIN public.workspace_security_policies p ON p.tenant_id=n.id\n  WHERE(k0.id,k0.token_hash,k0.user_id,k0.tenant_id)=(k,h,u,t) AND k0.revoked_at IS NULL AND k0.expires_at>v_now;\n END IF;\n IF x.role IS NULL OR x.deadline IS NULL OR NOT isfinite(x.deadline) OR x.deadline<=clock_timestamp() THEN\n  RAISE EXCEPTION ''''Expired metadata authority'''' USING ERRCODE=''''28000'''';\n END IF;\n IF x.role<>r THEN RAISE EXCEPTION ''''Metadata role changed'''' USING ERRCODE=''''40001'''';END IF;\n IF NOT coalesce(x.scope_ok,false) OR coalesce(x.mfa_required,true) OR(w AND x.role<>''''admin'''') THEN\n  RAISE EXCEPTION ''''Missing current metadata authority'''' USING ERRCODE=''''42501'''';\n END IF;\nEND\n$function$\n","volatility":"v","body_sha256":"239d1eb13343a59f2ca8a736c89eaf56d62192cc883e240137a3a86bfd5b5501","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","w"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"trigger","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"large_import173_append_guard()","definition":"CREATE OR REPLACE FUNCTION public.large_import173_append_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''pg_catalog'''', ''''public''''\nAS $function$\nDECLARE b public.large_import_blobs173%ROWTYPE;oldpart public.large_import_parts173%ROWTYPE;n bigint;j jsonb;\nBEGIN\n IF TG_OP<>''''INSERT'''' THEN RAISE EXCEPTION ''''Large import evidence is append only'''' USING ERRCODE=''''23514'''';END IF;\n IF TG_TABLE_NAME=''''large_import_events173'''' THEN\n  SELECT state_text::jsonb INTO j FROM public.large_import_jobs173 WHERE tenant_id=NEW.tenant_id AND id=NEW.job_id;\n  IF j->''''events''''->(NEW.sequence::integer) IS DISTINCT FROM NEW.event_text::jsonb OR (j->>''''revision'''')::bigint IS NULL OR (j->>''''revision'''')::bigint<NEW.revision THEN RAISE EXCEPTION ''''Event does not match saved job'''' USING ERRCODE=''''23514'''';END IF;RETURN NEW;\n END IF;\n SELECT * INTO STRICT b FROM public.large_import_blobs173 WHERE tenant_id=NEW.tenant_id AND id=NEW.blob_id FOR UPDATE;\n IF b.raw_sha256 IS NOT NULL THEN RAISE EXCEPTION ''''Original blob is sealed'''' USING ERRCODE=''''23514'''';END IF;\n IF TG_TABLE_NAME=''''large_import_parts173'''' THEN\n  SELECT * INTO oldpart FROM public.large_import_parts173 WHERE (tenant_id,blob_id,offset_bytes)=(NEW.tenant_id,NEW.blob_id,NEW.offset_bytes);\n  IF FOUND THEN IF (oldpart.byte_count,oldpart.sha256) IS DISTINCT FROM (NEW.byte_count,NEW.sha256) THEN RAISE EXCEPTION ''''Part replay differs'''' USING ERRCODE=''''23514'''';END IF;RETURN NEW;END IF;\n  SELECT coalesce(sum(byte_count),0) INTO n FROM public.large_import_parts173 WHERE tenant_id=NEW.tenant_id AND blob_id=NEW.blob_id;\n  IF NEW.offset_bytes<>n OR n+NEW.byte_count>b.max_bytes THEN RAISE EXCEPTION ''''Raw part is not contiguous/bounded'''' USING ERRCODE=''''23514'''';END IF;\n ELSE\n  j:=NEW.batch_text::jsonb;IF jsonb_typeof(j) IS DISTINCT FROM ''''object'''' OR j->>''''schema'''' IS DISTINCT FROM ''''large-core-import-parser-batch/v1'''' OR j->''''provisional'''' IS DISTINCT FROM ''''true''''::jsonb OR jsonb_typeof(j->''''index'''') IS DISTINCT FROM ''''number'''' OR (j->>''''index'''') !~ ''''^(0|[1-9][0-9]*)$'''' OR (j->>''''index'''')::integer IS DISTINCT FROM NEW.index OR j->>''''id'''' IS DISTINCT FROM NEW.id OR jsonb_typeof(j->''''normalized_bytes'''') IS DISTINCT FROM ''''number'''' OR (j->>''''normalized_bytes'''') !~ ''''^[1-9][0-9]*$'''' OR (j->>''''normalized_bytes'''')::bigint NOT BETWEEN 1 AND 2097152 OR jsonb_typeof(j->''''records'''') IS DISTINCT FROM ''''array'''' THEN RAISE EXCEPTION ''''Parser batch differs'''' USING ERRCODE=''''23514'''';END IF;\n  IF (SELECT count(*) FROM jsonb_object_keys(j))<>6 OR EXISTS(SELECT 1 FROM jsonb_object_keys(j) x WHERE x<>ALL(ARRAY[''''schema'''',''''provisional'''',''''index'''',''''id'''',''''normalized_bytes'''',''''records''''])) OR jsonb_array_length(j->''''records'''') NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION ''''Invalid parser batch shape'''' USING ERRCODE=''''23514'''';END IF;\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(j->''''records'''') r WHERE jsonb_typeof(r) IS DISTINCT FROM ''''object'''' OR jsonb_typeof(r->''''span'''') IS DISTINCT FROM ''''object'''' OR jsonb_typeof(r->''''data'''') IS DISTINCT FROM ''''object'''') THEN RAISE EXCEPTION ''''Parser record requires span and data'''' USING ERRCODE=''''23514'''';END IF;\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(j->''''records'''') r WHERE (SELECT count(*) FROM jsonb_object_keys(r))<>2 OR NOT (r ?& ARRAY[''''span'''',''''data'''']) OR (SELECT count(*) FROM jsonb_object_keys(r->''''span''''))<>6 OR NOT (r->''''span'''' ?& ARRAY[''''ordinal'''',''''byte_start'''',''''byte_end'''',''''line_start'''',''''line_end'''',''''raw_sha256'''']) OR jsonb_typeof(r->''''span''''->''''ordinal'''') IS DISTINCT FROM ''''number'''' OR jsonb_typeof(r->''''span''''->''''byte_start'''') IS DISTINCT FROM ''''number'''' OR jsonb_typeof(r->''''span''''->''''byte_end'''') IS DISTINCT FROM ''''number'''' OR jsonb_typeof(r->''''span''''->''''line_start'''') IS DISTINCT FROM ''''number'''' OR jsonb_typeof(r->''''span''''->''''line_end'''') IS DISTINCT FROM ''''number'''' OR jsonb_typeof(r->''''span''''->''''raw_sha256'''') IS DISTINCT FROM ''''string'''' OR (r#>>''''{span,raw_sha256}'''') !~ ''''^[a-f0-9]{64}$'''') THEN RAISE EXCEPTION ''''Invalid parser span shape'''' USING ERRCODE=''''23514'''';END IF;\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(j->''''records'''') r WHERE (r#>>''''{span,ordinal}'''') !~ ''''^(0|[1-9][0-9]*)$'''' OR (r#>>''''{span,byte_start}'''') !~ ''''^(0|[1-9][0-9]*)$'''' OR (r#>>''''{span,byte_end}'''') !~ ''''^[1-9][0-9]*$'''' OR (r#>>''''{span,line_start}'''') !~ ''''^[1-9][0-9]*$'''' OR (r#>>''''{span,line_end}'''') !~ ''''^[1-9][0-9]*$'''' OR (r#>>''''{span,byte_start}'''')::bigint>=(r#>>''''{span,byte_end}'''')::bigint OR (r#>>''''{span,byte_end}'''')::bigint>30000000 OR (r#>>''''{span,line_start}'''')::bigint>(r#>>''''{span,line_end}'''')::bigint) THEN RAISE EXCEPTION ''''Parser span must use bounded integer positions'''' USING ERRCODE=''''23514'''';END IF;\n END IF;RETURN NEW;\nEND $function$\n","volatility":"v","body_sha256":"77510cea0885ecdda464224dfcccfeb657c79def3cdf6fab58537764c5a68aaa","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"trigger","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"large_import173_blob_guard()","definition":"CREATE OR REPLACE FUNCTION public.large_import173_blob_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''pg_catalog'''', ''''public''''\nAS $function$\nDECLARE total bigint;records_count bigint:=0;m jsonb;d jsonb;batch public.large_import_batches173%ROWTYPE;n integer:=0;\nBEGIN\n IF TG_OP=''''DELETE'''' THEN RAISE EXCEPTION ''''Raw blob is retained'''' USING ERRCODE=''''23514'''';END IF;\n IF TG_OP=''''INSERT'''' THEN\n  IF NEW.raw_sha256 IS NOT NULL OR NEW.raw_bytes IS NOT NULL OR NEW.completed_eof IS NOT NULL OR NEW.parse_valid IS NOT NULL OR NEW.manifest_text IS NOT NULL OR NEW.manifest_sha256 IS NOT NULL THEN RAISE EXCEPTION ''''Original blob must start as empty unsealed upload'''' USING ERRCODE=''''23514'''';END IF;\n  RETURN NEW;\n END IF;\n IF (NEW.tenant_id,NEW.id,NEW.actor_id,NEW.api_key_id,NEW.storage_id,NEW.spec_text,NEW.max_bytes,NEW.created_at) IS DISTINCT FROM (OLD.tenant_id,OLD.id,OLD.actor_id,OLD.api_key_id,OLD.storage_id,OLD.spec_text,OLD.max_bytes,OLD.created_at) THEN RAISE EXCEPTION ''''Raw identity/spec are immutable'''' USING ERRCODE=''''23514'''';END IF;\n IF OLD.raw_sha256 IS NOT NULL AND (NEW.raw_sha256,NEW.raw_bytes,NEW.completed_eof,NEW.parse_valid) IS DISTINCT FROM (OLD.raw_sha256,OLD.raw_bytes,OLD.completed_eof,OLD.parse_valid) THEN RAISE EXCEPTION ''''Raw seal is immutable'''' USING ERRCODE=''''23514'''';END IF;\n IF OLD.manifest_text IS NOT NULL AND (NEW.manifest_text,NEW.manifest_sha256) IS DISTINCT FROM (OLD.manifest_text,OLD.manifest_sha256) THEN RAISE EXCEPTION ''''Manifest is immutable'''' USING ERRCODE=''''23514'''';END IF;\n SELECT coalesce(sum(byte_count),0) INTO total FROM public.large_import_parts173 WHERE tenant_id=NEW.tenant_id AND blob_id=NEW.id;\n IF NEW.raw_bytes IS NOT NULL AND NEW.raw_bytes<>total THEN RAISE EXCEPTION ''''Raw seal byte count differs'''' USING ERRCODE=''''23514'''';END IF;\n IF NEW.manifest_text IS NOT NULL THEN m:=NEW.manifest_text::jsonb;\n  IF jsonb_typeof(m) IS DISTINCT FROM ''''object'''' OR m->>''''schema'''' IS DISTINCT FROM ''''large-core-import-file/v1'''' OR jsonb_typeof(m->''''raw'''') IS DISTINCT FROM ''''object'''' OR m#>>''''{raw,sha256}'''' IS DISTINCT FROM NEW.raw_sha256 OR jsonb_typeof(m#>''''{raw,byte_count}'''') IS DISTINCT FROM ''''number'''' OR (m#>>''''{raw,byte_count}'''') !~ ''''^[1-9][0-9]*$'''' OR (m#>>''''{raw,byte_count}'''')::bigint IS DISTINCT FROM NEW.raw_bytes OR m#>''''{raw,completed_eof}'''' IS DISTINCT FROM ''''true''''::jsonb OR m#>''''{raw,parse_valid}'''' IS DISTINCT FROM ''''true''''::jsonb OR jsonb_typeof(m->''''batches'''') IS DISTINCT FROM ''''array'''' OR jsonb_typeof(m->''''records'''') IS DISTINCT FROM ''''number'''' OR (m->>''''records'''') !~ ''''^[1-9][0-9]*$'''' OR jsonb_typeof(m->''''total_batches'''') IS DISTINCT FROM ''''number'''' OR (m->>''''total_batches'''') !~ ''''^[1-9][0-9]*$'''' THEN RAISE EXCEPTION ''''Manifest raw seal differs'''' USING ERRCODE=''''23514'''';END IF;\n  IF m->>''''format'''' IS DISTINCT FROM ''''csv'''' AND m->>''''format'''' IS DISTINCT FROM ''''xml'''' OR (SELECT count(*) FROM jsonb_object_keys(m->''''raw''''))<>4 OR NOT (m->''''raw'''' ?& ARRAY[''''sha256'''',''''byte_count'''',''''completed_eof'''',''''parse_valid'''']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(m) x WHERE x<>ALL(ARRAY[''''schema'''',''''format'''',''''raw'''',''''records'''',''''total_batches'''',''''batches'''',''''header'''',''''raw_header''''])) OR NOT (m ?& ARRAY[''''schema'''',''''format'''',''''raw'''',''''records'''',''''total_batches'''',''''batches'''']) THEN RAISE EXCEPTION ''''Invalid manifest shape'''' USING ERRCODE=''''23514'''';END IF;\n  IF m->>''''format''''=''''csv'''' THEN IF jsonb_typeof(m->''''header'''') IS DISTINCT FROM ''''array'''' OR jsonb_typeof(m->''''raw_header'''') IS DISTINCT FROM ''''array'''' THEN RAISE EXCEPTION ''''CSV header is required'''' USING ERRCODE=''''23514'''';END IF;IF jsonb_array_length(m->''''header'''') NOT BETWEEN 1 AND 1000 OR jsonb_array_length(m->''''raw_header'''') IS DISTINCT FROM jsonb_array_length(m->''''header'''') OR EXISTS(SELECT 1 FROM jsonb_array_elements(m->''''header'''') x WHERE jsonb_typeof(x) IS DISTINCT FROM ''''string'''') OR EXISTS(SELECT 1 FROM jsonb_array_elements(m->''''raw_header'''') x WHERE jsonb_typeof(x) IS DISTINCT FROM ''''string'''') THEN RAISE EXCEPTION ''''CSV header differs'''' USING ERRCODE=''''23514'''';END IF;ELSIF m ? ''''header'''' OR m ? ''''raw_header'''' THEN RAISE EXCEPTION ''''XML cannot claim CSV headers'''' USING ERRCODE=''''23514'''';END IF;\n  FOR d IN SELECT value FROM jsonb_array_elements(m->''''batches'''') LOOP\n   SELECT * INTO STRICT batch FROM public.large_import_batches173 WHERE tenant_id=NEW.tenant_id AND blob_id=NEW.id AND index=n;\n   IF jsonb_typeof(d) IS DISTINCT FROM ''''object'''' OR jsonb_typeof(d->''''index'''') IS DISTINCT FROM ''''number'''' OR (d->>''''index'''') !~ ''''^(0|[1-9][0-9]*)$'''' OR (d->>''''index'''')::integer IS DISTINCT FROM n OR d->>''''id'''' IS DISTINCT FROM batch.id OR d->>''''ref'''' IS DISTINCT FROM (''''large-import-batch/v1:''''||NEW.id::text||'''':''''||n::text||'''':''''||batch.id) OR jsonb_typeof(d->''''rows'''') IS DISTINCT FROM ''''number'''' OR (d->>''''rows'''') !~ ''''^[1-9][0-9]*$'''' OR (d->>''''rows'''')::integer IS DISTINCT FROM jsonb_array_length(batch.batch_text::jsonb->''''records'''') OR d->''''normalized_bytes'''' IS DISTINCT FROM batch.batch_text::jsonb->''''normalized_bytes'''' OR d->''''record_spans'''' IS DISTINCT FROM (SELECT jsonb_agg(value->''''span'''' ORDER BY ord) FROM jsonb_array_elements(batch.batch_text::jsonb->''''records'''') WITH ORDINALITY x(value,ord)) THEN RAISE EXCEPTION ''''Manifest batch differs'''' USING ERRCODE=''''23514'''';END IF;IF (SELECT count(*) FROM jsonb_object_keys(d))<>6 OR NOT (d ?& ARRAY[''''index'''',''''id'''',''''rows'''',''''normalized_bytes'''',''''record_spans'''',''''ref'''']) THEN RAISE EXCEPTION ''''Invalid manifest descriptor shape'''' USING ERRCODE=''''23514'''';END IF;records_count:=records_count+(d->>''''rows'''')::integer;n:=n+1;\n  END LOOP;\n  IF n=0 OR (m->>''''records'''')::bigint IS DISTINCT FROM records_count OR (m->>''''total_batches'''')::integer IS DISTINCT FROM n OR n<>(SELECT count(*) FROM public.large_import_batches173 WHERE tenant_id=NEW.tenant_id AND blob_id=NEW.id) THEN RAISE EXCEPTION ''''Manifest batch count differs'''' USING ERRCODE=''''23514'''';END IF;\n END IF;RETURN NEW;\nEND $function$\n","volatility":"v","body_sha256":"9fb461bdb64c2b54bcbe4ee9bc6f7c49f7592021e47b1f94c5bb529924b3bba7","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"trigger","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"large_import173_certificate_seal()","definition":"CREATE OR REPLACE FUNCTION public.large_import173_certificate_seal()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nBEGIN\n IF TG_OP<>''''INSERT'''' OR current_user<>session_user OR NOT NEW.singleton\n OR EXISTS(SELECT 1 FROM public.large_import173_certificate)\n OR NEW.profile IS DISTINCT FROM public.large_import173_metadata()\n OR NEW.predecessor_map IS DISTINCT FROM public.large_import173_predecessor_map()\n OR public.large_import173_parents_valid() IS DISTINCT FROM true THEN\n  RAISE EXCEPTION ''''Large import173 certificate is immutable'''' USING ERRCODE=''''23514'''';\n END IF;RETURN NEW;\nEND\n$function$\n","volatility":"v","body_sha256":"3f3e095e95ec07055afe2160a946aabb32de2644a68cfba23765e23a0ce71cc4","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":null,"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"sql","parallel":"u","arguments":"j jsonb","leakproof":false,"signature":"large_import173_immutable(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.large_import173_immutable(j jsonb)\n RETURNS jsonb\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''''pg_catalog''''\nAS $function$\n SELECT jsonb_build_object(''''schema'''',j->''''schema'''',''''id'''',j->''''id'''',''''principal'''',j->''''principal'''',''''raw'''',j->''''raw'''',''''manifest'''',j->''''manifest'''',''''parsing_spec'''',j->''''parsing_spec'''',''''plan_hash'''',j->''''plan_hash'''',\n ''''core'''',(SELECT jsonb_agg(jsonb_build_object(''''previewKey'''',c->''''previewKey'''',''''executeKey'''',c->''''executeKey'''',''''request'''',c->''''request'''',''''identities'''',c->''''identities'''') ORDER BY n) FROM jsonb_array_elements(j->''''core'''') WITH ORDINALITY AS a(c,n)))\n$function$\n","volatility":"i","body_sha256":"52ff690fe2bf4bb9872751dc3327218ee2804b8696e1ddf4a490e46e0afaf5b4","returns_set":false,"configuration":["search_path=pg_catalog"],"argument_modes":null,"argument_names":["j"],"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"trigger","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"large_import173_job_guard()","definition":"CREATE OR REPLACE FUNCTION public.large_import173_job_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''pg_catalog'''', ''''public''''\nAS $function$\nDECLARE b jsonb:=CASE WHEN TG_OP=''''UPDATE'''' THEN OLD.state_text::jsonb ELSE NULL END;n jsonb:=NEW.state_text::jsonb;c jsonb;p jsonb;k text;pimkey text;i integer;a jsonb;lock_key bigint;\nBEGIN\n IF TG_OP=''''DELETE'''' THEN RAISE EXCEPTION ''''Large import history is immutable'''' USING ERRCODE=''''23514'''';END IF;\n IF jsonb_typeof(n) IS DISTINCT FROM ''''object'''' OR n->>''''schema'''' IS DISTINCT FROM ''''large-import-job/v1'''' OR (n->>''''id'''')::uuid IS DISTINCT FROM NEW.id OR (n#>>''''{principal,tenantId}'''')::uuid IS DISTINCT FROM NEW.tenant_id OR (n#>>''''{principal,userId}'''')::uuid IS DISTINCT FROM NEW.actor_id OR (n#>>''''{principal,apiKeyId}'''')::uuid IS DISTINCT FROM NEW.api_key_id OR n->>''''plan_hash'''' IS DISTINCT FROM NEW.plan_hash OR (n->>''''revision'''')::bigint IS DISTINCT FROM NEW.revision THEN RAISE EXCEPTION ''''Large import state identity differs'''' USING ERRCODE=''''23514'''';END IF;\n IF jsonb_typeof(n->''''principal'''') IS DISTINCT FROM ''''object'''' OR jsonb_typeof(n->''''raw'''') IS DISTINCT FROM ''''object'''' THEN RAISE EXCEPTION ''''Principal and raw descriptor are required'''' USING ERRCODE=''''23514'''';END IF;\n IF (SELECT count(*) FROM jsonb_object_keys(n->''''principal''''))<>3 OR NOT (n->''''principal'''' ?& ARRAY[''''tenantId'''',''''userId'''',''''apiKeyId'''']) OR (SELECT count(*) FROM jsonb_object_keys(n->''''raw''''))<>3 OR NOT (n->''''raw'''' ?& ARRAY[''''id'''',''''sha256'''',''''byte_count'''']) THEN RAISE EXCEPTION ''''Invalid principal/raw descriptor keys'''' USING ERRCODE=''''23514'''';END IF;\n IF jsonb_typeof(n->''''core'''') IS DISTINCT FROM ''''array'''' OR jsonb_typeof(n->''''events'''') IS DISTINCT FROM ''''array'''' OR jsonb_typeof(n->''''pim'''') IS DISTINCT FROM ''''object'''' OR jsonb_typeof(n->''''approved'''') IS DISTINCT FROM ''''boolean'''' OR jsonb_typeof(n->''''manifest'''') IS DISTINCT FROM ''''object'''' OR jsonb_typeof(n->''''parsing_spec'''') IS DISTINCT FROM ''''object'''' OR (SELECT count(*) FROM jsonb_object_keys(n))<>12 OR EXISTS(SELECT 1 FROM jsonb_object_keys(n) x WHERE x<>ALL(ARRAY[''''schema'''',''''id'''',''''revision'''',''''principal'''',''''raw'''',''''manifest'''',''''parsing_spec'''',''''plan_hash'''',''''approved'''',''''core'''',''''pim'''',''''events''''])) THEN RAISE EXCEPTION ''''Invalid large import state shape'''' USING ERRCODE=''''23514'''';END IF;\n IF TG_OP=''''INSERT'''' THEN IF NEW.revision<>0 OR jsonb_array_length(n->''''events'''')<>0 OR NEW.lease_fence IS DISTINCT FROM 0::bigint OR NEW.lease_token IS NOT NULL OR NEW.leased_at IS NOT NULL THEN RAISE EXCEPTION ''''Large import must start revision zero'''' USING ERRCODE=''''23514'''';END IF;RETURN NEW;END IF;\n -- Every UPDATE requires the genuine current backend to hold the exact app adapter bigint key.\n -- This proves exclusive serialization at this checkpoint, not IAM or session-versus-xact lifetime.\n lock_key:=hashtextextended(''''large-import173:''''||NEW.tenant_id::text||'''':''''||NEW.id::text,0);\n IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks l WHERE l.locktype=''''advisory'''' AND l.pid=pg_backend_pid() AND l.database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database()) AND l.mode=''''ExclusiveLock'''' AND l.granted IS TRUE AND l.objsubid=1 AND l.classid::bigint=((lock_key>>32)&4294967295::bigint) AND l.objid::bigint=(lock_key&4294967295::bigint)) THEN RAISE EXCEPTION ''''Large import checkpoint requires owned advisory lock'''' USING ERRCODE=''''23514'''';END IF;\n IF (NEW.tenant_id,NEW.id,NEW.actor_id,NEW.api_key_id,NEW.plan_hash,NEW.created_at) IS DISTINCT FROM (OLD.tenant_id,OLD.id,OLD.actor_id,OLD.api_key_id,OLD.plan_hash,OLD.created_at) THEN RAISE EXCEPTION ''''Large import plan identity is immutable'''' USING ERRCODE=''''23514'''';END IF;\n IF NEW.state_text=OLD.state_text AND NEW.state_sha256=OLD.state_sha256 AND NEW.revision=OLD.revision THEN\n  IF NOT (NEW.lease_fence=OLD.lease_fence+1 AND NEW.lease_token IS NOT NULL AND NEW.leased_at IS NOT NULL OR NEW.lease_fence=OLD.lease_fence AND NEW.lease_token IS NULL AND NEW.leased_at IS NULL AND OLD.lease_token IS NOT NULL) THEN RAISE EXCEPTION ''''Invalid monotone lease transition'''' USING ERRCODE=''''23514'''';END IF;RETURN NEW;\n END IF;\n IF NEW.lease_token IS DISTINCT FROM OLD.lease_token OR NEW.lease_fence<>OLD.lease_fence OR NEW.lease_token IS NULL OR NEW.revision<>OLD.revision+1 OR public.large_import173_immutable(n) IS DISTINCT FROM public.large_import173_immutable(b) OR (b->>''''approved'''')::boolean AND (n->>''''approved'''')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION ''''Large import CAS/immutable plan differs'''' USING ERRCODE=''''23514'''';END IF;\n IF jsonb_array_length(n->''''events'''')<>jsonb_array_length(b->''''events'''')+1 OR (SELECT coalesce(jsonb_agg(v ORDER BY ord),''''[]''''::jsonb) FROM jsonb_array_elements(n->''''events'''') WITH ORDINALITY x(v,ord) WHERE ord<=jsonb_array_length(b->''''events'''')) IS DISTINCT FROM b->''''events'''' OR (n->''''events''''->-1->>''''sequence'''')::bigint IS DISTINCT FROM jsonb_array_length(b->''''events'''') THEN RAISE EXCEPTION ''''Large import events are append only'''' USING ERRCODE=''''23514'''';END IF;\n FOR i IN 0..jsonb_array_length(b->''''core'''')-1 LOOP FOR k IN SELECT unnest(ARRAY[''''preview'''',''''execution'''',''''consent'''']) LOOP IF b->''''core''''->i ? k AND n->''''core''''->i->k IS DISTINCT FROM b->''''core''''->i->k THEN RAISE EXCEPTION ''''Core receipt is immutable'''' USING ERRCODE=''''23514'''';END IF;END LOOP;END LOOP;\n FOR pimkey,a IN SELECT key,value FROM jsonb_each(b->''''pim'''') LOOP\n  IF jsonb_typeof(n->''''pim''''->pimkey) IS DISTINCT FROM ''''array'''' OR jsonb_array_length(n->''''pim''''->pimkey)<jsonb_array_length(a) THEN RAISE EXCEPTION ''''PIM history was removed'''' USING ERRCODE=''''23514'''';END IF;\n  FOR i IN 0..jsonb_array_length(a)-1 LOOP p:=a->i;c:=n->''''pim''''->pimkey->i;\n   FOR k IN SELECT unnest(ARRAY[''''number'''',''''mapping'''',''''stageKey'''',''''previewKey'''',''''applyKey'''',''''stage'''',''''preview'''',''''consent'''',''''applied'''']) LOOP IF p ? k AND c->k IS DISTINCT FROM p->k THEN RAISE EXCEPTION ''''PIM attempt/receipt is immutable'''' USING ERRCODE=''''23514'''';END IF;END LOOP;\n   IF p->>''''previewAttempted''''=''''true'''' AND c->>''''previewAttempted'''' IS DISTINCT FROM ''''true'''' OR p->>''''applyAttempted''''=''''true'''' AND c->>''''applyAttempted'''' IS DISTINCT FROM ''''true'''' THEN RAISE EXCEPTION ''''PIM uncertainty latch was removed'''' USING ERRCODE=''''23514'''';END IF;\n  END LOOP;\n END LOOP;RETURN NEW;\nEND $function$\n","volatility":"v","body_sha256":"f35ea5172cf827ccf7ba18d8fd99862d3e3aa399aa0c980d72b9075f39157c15","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"sql","parallel":"u","arguments":"","leakproof":false,"signature":"large_import173_metadata()","definition":"CREATE OR REPLACE FUNCTION public.large_import173_metadata()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\n-- Fixed owner SELECT, also used verbatim by startup; it invokes no candidate helper.\n-- Portable semantic identifiers; generated FK trigger allocation names/OIDs are deliberately excluded.\nWITH RECURSIVE own AS (SELECT c.* FROM pg_class c WHERE c.relnamespace=''''public''''::regnamespace\n AND (starts_with(c.relname,''''large_import_'''') OR starts_with(c.relname,''''large_import173_''''))),\n own_functions AS (SELECT p.* FROM pg_proc p WHERE p.pronamespace=''''public''''::regnamespace\n AND (starts_with(p.proname,''''large_import_