a6bf625664c0de6eef19669dce556b4ef7''''),\n  (''''public.warehouse_wz_issuer_guards()'''', ''''4ddf9eddeaf10271fe6d874da8865983512600a7710601811303864e9580a438'''') ) AS required(signature,body_sha256) LOOP\n  SELECT encode(sha256(convert_to(prosrc,''''UTF8'''')),''''hex'''') INTO live_sha\n   FROM pg_proc WHERE oid=to_regprocedure(expected.signature);\n  IF live_sha IS DISTINCT FROM expected.body_sha256 THEN RETURN false;END IF;\n END LOOP;\n IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(public.pim_dictionary_predecessor_metadata()) names(key))\n IS DISTINCT FROM ARRAY[''''allegro_oauth_recovery_guards'''',''''b2b_credit_guards'''',''''b2b_invoice_guards'''',''''buyer_address_guards'''',''''catalog_stock_control_guards'''',''''catalog_stock_count_guards'''',''''catalog_stock_legacy_group_guards'''',''''catalog_stock_return_guards'''',''''competitor_observation_guards'''',''''credit_source_upgrade_valid'''',''''fa3_draft_guards'''',''''financial_return_guards'''',''''financial_return_upgrade_valid'''',''''label_print_guards'''',''''local_invoice_guards'''',''''manual_inventory_off_valid'''',''''operative_delivery_valid'''',''''packed_label_print_guards'''',''''parcel_physical_wz_valid'''',''''print_job_guards'''',''''product_rule_price_tags_guards'''',''''product_rule_schedule_guards'''',''''stocktake_adjustment_guards'''',''''warehouse_automatic_wz_guards'''',''''warehouse_wz_issuer_guards'''']::text[] THEN RETURN false;END IF;\n -- Source-pinned173 PIM copy executes the nested172 certificate checks,\n -- nested172_valid(), then15 super-guards covering all25 current predecessors.\n -- Whole173 profile/predecessor equality remains in large_import173_valid().\n -- Query cancellation has no handler here and propagates as57014.\n RETURN public.large_import173_pim_valid() IS NOT DISTINCT FROM true;\nEND\n$function$\n","volatility":"s","body_sha256":"b430f2035f764dd30e3868fa4a30c4738f7ce9e15c233a173efb5b369ebc1533","returns_set":false,"configuration":["sea