[^0-9]'''' OR length(s)>1 AND left(s,1)=''''0'''' THEN RETURN NULL;END IF;\n IF s::numeric<=4294967294 THEN RETURN s::bigint;END IF;\n RETURN NULL;\nEND $function$\n","volatility":"i","body_sha256":"3eb1ac03b91724a2a228bbbabfb42d13fc5681973ad8a0a4c5faa0b728b4c45c","returns_set":false,"configuration":["search_path=pg_catalog"],"argument_modes":null,"argument_names":["s"],"security_definer":false},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"text","strict":false,"defaults":"0","language":"plpgsql","parallel":"u","arguments":"v jsonb, depth integer","leakproof":false,"signature":"large_import_core_scope173_json(jsonb,integer)","definition":"CREATE OR REPLACE FUNCTION public.large_import_core_scope173_json(v jsonb, depth integer DEFAULT 0)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''''pg_catalog'''', ''''public''''\nAS $function$\nDECLARE kind text:=jsonb_typeof(v); out text;n numeric;\nBEGIN\n IF depth<0 OR depth>8 OR v IS NULL THEN RAISE EXCEPTION ''''Scope canonical JSON depth/SQL-null differs'''' USING ERRCODE=''''23514'''';END IF;\n CASE kind\n WHEN ''''null'''' THEN RETURN ''''null'''';\n WHEN ''''boolean'''' THEN RETURN CASE WHEN v=''''true''''::jsonb THEN ''''true'''' ELSE ''''false'''' END;\n WHEN ''''string'''' THEN RETURN public.large_import_core_scope173_quote(v#>>''''{}'''');\n WHEN ''''number'''' THEN\n  n:=(v#>>''''{}'''')::numeric;\n  IF n<>trunc(n) OR abs(n)>9007199254740991 THEN RAISE EXCEPTION ''''Only actual scope safe integers are serializable'''' USING ERRCODE=''''23514'''';END IF;\n  -- JS JSON.stringify(-0)=0; scale/exponent spellings have no authority. No request/rows number reaches here.\n  RETURN trunc(n)::text;\n WHEN ''''array'''' THEN\n  SELECT ''''[''''||coalesce(string_agg(public.large_import_core_scope173_json(value,depth+1),'''','''' ORDER BY ord),'''''''')||'''']'''' INTO out\n  FROM jsonb_array_elements(v) WITH ORDINALITY x(value,ord);RETURN out;\