) ORDER BY z->>''''resource_key'''' COLLATE \"C\"),''''[]''''::jsonb) INTO wanted FROM jsonb_array_elements(fact->''''resources'''') z;\n IF jsonb_typeof(p) IS DISTINCT FROM ''''object'''' OR (SELECT count(*) FROM jsonb_object_keys(p))<>7 OR p->>''''schema'''' IS DISTINCT FROM ''''private-upload-absent-close/v1''''\n OR p->''''scope'''' IS DISTINCT FROM jsonb_build_object(''''tenantId'''',t,''''actorId'''',u,''''apiKeyId'''',k) OR p->>''''reservation_id'''' IS DISTINCT FROM q::text\n OR p->>''''request_id'''' IS DISTINCT FROM fact->''''reservation''''->>''''request_id'''' OR p->''''resources'''' IS DISTINCT FROM wanted\n OR jsonb_typeof(p->''''fs_cut'''') IS DISTINCT FROM ''''array'''' OR jsonb_array_length(p->''''fs_cut'''')<>6\n OR p->''''fs_cut''''->0->>''''path'''' IS DISTINCT FROM ''''.'''' OR p->''''fs_cut''''->0->>''''state'''' IS DISTINCT FROM ''''present''''\n OR p->''''fs_cut''''->0->>''''kind'''' IS DISTINCT FROM ''''directory'''' OR p->''''fs_cut''''->0->>''''mode'''' IS DISTINCT FROM ''''448''''\n OR p->''''metadata_cut'''' IS DISTINCT FROM jsonb_build_object(''''blobs'''',0,''''jobs'''',0,''''reviews'''',0) THEN RAISE EXCEPTION ''''Absent reconciliation full original proof mismatch'''' USING ERRCODE=''''23514'''';END IF;\n FOR path0 IN SELECT value FROM jsonb_array_elements(fact->''''expected_paths'''') LOOP\n  IF (SELECT count(*) FROM jsonb_array_elements(p->''''fs_cut'''') z WHERE z=jsonb_build_object(''''path'''',path0,''''state'''',''''absent''''))<>1 THEN RAISE EXCEPTION ''''Absent reconciliation missing exact absent path'''' USING ERRCODE=''''23514'''';END IF;\n END LOOP;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q;\n inventory0:=encode(sha256(convert_to(proof0,''''UTF8'''')),''''hex'''');receipt0:=jsonb_build_object(''''schema'''',''''quota-absent-close-receipt/v1'''',''''client_key'''',client0,''''tenant_id'''',t,''''reservation_id'''',q,''''request_id'''',b.request_id,''''inventory_sha256'''',inventory0,''''released_directory_count'''',5,''''native_time'''',clock_timestamp());\n evidence0:=jsonb_build_object(''''schema'''',''''quota-absent-close-evidence/v1'''',''''inventory_text'''',proof0,''''receipt'''',receipt0)::text;key0:=''''event:upload-absent-close:''''||client0::text;\n -- One retained metadata resource stores the immutable original cut and receipt. Original five byte counts/hashes/payloads never change.\n IF 2::numeric*octet_length(evidence0)>b.metadata_ceiling OR 2>b.objects_ceiling THEN RAISE EXCEPTION ''''Absent reconciliation evidence exceeds original ceiling'''' USING ERRCODE=''''54000'''';END IF;\n INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,''''event'''',octet_length(evidence0),encode(sha256(convert_to(evidence0,''''UTF8'''')),''''hex''''),''''settled'''',evidence0);\n UPDATE public.large_import_quota_resources173 SET state=''''released'''' WHERE tenant_id=t AND reservation_id=q AND resource_key<>key0;\n UPDATE public.large_import_quota_reservations173 SET state=''''retained'''',outcome=''''absent'''',raw_charge=0,metadata_charge=2::numeric*octet_length(evidence0),objects_charge=2,closed_at=clock_timestamp(),inventory_sha256=inventory0 WHERE tenant_id=t AND id=q RETURNING * INTO b;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n RETURN jsonb_build_object(''''reused'''',false,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''receipt'''',receipt0);\nEND $function$\n","volatility":"v","body_sha256":"17c0a9533798c88fc530667c699bb9743d2eef49bdec5aa777ed85047b462eb0","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","client0","proof0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text","leakproof":false,"signature":"large_import_quota_authorize173(uuid,uuid,uuid,text,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_authorize173(u uuid, t uuid, k uuid, r text, h text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE policy_count integer;\nBEGIN\n -- VOLATILE SPI queries need fresh statement snapshots after the global advisory wait.\n -- RR/serializable snapshots established by prior IAM reads cannot safely sum cross-tenant allocations.\n IF current_setting(''''transaction_isolation'''') IS DISTINCT FROM ''''read committed'''' THEN\n  RAISE EXCEPTION ''''Quota writes require READ COMMITTED'''' USING ERRCODE=''''25000'''';\n END IF;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\n -- Every allocation/final settlement uses this identical global -> tenant order, including cross-tenant calls.\n PERFORM pg_advisory_xact_lock(hashtextextended(''''large-import173:quota:global'''',0));\n PERFORM pg_advisory_xact_lock(hashtextextended(''''large-import173:quota:tenant:''''||t::text,0));\n PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN(''''global'''',''''tenant:''''||t::text) ORDER BY scope FOR SHARE;\n GET DIAGNOSTICS policy_count=ROW_COUNT;\n IF policy_count<>2 THEN\n  RAISE EXCEPTION ''''Quota inventory/policy unavailable'''' USING ERRCODE=''''55000'''';\n END IF;\nEND $function$\n","volatility":"v","body_sha256":"60aa87e2205075621dedfbbcabad7a57cc265181dc0dcb56f10bffc7d2f2fbd0","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, outcome0 text, inventory text, keys0 text[]","leakproof":false,"signature":"large_import_quota_close173(uuid,uuid,uuid,text,text,uuid,text,text,text,text[])","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_close173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, outcome0 text, inventory text, keys0 text[])\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;x record;actual_keys text[];\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF token IS NULL OR outcome0 IS NULL OR outcome0 NOT IN(''''ready'''',''''quarantined'''',''''unknown'''') THEN RAISE EXCEPTION ''''Quota close shape'''' USING ERRCODE=''''22023'''';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND THEN RAISE EXCEPTION ''''Quota close not owned'''' USING ERRCODE=''''42501'''';END IF;\n IF outcome0=''''unknown'''' THEN\n  IF b.state=''''retained'''' THEN RETURN to_jsonb(b)-''''token_hash'''';END IF;\n  UPDATE public.large_import_quota_reservations173 SET state=''''unknown'''' WHERE tenant_id=t AND id=q RETURNING * INTO b;RETURN to_jsonb(b)-''''token_hash''''; -- Ceiling never released by expiry, revocation, uncertain commit, pending file or unknown ACK.\n END IF;\n IF inventory IS NULL OR inventory !~ ''''^[a-f0-9]{64}$'''' OR keys0 IS NULL OR array_position(keys0,NULL) IS NOT NULL THEN RAISE EXCEPTION ''''Complete private inventory required'''' USING ERRCODE=''''22023'''';END IF;\n SELECT coalesce(array_agg(resource_key ORDER BY resource_key COLLATE \"C\"),ARRAY[]::text[]) INTO actual_keys FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n -- Use a second explicit aggregate record; do not rely on row/text aliases or nullable checks.\n SELECT coalesce(sum(byte_count) FILTER(WHERE kind=''''raw'''' AND state<>''''released''''),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>''''raw'''' AND state<>''''released''''),0) metadata_used,coalesce(sum(CASE WHEN state=''''released'''' THEN 0 WHEN kind=''''raw'''' THEN 1 ELSE 2 END),0) objects_used,count(*) FILTER(WHERE state=''''intent'''') pending INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n IF actual_keys IS DISTINCT FROM keys0 OR x.pending<>0 THEN RAISE EXCEPTION ''''Quota incomplete resource inventory'''' USING ERRCODE=''''23514'''';END IF;\n IF b.state=''''retained'''' THEN\n  IF b.outcome IS DISTINCT FROM outcome0 OR b.inventory_sha256 IS DISTINCT FROM inventory OR b.raw_charge IS DISTINCT FROM x.raw_used OR b.metadata_charge IS DISTINCT FROM x.metadata_used OR b.objects_charge IS DISTINCT FROM x.objects_used THEN RAISE EXCEPTION ''''Quota close replay conflict'''' USING ERRCODE=''''23505'''';END IF;RETURN to_jsonb(b)-''''token_hash'''';\n END IF;\n UPDATE public.large_import_quota_reservations173 SET state=''''retained'''',outcome=outcome0,raw_charge=x.raw_used,metadata_charge=x.metadata_used,objects_charge=x.objects_used,closed_at=clock_timestamp(),inventory_sha256=inventory WHERE tenant_id=t AND id=q RETURNING * INTO b;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);RETURN to_jsonb(b)-''''token_hash'''';\nEND $function$\n","volatility":"v","body_sha256":"72d28007ca59c21d93728ac0a9608f2e3767af3d5b1432064f5876fe8da5387b","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","outcome0","inventory","keys0"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, kind0 text, n bigint, sha text, payload text","leakproof":false,"signature":"large_import_quota_intent173(uuid,uuid,uuid,text,text,uuid,text,text,text,bigint,text,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_intent173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, kind0 text, n bigint, sha text, payload text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;old record;x record;\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF token IS NULL OR key0 IS NULL OR length(key0) NOT BETWEEN 1 AND 200 OR kind0 IS NULL OR kind0 NOT IN(''''raw'''',''''blob'''',''''batch'''',''''job'''',''''review'''',''''event'''') OR key0 !~ ''''^(raw|blob|batch|job|review|event):[a-z0-9:-]{1,160}$'''' OR split_part(key0,'''':'''',1) IS DISTINCT FROM kind0 OR n IS NULL OR n<0 OR sha IS NULL OR sha !~ ''''^[a-f0-9]{64}$'''' THEN RAISE EXCEPTION ''''Quota intent shape'''' USING ERRCODE=''''22023'''';END IF;\n IF (kind0=''''raw'''' AND payload IS NOT NULL) OR (kind0<>''''raw'''' AND (payload IS NULL OR octet_length(payload) IS DISTINCT FROM n OR encode(sha256(convert_to(payload,''''UTF8'''')),''''hex'''') IS DISTINCT FROM sha)) THEN RAISE EXCEPTION ''''Quota exact metadata payload bytes'''' USING ERRCODE=''''23514'''';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND THEN RAISE EXCEPTION ''''Quota reservation not owned'''' USING ERRCODE=''''42501'''';END IF;\n SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n IF FOUND THEN\n  IF old.kind IS DISTINCT FROM kind0 OR old.byte_count IS DISTINCT FROM n OR old.sha256 IS DISTINCT FROM sha OR old.payload_text IS DISTINCT FROM payload THEN RAISE EXCEPTION ''''Quota resource replay conflict'''' USING ERRCODE=''''23505'''';END IF;\n  IF old.state=''''released'''' THEN RAISE EXCEPTION ''''Terminal allocation cannot authorize publication'''' USING ERRCODE=''''23505'''';END IF;\n  IF old.state=''''settled'''' OR old.state=''''quarantined'''' THEN RETURN to_jsonb(old)-''''token_hash'''';END IF;\n  RAISE EXCEPTION ''''Pending resource requires inspection, not duplicate write'''' USING ERRCODE=''''40001'''';\n END IF;\n IF b.state IS DISTINCT FROM ''''open'''' OR b.expires_at<=clock_timestamp() THEN RAISE EXCEPTION ''''Quota lease expired; retained allocation requires reconciliation'''' USING ERRCODE=''''40001'''';END IF;\n SELECT coalesce(sum(byte_count) FILTER(WHERE kind=''''raw'''' AND state<>''''released''''),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>''''raw'''' AND state<>''''released''''),0) metadata_used,coalesce(sum(CASE WHEN state=''''released'''' THEN 0 WHEN kind=''''raw'''' THEN 1 ELSE 2 END),0) objects_used INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n IF x.raw_used+(CASE WHEN kind0=''''raw'''' THEN n ELSE 0 END)>b.raw_ceiling OR x.metadata_used+(CASE WHEN kind0<>''''raw'''' THEN n*2::numeric ELSE 0 END)>b.metadata_ceiling OR x.objects_used+(CASE WHEN kind0=''''raw'''' THEN 1 ELSE 2 END)>b.objects_ceiling THEN RAISE EXCEPTION ''''Quota resource ceiling exhausted'''' USING ERRCODE=''''54000'''';END IF;\n INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,kind0,n,sha,''''intent'''',payload) RETURNING * INTO old;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);RETURN to_jsonb(old)-''''token_hash'''';\nEND $function$\n","volatility":"v","body_sha256":"c54a395fbf83109e340eb7a195a6d7d856c5ecb88c264736d2dea3c48dc03311","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","kind0","n","sha","payload"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb","leakproof":false,"signature":"large_import_quota_intent_many173(uuid,uuid,uuid,text,text,uuid,text,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_intent_many173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;old record;x record;v jsonb;key0 text;kind0 text;n bigint;sha text;payload text;seen text[]:=ARRAY[]::text[];result jsonb:=''''[]''''::jsonb;new_raw numeric:=0;new_metadata numeric:=0;new_objects numeric:=0;new_count integer:=0;\nBEGIN\n -- Same existing READ COMMITTED/full currentIAM/global -> tenant -> policy order.\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF q IS NULL OR token IS NULL OR token !~ ''''^[a-f0-9]{64}$'''' OR items IS NULL OR jsonb_typeof(items) IS DISTINCT FROM ''''array'''' THEN RAISE EXCEPTION ''''Quota group shape'''' USING ERRCODE=''''22023'''';END IF;\n IF jsonb_array_length(items) NOT BETWEEN 1 AND 64 OR octet_length(items::text)>8388608 THEN RAISE EXCEPTION ''''Quota group bound'''' USING ERRCODE=''''22023'''';END IF;\n -- Validate ALL shapes before reservation/resource mutation. Text payload is compared exactly,\n -- never JSON-projected or normalized; caller bytes/hash include original UTF8 serialization.\n FOR v IN SELECT value FROM jsonb_array_elements(items) LOOP\n  IF jsonb_typeof(v) IS DISTINCT FROM ''''object'''' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v) key) IS DISTINCT FROM ARRAY[''''byte_count'''',''''key'''',''''kind'''',''''payload_text'''',''''sha256'''']::text[] OR jsonb_typeof(v->''''key'''') IS DISTINCT FROM ''''string'''' OR jsonb_typeof(v->''''kind'''') IS DISTINCT FROM ''''string'''' OR jsonb_typeof(v->''''sha256'''') IS DISTINCT FROM ''''string'''' OR jsonb_typeof(v->''''byte_count'''') IS DISTINCT FROM ''''number'''' OR (v->>''''byte_count'''') !~ ''''^(0|[1-9][0-9]{0,15})$'''' THEN RAISE EXCEPTION ''''Quota group item shape'''' USING ERRCODE=''''22023'''';END IF;\n  key0:=v->>''''key'''';kind0:=v->>''''kind'''';n:=(v->>''''byte_count'''')::bigint;sha:=v->>''''sha256'''';payload:=v->>''''payload_text'''';\n  IF key0 !~ ''''^(raw|blob|batch|job|review|event):[a-z0-9:-]{1,160}$'''' OR kind0 NOT IN(''''raw'''',''''blob'''',''''batch'''',''''job'''',''''review'''',''''event'''') OR split_part(key0,'''':'''',1) IS DISTINCT FROM kind0 OR sha !~ ''''^[a-f0-9]{64}$'''' OR n>9007199254740991 OR key0=ANY(seen) THEN RAISE EXCEPTION ''''Quota group item identity'''' USING ERRCODE=''''22023'''';END IF;\n  IF (kind0=''''raw'''' AND jsonb_typeof(v->''''payload_text'''') IS DISTINCT FROM ''''null'''') OR (kind0<>''''raw'''' AND (jsonb_typeof(v->''''payload_text'''') IS DISTINCT FROM ''''string'''' OR octet_length(payload) IS DISTINCT FROM n OR encode(sha256(convert_to(payload,''''UTF8'''')),''''hex'''') IS DISTINCT FROM sha)) THEN RAISE EXCEPTION ''''Quota group exact payload'''' USING ERRCODE=''''23514'''';END IF;\n  seen:=array_append(seen,key0);\n END LOOP;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND THEN RAISE EXCEPTION ''''Quota group reservation not owned'''' USING ERRCODE=''''42501'''';END IF;\n -- Lock complete existing group in C byte order before any insertion. Reservation UPDATE also\n -- fences competing inserts under the unchanged native global lock protocol.\n PERFORM 1 FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=ANY(seen) ORDER BY resource_key COLLATE \"C\" FOR UPDATE;\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''''key'''') COLLATE \"C\" LOOP\n  key0:=v->>''''key'''';kind0:=v->>''''kind'''';n:=(v->>''''byte_count'''')::bigint;sha:=v->>''''sha256'''';payload:=v->>''''payload_text'''';\n  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n  IF FOUND THEN\n   IF old.kind IS DISTINCT FROM kind0 OR old.byte_count IS DISTINCT FROM n OR old.sha256 IS DISTINCT FROM sha OR old.payload_text IS DISTINCT FROM payload THEN RAISE EXCEPTION ''''Quota group replay conflict'''' USING ERRCODE=''''23505'''';END IF;\n   IF old.state=''''released'''' THEN RAISE EXCEPTION ''''Terminal allocation cannot authorize publication'''' USING ERRCODE=''''23505'''';END IF;\n   IF old.state NOT IN(''''settled'''',''''quarantined'''') THEN RAISE EXCEPTION ''''Pending resource requires inspection'''' USING ERRCODE=''''40001'''';END IF;\n  ELSE\n   IF b.state IS DISTINCT FROM ''''open'''' OR b.expires_at<=clock_timestamp() THEN RAISE EXCEPTION ''''Quota group lease unavailable'''' USING ERRCODE=''''40001'''';END IF;\n   new_count:=new_count+1;new_raw:=new_raw+(CASE WHEN kind0=''''raw'''' THEN n ELSE 0 END);new_metadata:=new_metadata+(CASE WHEN kind0<>''''raw'''' THEN n*2::numeric ELSE 0 END);new_objects:=new_objects+(CASE WHEN kind0=''''raw'''' THEN 1 ELSE 2 END);\n  END IF;\n END LOOP;\n IF new_count>0 THEN\n SELECT coalesce(sum(byte_count) FILTER(WHERE kind=''''raw'''' AND state<>''''released''''),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>''''raw'''' AND state<>''''released''''),0) metadata_used,coalesce(sum(CASE WHEN state=''''released'''' THEN 0 WHEN kind=''''raw'''' THEN 1 ELSE 2 END),0) objects_used INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n IF x.raw_used+new_raw>b.raw_ceiling OR x.metadata_used+new_metadata>b.metadata_ceiling OR x.objects_used+new_objects>b.objects_ceiling THEN RAISE EXCEPTION ''''Quota group ceiling exhausted'''' USING ERRCODE=''''54000'''';END IF;\n END IF;\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''''key'''') COLLATE \"C\" LOOP\n  key0:=v->>''''key'''';SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n  IF NOT FOUND THEN INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,v->>''''kind'''',(v->>''''byte_count'''')::bigint,v->>''''sha256'''',''''intent'''',v->>''''payload_text'''') RETURNING * INTO old;END IF;\n  result:=result||jsonb_build_array(to_jsonb(old));\n END LOOP;\n -- No saved verdict: complete graph + locked currentIAM again, after group effects. An elapsed\n -- new-write deadline rolls back the entire group. Exact settled replay never extends expiry.\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\n IF new_count>0 AND b.expires_at<=clock_timestamp() THEN RAISE EXCEPTION ''''Quota group deadline elapsed'''' USING ERRCODE=''''40001'''';END IF;\n RETURN result;\nEND $function$\n","volatility":"v","body_sha256":"06ef881ab76d92494cc45b7340d1031f458810e6d02c822a24f418f2ad93b5d8","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","items"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, w boolean","leakproof":false,"signature":"large_import_quota_keeper_admit173(uuid,uuid,uuid,text,text,boolean)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_keeper_admit173(u uuid, t uuid, k uuid, r text, h text, w boolean)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE x record;v_now timestamptz;\nBEGIN\n IF u IS NULL OR t IS NULL OR r IS NULL OR r NOT IN(''''admin'''',''''operator'''',''''viewer'''') OR h IS NULL OR h !~ ''''^[a-f0-9]{64}$'''' OR w IS NULL THEN\n  RAISE EXCEPTION ''''Invalid metadata authority'''' USING ERRCODE=''''42501'''';\n END IF;\n -- SD current_user is the module owner. The caller is a fresh, private dedicated owner keeper connection with role NONE; no role reset.\n IF current_setting(''''role'''',true) IS DISTINCT FROM ''''none''''\n OR session_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=to_regclass(''''public.large_import173_certificate'''')))\n OR t IS DISTINCT FROM nullif(current_setting(''''app.tenant_id'''',true),'''''''')::uuid THEN\n  RAISE EXCEPTION ''''Private keeper owner-role tenant transport mismatch'''' USING ERRCODE=''''42501'''';\n END IF;\n -- Owner startup MUST independently pin the complete current body/catalog graph before invoking the private keeper ABI.\n -- This leaf check alone is not self-attestation. The new helper+grant must be in that compiled certificate graph.\n IF public.large_import173_valid() IS DISTINCT FROM true THEN\n  RAISE EXCEPTION ''''Metadata173 is not certified'''' USING ERRCODE=''''55000'''';\n END IF;\n -- Same order as native170 pin path; independent authority, without its lifecycle.\n -- Actual metadata checkpoint caller must be inside BEGIN; locks then survive through its COMMIT/ROLLBACK.\n PERFORM 1 FROM public.users WHERE id=u FOR SHARE;\n PERFORM 1 FROM public.tenants WHERE id=t FOR SHARE;\n PERFORM 1 FROM public.account_security WHERE user_id=u FOR SHARE;\n PERFORM 1 FROM public.workspace_security_policies WHERE tenant_id=t FOR SHARE;\n PERFORM 1 FROM public.memberships WHERE(user_id,tenant_id)=(u,t) FOR SHARE;\n IF k IS NULL THEN\n  PERFORM 1 FROM public.sessions WHERE(token_hash,user_id,tenant_id)=(h,u,t) FOR SHARE;\n ELSE\n  PERFORM 1 FROM public.api_keys WHERE(id,user_id,tenant_id)=(k,u,t) FOR SHARE;\n END IF;\n v_now:=clock_timestamp();\n IF k IS NULL THEN\n  SELECT m.role,coalesce(a.version,0)::text account_version,true scope_ok,\n   least(s.expires_at,CASE WHEN coalesce(p.require_mfa,false) THEN s.mfa_verified_at+interval ''''8 hours'''' ELSE s.expires_at END) deadline,\n   coalesce(p.require_mfa,false) AND NOT(coalesce(a.enabled_at IS NOT NULL AND s.mfa_verified_at IS NOT NULL AND s.mfa_verified_at>v_now-interval ''''8 hours'''',false)) mfa_required INTO x\n  FROM public.sessions s JOIN public.users z ON z.id=s.user_id JOIN public.tenants n ON n.id=s.tenant_id\n  JOIN public.memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)\n  LEFT JOIN public.account_security a ON a.user_id=z.id LEFT JOIN public.workspace_security_policies p ON p.tenant_id=n.id\n  WHERE(s.token_hash,s.user_id,s.tenant_id)=(h,u,t) AND s.expires_at>v_now AND s.account_version=coalesce(a.version,0);\n ELSE\n  SELECT m.role,coalesce(a.version,0)::text account_version,k0.expires_at deadline,\n   k0.scopes@>CASE WHEN w THEN ARRAY[''''products:read'''',''''products:write'''']::text[] ELSE ARRAY[''''products:read'''']::text[] END scope_ok,\n   coalesce(p.require_mfa,false) AND a.enabled_at IS NULL mfa_required INTO x\n  FROM public.api_keys k0 JOIN public.users z ON z.id=k0.user_id JOIN public.tenants n ON n.id=k0.tenant_id\n  JOIN public.memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)\n  LEFT JOIN public.account_security a ON a.user_id=z.id LEFT JOIN public.workspace_security_policies p ON p.tenant_id=n.id\n  WHERE(k0.id,k0.token_hash,k0.user_id,k0.tenant_id)=(k,h,u,t) AND k0.revoked_at IS NULL AND k0.expires_at>v_now;\n END IF;\n IF x.role IS NULL OR x.deadline IS NULL OR NOT isfinite(x.deadline) OR x.deadline<=clock_timestamp() THEN\n  RAISE EXCEPTION ''''Expired metadata authority'''' USING ERRCODE=''''28000'''';\n END IF;\n IF x.role<>r THEN RAISE EXCEPTION ''''Metadata role changed'''' USING ERRCODE=''''40001'''';END IF;\n IF NOT coalesce(x.scope_ok,false) OR coalesce(x.mfa_required,true) OR(w AND x.role<>''''admin'''') THEN\n  RAISE EXCEPTION ''''Missing current metadata authority'''' USING ERRCODE=''''42501'''';\n END IF;\nEND\n$function$\n","volatility":"v","body_sha256":"734ce613962ab35ec98bf714b152a959e5f2aa2fb2baf0191720d52de6b7a27b","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","w"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, q uuid, token text, key0 text, n bigint, sha text","leakproof":false,"signature":"large_import_quota_lock_cleanup_pin173(uuid,uuid,uuid,uuid,text,text,bigint,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_lock_cleanup_pin173(u uuid, t uuid, k uuid, q uuid, token text, key0 text, n bigint, sha text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;x record;\nBEGIN\n IF current_setting(''''role'''',true) IS DISTINCT FROM ''''dyna_app'''' OR current_setting(''''app.tenant_id'''',true) IS DISTINCT FROM t::text\n OR session_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=''''public.large_import173_certificate''''::regclass))\n OR public.large_import173_valid() IS DISTINCT FROM true THEN RAISE EXCEPTION ''''Cleanup requires certified owned app transport'''' USING ERRCODE=''''42501'''';END IF;\n -- No global/tenant quota locks: caller already committed intents; no new capacity or receipt allocation occurs here.\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR SHARE;\n IF NOT FOUND OR b.kind IS DISTINCT FROM ''''upload'''' OR b.state=''''retained'''' THEN RAISE EXCEPTION ''''Cleanup reservation not active/owned'''' USING ERRCODE=''''42501'''';END IF;\n SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0 FOR SHARE;\n IF NOT FOUND OR x.kind IS DISTINCT FROM ''''blob'''' OR x.state=''''released'''' OR x.byte_count IS DISTINCT FROM n OR x.sha256 IS DISTINCT FROM sha\n OR key0 !~ ''''^blob:fs:(blobs|uploads|witnesses):[a-f0-9-]{36}:lock:[a-f0-9-]{36}$''''\n OR (x.payload_text::jsonb->>''''schema'''') IS DISTINCT FROM ''''private-import-lock/v1''''\n OR (x.payload_text::jsonb->>''''id'''') IS DISTINCT FROM split_part(key0,'''':'''',6)\n OR (SELECT count(*) FROM jsonb_object_keys(x.payload_text::jsonb))<>2 THEN\n RAISE EXCEPTION ''''Cleanup only permits original exact transient lock'''' USING ERRCODE=''''42501'''';END IF;\nEND $function$\n","volatility":"v","body_sha256":"a791212d48162da3cb71f1d67db5f4f38252bcf03dc73570d4bf532a45afbe1d","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","q","token","key0","n","sha"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid","leakproof":false,"signature":"large_import_quota_owned_close_begin173(uuid,uuid,uuid,text,text,uuid,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_owned_close_begin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;policy_count integer;old record;snapshot0 jsonb;\nBEGIN\n IF current_setting(''''transaction_isolation'''') IS DISTINCT FROM ''''read committed'''' THEN RAISE EXCEPTION ''''Terminal writes require READ COMMITTED'''' USING ERRCODE=''''25000'''';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n PERFORM pg_advisory_xact_lock(hashtextextended(''''large-import173:quota:global'''',0));PERFORM pg_advisory_xact_lock(hashtextextended(''''large-import173:quota:tenant:''''||t::text,0));\n PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN(''''global'''',''''tenant:''''||t::text) ORDER BY scope FOR SHARE;GET DIAGNOSTICS policy_count=ROW_COUNT;\n IF policy_count<>2 THEN RAISE EXCEPTION ''''Terminal quota policy absent'''' USING ERRCODE=''''55000'''';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.kind NOT IN(''''job'''',''''review'''') OR client0 IS NULL THEN RAISE EXCEPTION ''''Known-close business request not owned'''' USING ERRCODE=''''42501'''';END IF;\n IF b.state=''''retained'''' THEN\n  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=''''event:business-known-close:''''||client0::text AND state=''''settled'''';\n  IF NOT FOUND OR b.outcome<>''''ready'''' OR old.payload_text::jsonb->''''receipt''''->>''''client_key'''' IS DISTINCT FROM client0::text THEN RAISE EXCEPTION ''''Known-close original key conflict'''' USING ERRCODE=''''23505'''';END IF;\n  RETURN jsonb_build_object(''''reused'''',true,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''receipt'''',old.payload_text::jsonb->''''receipt''''); -- no fresh cut or callback on exact old-key recovery\n END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE \"C\"),''''[]''''::jsonb) INTO snapshot0 FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;\n IF jsonb_array_length(snapshot0)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot0) x WHERE x->>''''state'''' NOT IN(''''settled'''',''''released'''')) THEN RAISE EXCEPTION ''''Known close has pending original allocations'''' USING ERRCODE=''''40001'''';END IF;\n RETURN jsonb_build_object(''''reused'''',false,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''resources'''',snapshot0);\nEND $function$\n","volatility":"v","body_sha256":"d7dd88adb51e571a8e124bec7e5dae9f7e6bdef6796eafc326e7f70f65ce0948","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","client0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text","leakproof":false,"signature":"large_import_quota_owned_close_finish173(uuid,uuid,uuid,text,text,uuid,text,uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_owned_close_finish173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE fact jsonb;p jsonb;wanted jsonb;b record;job0 record;actual0 jsonb;charges record;receipt0 jsonb;evidence0 text;key0 text;inventory0 text;\nBEGIN\n fact:=public.large_import_quota_owned_close_begin173(u,t,k,r,h,q,token,client0);IF fact->''''reused''''=''''true''''::jsonb THEN RETURN fact;END IF;\n IF proof0 IS NULL OR octet_length(proof0)>8388608 THEN RAISE EXCEPTION ''''Known-close bounded private proof required'''' USING ERRCODE=''''22023'''';END IF;\n p:=proof0::jsonb;\n SELECT coalesce(jsonb_agg(jsonb_build_object(''''resource_key'''',z->>''''resource_key'''',''''kind'''',z->>''''kind'''',''''byte_count'''',z->''''byte_count'''',''''sha256'''',z->>''''sha256'''',''''state'''',z->>''''state'''') ORDER BY z->>''''resource_key'''' COLLATE \"C\"),''''[]''''::jsonb) INTO wanted FROM jsonb_array_elements(fact->''''resources'''') z;\n IF jsonb_typeof(p) IS DISTINCT FROM ''''object'''' OR (SELECT count(*) FROM jsonb_object_keys(p))<>9 OR p->>''''schema'''' IS DISTINCT FROM ''''private-business-known-close/v1''''\n OR p->''''scope'''' IS DISTINCT FROM jsonb_build_object(''''tenantId'''',t,''''actorId'''',u,''''apiKeyId'''',k) OR p->>''''reservation_id'''' IS DISTINCT FROM q::text\n OR p->>''''request_id'''' IS DISTINCT FROM fact->''''reservation''''->>''''request_id'''' OR p->''''resources'''' IS DISTINCT FROM wanted\n OR p->>''''kind'''' IS DISTINCT FROM fact->''''reservation''''->>''''kind'''' OR jsonb_typeof(p->''''fs_cut'''') IS DISTINCT FROM ''''array''''\n OR jsonb_typeof(p->''''metadata_cut'''') IS DISTINCT FROM ''''object'''' THEN RAISE EXCEPTION ''''Known-close full original inventory mismatch'''' USING ERRCODE=''''23514'''';END IF;\n IF EXISTS(SELECT 1 FROM public.large_import_quota_resources173 z WHERE z.tenant_id=t AND z.reservation_id=q AND z.state=''''released'''' AND NOT EXISTS(SELECT 1 FROM public.large_import_quota_terminal_receipts173 e WHERE(e.tenant_id,e.reservation_id,e.resource_key)=(z.tenant_id,z.reservation_id,z.resource_key))) THEN RAISE EXCEPTION ''''Released allocation lacks immutable native receipt'''' USING ERRCODE=''''23514'''';END IF;\n SELECT * INTO job0 FROM public.large_import_jobs173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND id=(p->>''''job_id'''')::uuid FOR SHARE;\n IF NOT FOUND OR job0.lease_token IS NOT NULL OR job0.leased_at IS NOT NULL THEN RAISE EXCEPTION ''''Business job is not owned/quiescent'''' USING ERRCODE=''''40001'''';END IF;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(job0.state_text::jsonb->''''core'''') batch WHERE jsonb_typeof(batch->''''execution'''') IS DISTINCT FROM ''''object'''')\n OR EXISTS(SELECT 1 FROM jsonb_each(job0.state_text::jsonb->''''pim'''') group0 CROSS JOIN LATERAL jsonb_array_elements(group0.value) attempt WHERE ((attempt->>''''applyAttempted'''')::boolean AND jsonb_typeof(attempt->''''applied'''') IS DISTINCT FROM ''''object'''') OR ((attempt->>''''previewAttempted'''')::boolean AND jsonb_typeof(attempt->''''preview'''') IS DISTINCT FROM ''''object''''))\n THEN RAISE EXCEPTION ''''Unresolved original business outcome'''' USING ERRCODE=''''40001'''';END IF;\n PERFORM 1 FROM public.large_import_events173 WHERE tenant_id=t AND job_id=job0.id ORDER BY sequence FOR SHARE;\n PERFORM 1 FROM public.large_import_core_reviews173 WHERE tenant_id=t AND job_id=job0.id ORDER BY revision FOR SHARE;\n SELECT jsonb_build_object(''''job'''',jsonb_build_object(''''state_text'''',job0.state_text,''''state_sha256'''',job0.state_sha256,''''revision'''',job0.revision,''''lease_fence'''',job0.lease_fence::text,''''lease_token'''',job0.lease_token,''''leased_at'''',job0.leased_at),\n ''''events'''',(SELECT coalesce(jsonb_agg(jsonb_build_object(''''sequence'''',e.sequence,''''revision'''',e.revision,''''event_text'''',e.event_text,''''event_sha256'''',e.event_sha256) ORDER BY e.sequence),''''[]''''::jsonb) FROM public.large_import_events173 e WHERE e.tenant_id=t AND e.job_id=job0.id),\n ''''reviews'''',(SELECT coalesce(jsonb_agg(jsonb_build_object(''''revision'''',v.revision,''''review_text'''',v.review_text,''''review_sha256'''',v.review_sha256,''''job_revision'''',v.job_revision,''''lease_fence'''',v.lease_fence::text,''''scope_text'''',v.scope_text,''''request_texts'''',v.request_texts,''''row_texts'''',v.row_texts) ORDER