n is not an owned witness lock'''' USING ERRCODE=''''22023'''';END IF;\n RETURN jsonb_build_object(''''reused'''',false,''''classification'''',classification,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''resource'''',to_jsonb(x));\nEND $function$\n","volatility":"v","body_sha256":"529eeacc46303fb9fc5b1bcedc6c9128290941b3b032fab6777c2364b2fa2e73","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","client0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid, witness0 text, classification0 text","leakproof":false,"signature":"large_import_quota_owned_release_finish173(uuid,uuid,uuid,text,text,uuid,text,text,uuid,text,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_owned_release_finish173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid, witness0 text, classification0 text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE fact jsonb;b record;x record;blob0 record;w jsonb;receipt0 text;wkey text;rkey text;charges record;extra_metadata numeric;extra_objects bigint:=4;\nBEGIN\n fact:=public.large_import_quota_owned_release_begin173(u,t,k,r,h,q,token,key0,client0);\n IF fact->''''reused''''=''''true''''::jsonb THEN RETURN fact;END IF;\n IF classification0 IS DISTINCT FROM fact->>''''classification'''' OR witness0 IS NULL OR octet_length(witness0)>8388608 THEN RAISE EXCEPTION ''''Terminal witness shape'''' USING ERRCODE=''''22023'''';END IF;\n w:=witness0::jsonb;\n IF jsonb_typeof(w) IS DISTINCT FROM ''''object'''' OR (SELECT count(*) FROM jsonb_object_keys(w))<>10 OR w->>''''schema'''' IS DISTINCT FROM ''''private-business-lock-terminal-witness/v1''''\n OR w->''''scope'''' IS DISTINCT FROM jsonb_build_object(''''tenantId'''',t,''''actorId'''',u,''''apiKeyId'''',k)\n OR w->>''''reservation_id'''' IS DISTINCT FROM q::text OR w->>''''resource_key'''' IS DISTINCT FROM key0 OR w->>''''classification'''' IS DISTINCT FROM classification0\n OR jsonb_typeof(w->''''fs_cut'''') IS DISTINCT FROM ''''array'''' OR jsonb_array_length(w->''''fs_cut'''')<1 THEN RAISE EXCEPTION ''''Terminal witness full binding'''' USING ERRCODE=''''23514'''';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q;\n SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n IF w->>''''request_id'''' IS DISTINCT FROM b.request_id::text OR w->>''''original_sha256'''' IS DISTINCT FROM x.sha256 OR w->>''''byte_count'''' IS DISTINCT FROM x.byte_count::text THEN RAISE EXCEPTION ''''Terminal original allocation changed'''' USING ERRCODE=''''23514'''';END IF;\n IF w->>''''kind'''' IS DISTINCT FROM b.kind OR classification0 IS DISTINCT FROM ''''released-lock'''' THEN RAISE EXCEPTION ''''Business witness reservation mismatch'''' USING ERRCODE=''''23514'''';END IF;\n IF classification0=''''released-lock'''' AND x.payload_text::jsonb IS DISTINCT FROM jsonb_build_object(''''schema'''',''''private-import-lock/v1'''',''''id'''',split_part(key0,'''':'''',6)::uuid) THEN RAISE EXCEPTION ''''Released lock context mismatch'''' USING ERRCODE=''''23514'''';END IF;\n -- Keep old count/hash/payload immutable. A terminal disposition is distinct from pretending absent bytes were settled.\n receipt0:=jsonb_build_object(''''schema'''',''''quota-terminal-receipt/v1'''',''''tenant_id'''',t,''''reservation_id'''',q,''''resource_key'''',key0,''''client_key'''',client0,''''classification'''',classification0,''''old_state'''',x.state,''''original_