of(p->''''metadata_cut'''') IS DISTINCT FROM ''''array'''' OR jsonb_array_length(p->''''metadata_cut'''')<1 THEN RAISE EXCEPTION ''''Known-close full original inventory mismatch'''' USING ERRCODE=''''23514'''';END IF;\n IF EXISTS(SELECT 1 FROM public.large_import_quota_resources173 z WHERE z.tenant_id=t AND z.reservation_id=q AND z.state=''''released'''' AND NOT EXISTS(SELECT 1 FROM public.large_import_quota_terminal_receipts173 e WHERE(e.tenant_id,e.reservation_id,e.resource_key)=(z.tenant_id,z.reservation_id,z.resource_key))) THEN RAISE EXCEPTION ''''Released allocation lacks immutable native receipt'''' USING ERRCODE=''''23514'''';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q;\n inventory0:=encode(sha256(convert_to(proof0,''''UTF8'''')),''''hex'''');receipt0:=jsonb_build_object(''''schema'''',''''quota-known-close-receipt/v1'''',''''client_key'''',client0,''''tenant_id'''',t,''''reservation_id'''',q,''''request_id'''',b.request_id,''''inventory_sha256'''',inventory0,''''native_time'''',clock_timestamp());\n evidence0:=jsonb_build_object(''''schema'''',''''quota-known-close-evidence/v1'''',''''inventory_text'''',proof0,''''receipt'''',receipt0)::text;key0:=''''event:upload-known-close:''''||client0::text;\n IF octet_length(evidence0)>8388608 THEN RAISE EXCEPTION ''''Known-close evidence limit'''' USING ERRCODE=''''54000'''';END IF;\n SELECT coalesce(sum(byte_count) FILTER(WHERE kind=''''raw'''' AND state<>''''released''''),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>''''raw'''' AND state<>''''released''''),0) metadata_used,coalesce(sum(CASE WHEN state=''''released'''' THEN 0 WHEN kind=''''raw'''' THEN 1 ELSE 2 END),0) objects_used INTO charges FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;\n IF charges.raw_used>b.raw_ceiling OR charges.metadata_used+2::numeric*octet_length(evidence0)>b.metadata_ceiling OR charges.objects_used+2>b.objects_ceiling THEN RAISE EXCEPTION ''''Known-close evidence exceeds original ceiling'''' USING ERRCODE=''''54000'''';END IF;\n INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,''''event'''',octet_length(evidence0),encode(sha256(convert_to(evidence0,''''UTF8'''')),''''hex''''),''''settled'''',evidence0);\n UPDATE public.large_import_quota_reservations173 SET state=''''retained'''',outcome=''''ready'''',raw_charge=charges.raw_used,metadata_charge=charges.metadata_used+2::numeric*octet_length(evidence0),objects_charge=charges.objects_used+2,closed_at=clock_timestamp(),inventory_sha256=inventory0 WHERE tenant_id=t AND id=q RETURNING * INTO b;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n RETURN jsonb_build_object(''''reused'''',false,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''receipt'''',receipt0);\nEND $function$\n","volatility":"v","body_sha256":"c662f3f6d5e1cdfc86947172e1633c9c43c1224a7448c3726bff0e6dd1b4ffc8","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","client0","proof0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid, witness0 text, classification0 text","leakproof":false,"signature":"large_import_quota_terminal_finish173(uuid,uuid,uuid,text,text,uuid,text,text,uuid,text,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_terminal_finish173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid, witness0 text, classification0 text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE fact jsonb;b record